function createCrossFigureLogicState(result = null, supplementalFingerprint = '') {
    return {
        result,
        pendingResult: null,
        operation: null,
        status: result ? 'complete' : 'idle',
        progress: null,
        audit: { code: '', updatedAt: 0 },
        supplementalFingerprint: String(supplementalFingerprint || '').slice(0, 1000)
    };
}

function crossFigureMechanismOwnData(value, key) {
    if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
        return undefined;
    }
    try {
        const descriptor = Object.getOwnPropertyDescriptor(value, key);
        return descriptor && Object.hasOwn(descriptor, 'value')
            ? descriptor.value : undefined;
    } catch (_) {
        return undefined;
    }
}

function canonicalMechanismFingerprintValue(value, depth = 0, budget = { entries: 0 }) {
    if (value === null || typeof value === 'boolean') return value;
    if (typeof value === 'number') return Number.isFinite(value) ? value : null;
    if (typeof value === 'string') return value.normalize('NFKC').slice(0, 2000);
    if (depth >= 6 || budget.entries >= 4096) return null;
    if (Array.isArray(value)) {
        const result = [];
        for (let index = 0; index < Math.min(256, value.length); index += 1) {
            budget.entries += 1;
            result.push(canonicalMechanismFingerprintValue(
                crossFigureMechanismOwnData(value, String(index)), depth + 1, budget
            ));
        }
        return result;
    }
    if (!value || typeof value !== 'object') return null;
    let descriptors;
    try { descriptors = Object.getOwnPropertyDescriptors(value); } catch (_) { return null; }
    const result = {};
    Object.keys(descriptors).sort().slice(0, 128).forEach(key => {
        const descriptor = descriptors[key];
        if (!descriptor || !Object.hasOwn(descriptor, 'value') || budget.entries >= 4096) return;
        budget.entries += 1;
        result[key.slice(0, 160)] = canonicalMechanismFingerprintValue(
            descriptor.value, depth + 1, budget
        );
    });
    return result;
}

function mechanismChainFingerprint(chain) {
    const canonical = canonicalMechanismFingerprintValue({
        nodes: crossFigureMechanismOwnData(chain, 'nodes') || [],
        edges: crossFigureMechanismOwnData(chain, 'edges') || []
    });
    const digest = typeof SciLLM.stableHash === 'function'
        ? String(SciLLM.stableHash(canonical) || '').toLowerCase()
        : '00000000';
    return `mechanism-chain-v1-${digest.replace(/[^a-f0-9]/gu, '').slice(0, 64) || '00000000'}`;
}

function normalizeEvidenceFirstMechanismRequest(request, live) {
    const own = (value, key) => {
        if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
            return undefined;
        }
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) { return undefined; }
    };
    const invalid = () => {
        const error = new Error('MECHANISM_REQUEST_INVALID');
        error.code = 'MECHANISM_REQUEST_INVALID';
        throw error;
    };
    const suppliedVersions = own(request, 'evidenceFirstVersions');
    const evidenceFirstVersions = typeof SciLLM.normalizeEvidenceFirstVersions === 'function'
        ? SciLLM.normalizeEvidenceFirstVersions(suppliedVersions) : null;
    if (!evidenceFirstVersions) invalid();
    const normalized = {
        evidenceFirstVersion: own(request, 'evidenceFirstVersion'),
        evidenceFirstRouterVersion: own(request, 'evidenceFirstRouterVersion'),
        evidenceFirstVersions,
        operationId: own(request, 'operationId'),
        documentId: own(request, 'documentId'),
        workspaceId: own(request, 'workspaceId'),
        workspaceGeneration: own(request, 'workspaceGeneration'),
        workspaceLifecycle: own(request, 'workspaceLifecycle'),
        baseWorkspaceRevision: own(request, 'baseWorkspaceRevision'),
        mechanismChainFingerprint: own(request, 'mechanismChainFingerprint')
    };
    if (normalized.evidenceFirstVersion !== '2' ||
        normalized.evidenceFirstRouterVersion !== '2' ||
        typeof normalized.operationId !== 'string' ||
        !/^mechanism:[A-Za-z0-9:._-]{8,90}$/u.test(normalized.operationId) ||
        normalized.operationId.length > 100 ||
        typeof normalized.documentId !== 'string' || !normalized.documentId ||
        normalized.documentId.length > 1000 ||
        typeof normalized.workspaceId !== 'string' || !normalized.workspaceId ||
        normalized.workspaceId.length > 1000 ||
        !Number.isSafeInteger(normalized.workspaceGeneration) ||
        normalized.workspaceGeneration < 1 ||
        !Number.isSafeInteger(normalized.workspaceLifecycle) ||
        normalized.workspaceLifecycle < 0 ||
        !Number.isSafeInteger(normalized.baseWorkspaceRevision) ||
        normalized.baseWorkspaceRevision < 0 ||
        typeof normalized.mechanismChainFingerprint !== 'string' ||
        !/^mechanism-chain-v1-[a-f0-9]{8,64}$/u.test(
            normalized.mechanismChainFingerprint
        )) invalid();
    if (live !== undefined && live !== null) {
        for (const key of [
            'documentId', 'workspaceId', 'workspaceGeneration', 'workspaceLifecycle',
            'baseWorkspaceRevision', 'mechanismChainFingerprint'
        ]) {
            if (own(live, key) !== normalized[key]) invalid();
        }
    }
    return Object.freeze(normalized);
}

function buildEvidenceFirstMechanismBackgroundMessage(identity, documentPayload, figures) {
    const own = (value, key) => {
        if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
            return undefined;
        }
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) { return undefined; }
    };
    return Object.freeze({
        type: 'LLM_ANALYZE_CROSS_FIGURE_LOGIC',
        evidenceFirstVersion: '2',
        evidenceFirstRouterVersion: '2',
        evidenceFirstVersions: own(identity, 'evidenceFirstVersions'),
        operationId: own(identity, 'operationId'),
        documentId: own(identity, 'documentId'),
        workspaceId: own(identity, 'workspaceId'),
        baseWorkspaceRevision: own(identity, 'baseWorkspaceRevision'),
        workspaceGeneration: own(identity, 'workspaceGeneration'),
        workspaceLifecycle: own(identity, 'workspaceLifecycle'),
        mechanismChainFingerprint: own(identity, 'mechanismChainFingerprint'),
        document: documentPayload,
        figures
    });
}

function sameCrossFigureMechanismBinding(left, right) {
    if (!left || !right) return false;
    return [
        'documentId', 'workspaceId', 'workspaceGeneration', 'workspaceLifecycle',
        'baseWorkspaceRevision', 'mechanismChainFingerprint'
    ].every(key => crossFigureMechanismOwnData(left, key) ===
        crossFigureMechanismOwnData(right, key));
}

function isSeedableCrossFigureLogicResult(value) {
    const arrayKind = candidate => {
        try { return Array.isArray(candidate); } catch (_) { return null; }
    };
    if (!value || typeof value !== 'object' || arrayKind(value) !== false) return false;
    const edges = crossFigureMechanismOwnData(value, 'mechanismEdges');
    if (arrayKind(edges) !== true) return false;
    const edgeCount = crossFigureMechanismOwnData(edges, 'length');
    if (!Number.isSafeInteger(edgeCount) || edgeCount < 1 || edgeCount > 256) return false;
    for (let index = 0; index < edgeCount; index += 1) {
        const edge = crossFigureMechanismOwnData(edges, String(index));
        if (!edge || typeof edge !== 'object' || arrayKind(edge) !== false) return false;
        const from = crossFigureMechanismOwnData(edge, 'from');
        const to = crossFigureMechanismOwnData(edge, 'to');
        if (typeof from !== 'string' || !from.trim() || from.length > 240 ||
            typeof to !== 'string' || !to.trim() || to.length > 240) return false;
        const supportPanels = crossFigureMechanismOwnData(edge, 'supportPanels');
        if (supportPanels !== undefined) {
            if (arrayKind(supportPanels) !== true) return false;
            const panelCount = crossFigureMechanismOwnData(supportPanels, 'length');
            if (!Number.isSafeInteger(panelCount) || panelCount < 0 || panelCount > 64) {
                return false;
            }
            for (let panelIndex = 0; panelIndex < panelCount; panelIndex += 1) {
                const panel = crossFigureMechanismOwnData(supportPanels, String(panelIndex));
                if (typeof panel !== 'string' || !panel.trim() || panel.length > 200) return false;
            }
        }
    }
    return true;
}

function normalizeCrossFigureMechanismPendingPreview(value, expectedNodeDialect = '') {
    const arrayKind = candidate => {
        try { return Array.isArray(candidate); } catch (_) { return null; }
    };
    const rawEvidence = crossFigureMechanismOwnData(value, 'evidenceFirstMechanism');
    const evidenceFirstMechanism = typeof SciLLM.normalizeGeneratedMechanismPreview ===
        'function' ? SciLLM.normalizeGeneratedMechanismPreview(
            rawEvidence, expectedNodeDialect
        ) : null;
    const edges = crossFigureMechanismOwnData(value, 'mechanismEdges');
    const edgeCount = crossFigureMechanismOwnData(edges, 'length');
    const canonicalZeroEdgePreview = Boolean(evidenceFirstMechanism &&
        arrayKind(edges) === true && edgeCount === 0);
    if (!isSeedableCrossFigureLogicResult(value) && !canonicalZeroEdgePreview) return null;
    // crossFigureLogic.nodes describes the old Figure argument overview. In the
    // evidence-first dialect, biological node identity comes from the validated
    // canonical evidence, not those unrelated Figure rows.
    const overviewNodes = crossFigureMechanismOwnData(value, 'nodes');
    const overviewCount = overviewNodes === undefined ? 0
        : crossFigureMechanismOwnData(overviewNodes, 'length');
    if (overviewNodes !== undefined && (arrayKind(overviewNodes) !== true ||
        !Number.isSafeInteger(overviewCount) || overviewCount < 0 ||
        overviewCount > 128)) return null;
    const rawNodes = evidenceFirstMechanism
        ? evidenceFirstMechanism.nodes.map(node => ({ id: node.nodeId, label: node.label }))
        : overviewNodes;
    const rawNodeCount = rawNodes === undefined ? 0
        : crossFigureMechanismOwnData(rawNodes, 'length');
    if (rawNodes !== undefined && (arrayKind(rawNodes) !== true ||
        !Number.isSafeInteger(rawNodeCount) || rawNodeCount < 0 ||
        rawNodeCount > 128)) return null;
    const nodes = [];
    for (let index = 0; index < rawNodeCount; index += 1) {
        const raw = crossFigureMechanismOwnData(rawNodes, String(index));
        const id = crossFigureMechanismOwnData(raw, 'id');
        const label = crossFigureMechanismOwnData(raw, 'label');
        if (typeof id !== 'string' || !id.trim() || id.length > 160 ||
            (label !== undefined && (typeof label !== 'string' || label.length > 240))) {
            return null;
        }
        nodes.push({ id: id.trim(), ...(typeof label === 'string' ? { label: label.trim() } : {}) });
    }
    const mechanismEdges = [];
    for (let index = 0; index < edgeCount; index += 1) {
        const raw = crossFigureMechanismOwnData(edges, String(index));
        const from = crossFigureMechanismOwnData(raw, 'from');
        const to = crossFigureMechanismOwnData(raw, 'to');
        const rawLabel = crossFigureMechanismOwnData(raw, 'label');
        const rawRelation = crossFigureMechanismOwnData(raw, 'relation');
        const rawPolarity = crossFigureMechanismOwnData(raw, 'polarity');
        const supportRows = crossFigureMechanismOwnData(raw, 'supportPanels');
        const supportCount = supportRows === undefined ? 0
            : crossFigureMechanismOwnData(supportRows, 'length');
        const supportPanels = [];
        for (let panelIndex = 0; panelIndex < supportCount; panelIndex += 1) {
            supportPanels.push(String(crossFigureMechanismOwnData(
                supportRows, String(panelIndex)
            )).trim().slice(0, 200));
        }
        mechanismEdges.push({
            from: String(from).trim().slice(0, 240),
            to: String(to).trim().slice(0, 240),
            ...(typeof rawLabel === 'string' ? { label: rawLabel.trim().slice(0, 400) }
                : typeof rawRelation === 'string'
                    ? { relation: rawRelation.trim().slice(0, 400) } : {}),
            ...(['positive', 'negative', 'neutral'].includes(rawPolarity)
                ? { polarity: rawPolarity } : {}),
            ...(supportRows !== undefined ? { supportPanels } : {})
        });
    }
    if (rawEvidence !== undefined && !evidenceFirstMechanism) return null;
    return {
        ...(rawNodes !== undefined ? { nodes } : {}),
        mechanismEdges,
        ...(evidenceFirstMechanism ? { evidenceFirstMechanism } : {})
    };
}

function buildGeneratedMechanismV2WorkspaceMutation(result, operation) {
    const pendingPreview = normalizeCrossFigureMechanismPendingPreview(result, 'node-v2');
    const evidence = pendingPreview?.evidenceFirstMechanism;
    const binding = crossFigureMechanismOwnData(operation, 'binding');
    const operationId = crossFigureMechanismOwnData(operation, 'operationId');
    const operationEpoch = crossFigureMechanismOwnData(operation, 'epoch');
    if (!evidence || evidence.status !== 'complete' || !binding ||
        typeof operationId !== 'string' || !Number.isSafeInteger(operationEpoch) ||
        operationEpoch < 1 || evidence.nodes.length > 64) return null;
    const nodes = evidence.nodes.map(node => ({ id: node.nodeId, label: node.label }));
    const nodeIds = new Set(nodes.map(node => node.id));
    const edges = [];
    for (const relation of evidence.relations) {
        if (relation.relationStatus !== 'supported') continue;
        if (!nodeIds.has(relation.sourceNodeId) || !nodeIds.has(relation.targetNodeId) ||
            edges.length >= 64) return null;
        const evidenceByPanel = new Map();
        for (const assignment of relation.assignments) {
            const separator = assignment.panelKey.lastIndexOf(':');
            const figureId = separator > 0 ? assignment.panelKey.slice(0, separator) : '';
            const panelId = separator > 0 ? assignment.panelKey.slice(separator + 1) : '';
            if (!figureId || !panelId) return null;
            const key = `${figureId}\u0000${panelId}`;
            const prior = evidenceByPanel.get(key);
            if (!prior || (prior.evidenceClass === 'other' &&
                assignment.evidenceClass !== 'other')) {
                evidenceByPanel.set(key, {
                    figureId, panelId,
                    evidenceClass: assignment.role === 'counterclaim'
                        ? 'other' : assignment.evidenceClass,
                    evidenceClassSource: 'inferred'
                });
            }
        }
        const panelEvidence = [...evidenceByPanel.values()];
        if (panelEvidence.length > 32) return null;
        edges.push({
            id: relation.relationId,
            from: relation.sourceNodeId,
            to: relation.targetNodeId,
            label: '',
            polarity: relation.polarity === 'increases' ? 'positive'
                : relation.polarity === 'decreases' ? 'negative' : 'neutral',
            panelEvidence
        });
    }
    if (!edges.length) return null;
    const generationPayload = {
        status: 'complete', operationId, operationEpoch,
        evidenceFirstVersions: crossFigureMechanismOwnData(
            operation, 'evidenceFirstVersions'
        ),
        documentId: crossFigureMechanismOwnData(binding, 'documentId'),
        workspaceId: crossFigureMechanismOwnData(binding, 'workspaceId'),
        workspaceGeneration: crossFigureMechanismOwnData(
            binding, 'workspaceGeneration'
        ),
        workspaceLifecycle: crossFigureMechanismOwnData(binding, 'workspaceLifecycle'),
        baseWorkspaceRevision: crossFigureMechanismOwnData(
            binding, 'baseWorkspaceRevision'
        ),
        mechanismChainFingerprint: crossFigureMechanismOwnData(
            binding, 'mechanismChainFingerprint'
        ),
        evidenceFirstMechanism: evidence
    };
    const envelopeBuilder = typeof createMechanismGenerationCandidateEnvelope === 'function'
        ? createMechanismGenerationCandidateEnvelope
        : globalThis.SciLLM?.createMechanismGenerationCandidateEnvelope;
    const generationEnvelope = typeof envelopeBuilder === 'function'
        ? envelopeBuilder(JSON.stringify(generationPayload)) : '';
    if (!generationEnvelope) return null;
    return {
        type: 'replace_generated_mechanism_v2',
        expectedRevision: crossFigureMechanismOwnData(binding, 'baseWorkspaceRevision'),
        chain: { nodes, edges },
        generationEnvelope
    };
}

async function commitGeneratedMechanismV2ToWorkspace(input, dependencies = {}) {
    const source = input && typeof input === 'object' ? input : {};
    const suppliedProviderStatus = crossFigureMechanismOwnData(
        source, 'providerStatus'
    );
    const providerStatus = typeof suppliedProviderStatus === 'string'
        ? suppliedProviderStatus : 'failed';
    const previousResult = crossFigureMechanismOwnData(source, 'previousResult') || null;
    const result = crossFigureMechanismOwnData(source, 'result');
    const operation = crossFigureMechanismOwnData(source, 'operation');
    if (providerStatus !== 'complete') {
        return {
            success: false, status: providerStatus, code: '',
            result: previousResult, pendingResult: null
        };
    }
    const mutation = buildGeneratedMechanismV2WorkspaceMutation(
        result, operation
    );
    if (!mutation) {
        return {
            success: false, status: 'failed', code: 'INVALID_RESPONSE',
            result: previousResult, pendingResult: null
        };
    }
    const envelopeReader = typeof readMechanismGenerationEnvelope === 'function'
        ? readMechanismGenerationEnvelope
        : globalThis.SciLLM?.readMechanismGenerationEnvelope;
    const generation = typeof envelopeReader === 'function'
        ? envelopeReader(mutation.generationEnvelope) : null;
    if (!generation?.preview) {
        return {
            success: false, status: 'failed', code: 'INVALID_RESPONSE',
            result: previousResult, pendingResult: null
        };
    }
    const nodeLabels = new Map(mutation.chain.nodes.map(node => [node.id, node.label]));
    const pendingResult = {
        mechanismEdges: mutation.chain.edges.map(edge => ({
            from: nodeLabels.get(edge.from), to: nodeLabels.get(edge.to),
            label: edge.label, polarity: edge.polarity,
            supportPanels: edge.panelEvidence.map(item =>
                `${item.figureId}:${item.panelId}`)
        })),
        evidenceFirstMechanism: generation.preview
    };
    const binding = crossFigureMechanismOwnData(operation, 'binding');
    const captureBinding = typeof dependencies.captureBinding === 'function'
        ? dependencies.captureBinding : captureEvidenceFirstMechanismBinding;
    const ensureController = typeof dependencies.ensureController === 'function'
        ? dependencies.ensureController : ensureFigureWorkspaceDraftController;
    const getActiveController = typeof dependencies.getActiveController === 'function'
        ? dependencies.getActiveController : () => figureWorkspaceDraftController;
    const getLifecycle = typeof dependencies.getLifecycle === 'function'
        ? dependencies.getLifecycle : () => articleWorkspaceLifecycleGeneration;
    const commitController = typeof dependencies.commitController === 'function'
        ? dependencies.commitController : controller => {
            figureWorkspaceDraft = controller.getDraft();
            figureWorkspaceDraftCheckpoint = controller.getCheckpoint();
            figureWorkspaceDraftDirty = controller.isDirty();
        };
    if (!sameCrossFigureMechanismBinding(binding, captureBinding()) ||
        getLifecycle() !== binding.workspaceLifecycle) {
        return {
            success: false, status: 'revision_conflict',
            code: 'MECHANISM_REVISION_CONFLICT', result: previousResult, pendingResult
        };
    }
    try {
        const controller = await ensureController();
        if (getActiveController() !== controller ||
            !sameCrossFigureMechanismBinding(binding, captureBinding()) ||
            getLifecycle() !== binding.workspaceLifecycle) {
            return {
                success: false, status: 'revision_conflict',
                code: 'MECHANISM_REVISION_CONFLICT', result: previousResult,
                pendingResult
            };
        }
        const response = await controller.mutate(mutation, Date.now());
        if (crossFigureMechanismOwnData(response, 'stale') === true ||
            getActiveController() !== controller ||
            getLifecycle() !== binding.workspaceLifecycle) {
            return {
                success: false, status: 'revision_conflict',
                code: 'MECHANISM_REVISION_CONFLICT', result: previousResult,
                pendingResult,
                // controller.mutate returns only after its persistence promise
                // has acknowledged the exact CAS. A later lifecycle change can
                // suppress projection into this realm, but cannot undo that
                // authoritative workspace commit.
                durableWorkspaceCommitted: true
            };
        }
        commitController(controller);
        return {
            success: true, status: 'complete', code: '',
            result: pendingResult, pendingResult: null, response
        };
    } catch (error) {
        const revisionConflict = error?.code === 'FIGURE_WORKSPACE_REVISION_CONFLICT' ||
            error?.code === 'FIGURE_WORKSPACE_LIFECYCLE_CHANGED';
        return {
            success: false,
            status: revisionConflict ? 'revision_conflict' : 'failed',
            code: revisionConflict ? 'MECHANISM_REVISION_CONFLICT'
                : 'MECHANISM_WORKSPACE_COMMIT_FAILED',
            result: previousResult, pendingResult
        };
    }
}

function restoreCrossFigureMechanismState(value) {
    const source = value && typeof value === 'object' ? value : {};
    const result = normalizeCrossFigureMechanismPendingPreview(
        crossFigureMechanismOwnData(source, 'result')
    );
    const pendingResult = normalizeCrossFigureMechanismPendingPreview(
        crossFigureMechanismOwnData(source, 'pendingResult')
    );
    const suppliedStatus = crossFigureMechanismOwnData(source, 'status');
    const rawAudit = crossFigureMechanismOwnData(source, 'audit');
    const suppliedCode = crossFigureMechanismOwnData(rawAudit, 'code');
    const interruptedCommit =
        ['queued', 'working', 'retrying'].includes(suppliedStatus) &&
        suppliedCode === 'MECHANISM_COMMIT_PENDING';
    const status = interruptedCommit ? 'revision_conflict'
        : ['complete', 'needs_review', 'failed', 'cancelled',
            'revision_conflict'].includes(suppliedStatus) ? suppliedStatus
            : result ? 'complete' : 'idle';
    const safeCodes = new Set([
        '', 'MECHANISM_UNRESOLVED_EVIDENCE', 'MECHANISM_OPERATION_CANCELLED',
        'MECHANISM_REVISION_CONFLICT', 'MECHANISM_WORKSPACE_COMMIT_FAILED',
        'MECHANISM_COMMIT_INTERRUPTED', 'MECHANISM_PROVIDER_RECEIPT_AMBIGUOUS',
        'MECHANISM_PROVIDER_RECEIPT_MISMATCH',
        'MECHANISM_OPERATION_CAPACITY_EXCEEDED',
        'MECHANISM_DISPATCH_BINDING_UNAVAILABLE', 'MECHANISM_OPERATION_FINALIZED',
        'INVALID_RESPONSE', 'PROVIDER_UNAVAILABLE'
    ]);
    const suppliedFingerprint = crossFigureMechanismOwnData(
        source, 'supplementalFingerprint'
    );
    const base = createCrossFigureLogicState(
        result, typeof suppliedFingerprint === 'string' ? suppliedFingerprint : ''
    );
    const cleanupIntents = typeof normalizeCrossFigureMechanismCleanupIntents === 'function'
        ? normalizeCrossFigureMechanismCleanupIntents(
            crossFigureMechanismOwnData(source, 'cleanupIntents')
        ) : [];
    const suppliedUpdatedAt = crossFigureMechanismOwnData(rawAudit, 'updatedAt');
    const updatedAt = typeof suppliedUpdatedAt === 'number' &&
        Number.isFinite(suppliedUpdatedAt)
        ? Math.max(0, Math.min(4102444800000, Math.floor(suppliedUpdatedAt))) : 0;
    return {
        ...base,
        pendingResult,
        cleanupIntents,
        status: status === 'complete' && !result ? 'idle' : status,
        audit: {
            code: interruptedCommit ? 'MECHANISM_COMMIT_INTERRUPTED'
                : safeCodes.has(suppliedCode) ? suppliedCode : 'PROVIDER_UNAVAILABLE',
            updatedAt
        }
    };
}

function applyCrossFigureMechanismProgress(state, event, now = Date.now()) {
    const own = (value, key) => {
        if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
            return undefined;
        }
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) { return undefined; }
    };
    const allowedStages = new Set([
        'collecting_panel_evidence', 'canonicalizing_nodes',
        'mapping_claim_relations', 'assembling_graph',
        'repairing_unresolved', 'validating_final_result'
    ]);
    const operation = own(state, 'operation');
    const phase = own(event, 'phase');
    const operationId = own(event, 'operationId');
    const operationEpoch = own(event, 'operationEpoch');
    if (!operation || !allowedStages.has(phase) ||
        own(operation, 'cancelled') === true ||
        operationId !== own(operation, 'operationId') ||
        !Number.isSafeInteger(operationEpoch) || operationEpoch < 1 ||
        (own(operation, 'epoch') > 0 && own(operation, 'epoch') !== operationEpoch)) {
        return state;
    }
    const eventCompleted = Math.max(0, Math.min(4096, Math.floor(Number(
        own(event, 'completedPanels')
    ) || 0)));
    const eventTotal = Math.max(0, Math.min(4096, Math.floor(Number(
        own(event, 'totalPanels')
    ) || 0)));
    const previousProgress = own(state, 'progress');
    const previousSequenceValue = own(previousProgress, 'progressSequence');
    const previousSequence = Number.isSafeInteger(previousSequenceValue) &&
        previousSequenceValue >= 0 ? previousSequenceValue : 0;
    if (previousSequence >= 1_000_000) return state;
    const sameStage = own(previousProgress, 'stage') === phase;
    const previousCompleted = sameStage
        ? Math.max(0, Math.min(4096, Math.floor(Number(
            own(previousProgress, 'completed')
        ) || 0))) : 0;
    const previousTotal = sameStage
        ? Math.max(0, Math.min(4096, Math.floor(Number(
            own(previousProgress, 'total')
        ) || 0))) : 0;
    const completed = Math.max(previousCompleted,
        Math.min(eventCompleted, eventTotal || eventCompleted));
    const total = Math.max(previousTotal, eventTotal, completed);
    const timestamp = Math.max(0, Math.floor(Number(now) || 0));
    return {
        ...state,
        operation: { ...operation, epoch: operationEpoch },
        status: own(event, 'status') === 'retrying' ? 'retrying' : 'working',
        progress: {
            stage: phase,
            completed,
            total,
            elapsedSeconds: Math.max(0, Math.min(3600, Math.floor(
                Number(own(event, 'elapsedMs')) / 1000 ||
                (timestamp - Number(own(operation, 'startedAt') || timestamp)) / 1000
            ))),
            heartbeatAt: timestamp,
            progressSequence: previousSequence + 1
        },
        audit: { code: '', updatedAt: timestamp }
    };
}

function settleCrossFigureMechanismState(state, response, currentBinding, now = Date.now()) {
    const own = (value, key) => {
        if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
            return undefined;
        }
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) { return undefined; }
    };
    const operation = own(state, 'operation');
    const stage0 = own(response, 'evidenceFirstStage0');
    const operationId = own(stage0, 'operationId');
    const operationEpoch = own(stage0, 'operationEpoch');
    const operationVersions = SciLLM.normalizeEvidenceFirstVersions?.(
        own(operation, 'evidenceFirstVersions')
    );
    const stage0Versions = SciLLM.normalizeEvidenceFirstVersions?.(
        own(stage0, 'evidenceFirstVersions')
    );
    if (!operation || own(operation, 'cancelled') === true ||
        !operationVersions || !stage0Versions ||
        operationId !== own(operation, 'operationId') ||
        !Number.isSafeInteger(operationEpoch) || operationEpoch < 1 ||
        (own(operation, 'epoch') > 0 && own(operation, 'epoch') !== operationEpoch)) return state;
    const timestamp = Math.max(0, Math.floor(Number(now) || 0));
    const result = own(response, 'crossFigureLogic');
    const previewResult = typeof normalizeCrossFigureMechanismPendingPreview === 'function'
        ? normalizeCrossFigureMechanismPendingPreview(result, 'node-v2')
        : isSeedableCrossFigureLogicResult(result) ? result : null;
    const binding = own(operation, 'binding');
    const sameBinding = Boolean(binding && currentBinding && [
        'documentId', 'workspaceId', 'workspaceGeneration', 'workspaceLifecycle',
        'baseWorkspaceRevision', 'mechanismChainFingerprint'
    ].every(key => own(binding, key) === own(currentBinding, key)));
    if (!sameBinding) {
        return {
            ...state,
            pendingResult: previewResult,
            operation: { ...operation, epoch: operationEpoch },
            status: 'revision_conflict',
            audit: { code: 'MECHANISM_REVISION_CONFLICT', updatedAt: timestamp }
        };
    }
    const rawStatus = own(response, 'status');
    let status = ['complete', 'needs_review', 'failed', 'cancelled'].includes(rawStatus)
        ? rawStatus : 'failed';
    if (status === 'complete' && !previewResult) {
        status = 'failed';
    }
    const rawSuppliedCode = own(response, 'errorCode');
    const suppliedCode = typeof rawSuppliedCode === 'string'
        ? rawSuppliedCode.toUpperCase() : '';
    const safeCodes = new Set([
        'MECHANISM_UNRESOLVED_EVIDENCE', 'MECHANISM_OPERATION_CANCELLED',
        'MECHANISM_OPERATION_STALE', 'MECHANISM_OPERATION_DEADLINE_EXCEEDED',
        'MECHANISM_PROVIDER_REQUEST_BUDGET_EXCEEDED', 'MECHANISM_CHECKPOINT_INVALID',
        'MECHANISM_CHECKPOINT_READ_FAILED', 'MECHANISM_CHECKPOINT_WRITE_FAILED',
        'MECHANISM_RUN_STATE_READ_FAILED', 'MECHANISM_RUN_STATE_WRITE_FAILED',
        'MECHANISM_PROVIDER_RECEIPT_AMBIGUOUS',
        'MECHANISM_PROVIDER_RECEIPT_MISMATCH',
        'MECHANISM_OPERATION_CAPACITY_EXCEEDED',
        'MECHANISM_DISPATCH_BINDING_UNAVAILABLE', 'MECHANISM_OPERATION_FINALIZED',
        'INVALID_RESPONSE', 'OUTPUT_TRUNCATED', 'NETWORK_ERROR', 'RATE_LIMITED',
        'REQUEST_TIMEOUT', 'PROVIDER_UNAVAILABLE'
    ]);
    const code = rawStatus === 'complete' && status === 'failed'
        ? 'INVALID_RESPONSE'
        : safeCodes.has(suppliedCode) ? suppliedCode
        : status === 'needs_review' ? 'MECHANISM_UNRESOLVED_EVIDENCE'
            : status === 'cancelled' ? 'MECHANISM_OPERATION_CANCELLED'
                : status === 'failed' ? 'PROVIDER_UNAVAILABLE' : '';
    return {
        ...state,
        result: status === 'complete' ? previewResult : state.result,
        pendingResult: status === 'complete' ||
            (rawStatus === 'complete' && status === 'failed') ? null : previewResult,
        operation: { ...operation, epoch: operationEpoch, cancelled: status === 'cancelled' },
        status,
        audit: { code, updatedAt: timestamp }
    };
}

let crossFigureLogicState = createCrossFigureLogicState();
let articleLogicMapIndex = SciLLM.normalizeResearchLogicMapIndex?.() || {
    schemaVersion: 1,
    activeMapId: '',
    maps: []
};
const articleParagraphNotes = new Map();
let articleParagraphNoteMarkerManager = null;
let articleParagraphNoteMarkerSyncPending = false;
let articleParagraphNoteMarkerSyncGeneration = 0;
let articleParagraphNoteRevealPending = null;
let articleParagraphNoteProjectionCache = new WeakMap();
let articleChatState = {
    turns: [],
    loading: false,
    error: '',
    operationId: '',
    activeTurnId: '',
    coverage: null,
    memoryNeedsRebuild: false
};
let articleChatGeneration = 0;
let articleChatTurnSequence = 0;
let articleChatPumpPromise = null;
const articleChatMutationLocks = new Set();
let articleChatClearInFlight = false;
let reviewOutlinePromise = null;
let lastReviewOutline = null;
const standaloneReviewParagraphSummaries = new Map();
let reviewOutlineDepth = 'major';
let reviewOutlineStatus = createInitialReviewOutlineStatus();
let currentArticleStructure = null;
let activePdfSemanticNavigationContext = null;
let pdfSemanticFocusSequence = 0;
let articleStructureObserver = null;
let articleStructureReadinessNotifier = null;
let articleStructureRefreshTimer = null;
let articleStructureObservedRoots = new Set();
let articleStructureBoundaryRoots = new Map();
const extractionTrace = SciLLM.createExtractionTraceRecorder({ limit: 40 });
let lastSuccessfulExtraction = null;
let lastSuccessfulStructure = null;
const ARTICLE_EXTRACTION_CACHE_TTL_MS = 15000;
let articleExtractionCache = null;
let articleStructureLastMutationAt = 0;
let articleStructureChangeSequence = 0;
const articleStructureInternalRewriteRoots = new Set();
let manualPreparedContentSequence = -1;
let articleStructureWaiting = false;
let figureWorkspaceInventoryEpoch = 0;
let canonicalArticleSnapshotCache = null;
const articlePreindexScheduler = {
    url: '',
    generation: 0,
    leadingQueued: false,
    canonicalQueued: false,
    leadingComplete: false,
    canonicalComplete: false,
    leadingIndex: null,
    records: null
};
const articleSectionOutlines = new Map();
const articleNavigatorState = {
    activeTab: 'outline',
    depth: 'major',
    summariesVisible: false,
    expandedSectionIds: new Set(),
    analysisSectionSelection: new Map()
};
const DEFAULT_ANALYSIS_SECTION_KINDS = new Set([
    'abstract', 'main', 'article', 'introduction', 'results', 'discussion', 'conclusion'
]);

function defaultArticleAnalysisSectionSelection(sectionKind) {
    return DEFAULT_ANALYSIS_SECTION_KINDS.has(String(sectionKind || '').toLowerCase());
}

function deriveArticleAnalysisSelectionCustomized(analysisSectionSelection, sectionKinds) {
    if (!(analysisSectionSelection instanceof Map) || !(sectionKinds instanceof Map)) {
        return false;
    }
    return [...analysisSectionSelection].some(([sectionId, selected]) =>
        sectionKinds.has(sectionId) && selected !==
            defaultArticleAnalysisSectionSelection(sectionKinds.get(sectionId))
    );
}

function articleAnalysisSectionSelected(sectionId, sectionKind) {
    const key = String(sectionId || '');
    if (articleNavigatorState.analysisSectionSelection.has(key)) {
        return articleNavigatorState.analysisSectionSelection.get(key) === true;
    }
    return defaultArticleAnalysisSectionSelection(sectionKind);
}

function selectedArticleAnalysisParagraphIds(snapshot = getCanonicalArticleSnapshot()) {
    return new Set((Array.isArray(snapshot?.paragraphs) ? snapshot.paragraphs : [])
        .filter(paragraph => articleAnalysisSectionSelected(
            paragraph.sectionId,
            paragraph.sectionKind
        ))
        .flatMap(paragraph => [
            String(paragraph.paragraphId || ''),
            String(paragraph.sourceKey || '')
        ])
        .filter(Boolean));
}

function nativePdfAnalysisSectionKind(value, inheritedKind = '') {
    const title = String(value || '').normalize('NFKC').toLowerCase()
        .replace(/&/gu, ' and ').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    if (/\b(?:abstract|summary|highlights)\b|摘要/u.test(title)) return 'abstract';
    if (/\b(?:materials? and )?methods?\b|\bstar methods\b|方法/u.test(title)) {
        return 'methods';
    }
    if (/\bintroduction\b|引言|背景/u.test(title)) return 'introduction';
    if (/\bresults?\b|结果/u.test(title)) return 'results';
    if (/\bdiscussion\b|讨论/u.test(title)) return 'discussion';
    if (/\bconclusions?\b|结论/u.test(title)) return 'conclusion';
    if (/\breferences?\b|\bbibliograph/u.test(title)) return 'reference';
    if (/\b(?:resource availability|data availability|acknowledg|author contributions|declaration of interests|supplemental)\b/u.test(title)) return 'metadata';
    if (/\bdocument\b|正文|全文/u.test(title)) return 'main';
    if (/\bpreamble\b/u.test(title)) return 'front-matter';
    return inheritedKind;
}

function currentNativePdfSemanticAnalysisScope(
    context = currentNativePdfSemanticHighlightState().context,
    snapshot = getCanonicalArticleSnapshot()
) {
    const waiting = reasonCode => Object.freeze({
        status: 'waiting', reasonCode,
        identity: '', semanticParagraphIds: new Set(),
        canonicalParagraphIds: selectedArticleAnalysisParagraphIds(snapshot)
    });
    if (!context?.navigation || !context.documentHash ||
        !Number.isSafeInteger(Number(context.documentGeneration)) ||
        !Number.isSafeInteger(Number(context.revision)) ||
        !String(context.semanticCacheKey || '') ||
        !String(context.semanticProvenanceKey || '')) {
        return waiting('PDF_SEMANTIC_SCOPE_WAITING');
    }
    const canonicalParagraphIds = selectedArticleAnalysisParagraphIds(snapshot);
    const canonicalParagraphs = Array.isArray(snapshot?.paragraphs)
        ? snapshot.paragraphs : [];
    const normalizeTitle = value => String(value || '').normalize('NFKC')
        .toLowerCase().replace(/&/gu, ' and ').replace(/[^\p{L}\p{N}]+/gu, ' ')
        .trim();
    const inferKind = nativePdfAnalysisSectionKind;
    const canonicalSectionKinds = new Map();
    const canonicalSections = [];
    const canonicalSectionIds = new Set();
    const visitCanonical = (nodes, ancestorTitles = []) => {
        for (const node of Array.isArray(nodes) ? nodes : []) {
            const sectionId = String(node?.sectionId || '');
            const title = normalizeTitle(node?.title || node?.displayTitle);
            const level = Math.max(1, Number(node?.level) || ancestorTitles.length + 1);
            if (sectionId) {
                const inferredKind = inferKind(title);
                canonicalSections.push({ sectionId, title, level,
                    ancestorTitles: [...ancestorTitles],
                    sectionKind: inferredKind || String(node?.sectionKind || '') });
                canonicalSectionIds.add(sectionId);
                canonicalSectionKinds.set(sectionId,
                    inferredKind || String(node?.sectionKind || ''));
            }
            visitCanonical(node?.children, title ? [...ancestorTitles, title] : ancestorTitles);
        }
    };
    visitCanonical(snapshot?.structure?.nodes || snapshot?.nodes);
    for (const paragraph of canonicalParagraphs) {
        const canonicalSectionId = String(paragraph?.sectionId || '');
        if (canonicalSectionId && paragraph?.sectionKind) {
            if (!canonicalSectionKinds.has(canonicalSectionId)) {
                canonicalSectionKinds.set(canonicalSectionId, paragraph.sectionKind);
            }
        }
        if (canonicalSectionId && !canonicalSectionIds.has(canonicalSectionId)) {
            const title = normalizeTitle(
                paragraph?.sectionTitle || paragraph?.displaySectionTitle
            );
            canonicalSections.push({ sectionId: canonicalSectionId, title,
                level: Math.max(1, Number(paragraph?.headingLevel) || 1),
                ancestorTitles: [],
                sectionKind: inferKind(title) || String(paragraph?.sectionKind || '') });
            canonicalSectionIds.add(canonicalSectionId);
        }
    }
    const semanticProjection = typeof nativePdfAnalysisSectionProjection === 'function'
        ? nativePdfAnalysisSectionProjection() : null;
    if (semanticProjection) semanticProjection.kinds.forEach((kind, id) => {
        canonicalSectionKinds.set(id, kind);
        const section = canonicalSections.find(item => item.sectionId === id);
        if (section) section.sectionKind = kind;
        canonicalSectionIds.add(id);
    });
    const canonicalSelectionCustomized = deriveArticleAnalysisSelectionCustomized(
        articleNavigatorState.analysisSectionSelection, canonicalSectionKinds
    );
    const semanticSignatureCandidates = (title, level, ancestorTitles) => {
        const exact = canonicalSections.filter(section => section.title === title &&
            section.level === level &&
            section.ancestorTitles.length === ancestorTitles.length &&
            section.ancestorTitles.every((ancestor, index) =>
                ancestor === ancestorTitles[index]));
        if (exact.length === 1) return exact;
        const titleAndLevel = canonicalSections.filter(section =>
            section.title === title && section.level === level);
        if (titleAndLevel.length === 1) return titleAndLevel;
        const titleOnly = canonicalSections.filter(section => section.title === title);
        if (titleOnly.length === 1) return titleOnly;
        const inferredKind = inferKind(title);
        const kindMatches = inferredKind ? canonicalSections.filter(section =>
            inferKind(section.title) === inferredKind) : [];
        return kindMatches.length === 1 ? kindMatches : [];
    };
    const canonicalSelection = section => {
        if (!section) return undefined;
        if (articleNavigatorState.analysisSectionSelection.has(section.sectionId)) {
            return articleNavigatorState.analysisSectionSelection.get(section.sectionId) === true;
        }
        if (canonicalSelectionCustomized && !section.semanticOwned) return undefined;
        return defaultArticleAnalysisSectionSelection(section.sectionKind);
    };
    const semanticParagraphIds = new Set();
    const mappedCanonicalSectionIds = new Set();
    const visit = (section, inheritedSelection, ancestorTitles = []) => {
        const sectionId = String(section?.sectionId || '');
        const analysisSectionId = String(section?.analysisSectionId || '');
        const explicitId = analysisSectionId && articleNavigatorState.analysisSectionSelection.has(analysisSectionId)
            ? analysisSectionId : sectionId;
        const explicit = articleNavigatorState.analysisSectionSelection.has(explicitId)
            ? articleNavigatorState.analysisSectionSelection.get(explicitId) === true : undefined;
        const title = normalizeTitle(section?.title);
        const level = Math.max(1, Number(section?.level) || ancestorTitles.length + 1);
        const owned = semanticProjection?.bindings.get(sectionId);
        const candidates = semanticSignatureCandidates(title, level, ancestorTitles);
        const canonicalSection = owned
            ? { sectionId: owned.node.sectionId, semanticOwned: true,
                sectionKind: owned.node.sectionKind }
            : candidates.length === 1 ? candidates[0] : null;
        if (canonicalSection) mappedCanonicalSectionIds.add(canonicalSection.sectionId);
        let selected = explicit;
        if (selected === undefined) selected = canonicalSelection(canonicalSection);
        if (selected === undefined && inheritedSelection !== undefined) {
            selected = inheritedSelection;
        }
        if (selected === undefined && !canonicalSelectionCustomized) {
            const inferredKind = inferKind(title);
            if (inferredKind) selected = defaultArticleAnalysisSectionSelection(inferredKind);
        }
        const targets = Array.isArray(section?.paragraphTargets)
            ? section.paragraphTargets : [];
        if (selected === true) {
            targets.forEach(target => {
                const paragraphId = String(target?.paragraphId || '');
                if (paragraphId && !paragraphId.startsWith('pdf-page-')) {
                    semanticParagraphIds.add(paragraphId);
                }
            });
        }
        (Array.isArray(section?.children) ? section.children : [])
            .forEach(child => visit(child, selected,
                title ? [...ancestorTitles, title] : ancestorTitles));
    };
    (Array.isArray(context.navigation.sections) ? context.navigation.sections : [])
        .forEach(section => visit(section, undefined));
    const selectedCanonicalSectionIds = new Set(
        [...articleNavigatorState.analysisSectionSelection]
            .filter(([sectionId, selected]) => selected === true &&
                canonicalSectionIds.has(String(sectionId)))
            .map(([sectionId]) => String(sectionId))
    );
    if (!semanticProjection && canonicalParagraphIds.size > 0 && (
        semanticParagraphIds.size === 0 ||
        [...selectedCanonicalSectionIds].some(sectionId =>
            !mappedCanonicalSectionIds.has(sectionId))
    )) return waiting('PDF_SEMANTIC_SCOPE_UNMAPPED');
    const selectionIdentity = [...articleNavigatorState.analysisSectionSelection]
        .map(([sectionId, selected]) => `${String(sectionId)}:${selected === true ? 1 : 0}`)
        .sort().join('|');
    const identity = [context.documentHash, Number(context.documentGeneration),
        Number(context.revision), context.semanticCacheKey, context.semanticProvenanceKey,
        selectionIdentity, [...canonicalParagraphIds].sort().join(','),
        [...semanticParagraphIds].sort().join(',')].join('::');
    return Object.freeze({
        status: 'ready', reasonCode: '', identity, selectionIdentity,
        documentHash: context.documentHash,
        documentGeneration: Number(context.documentGeneration),
        revision: Number(context.revision),
        semanticCacheKey: context.semanticCacheKey,
        semanticProvenanceKey: context.semanticProvenanceKey,
        canonicalParagraphIds,
        semanticParagraphIds
    });
}

function filterParagraphsForArticleAnalysis(paragraphs = []) {
    // Navigation stores canonical section IDs; HTML extraction keeps its original
    // IDs for grounding and rendering. Join by source identity, never heading text.
    const canonical = typeof getCanonicalArticleSnapshot === 'function'
        ? getCanonicalArticleSnapshot()?.paragraphs : [];
    const sectionsBySource = new Map();
    for (const paragraph of Array.isArray(canonical) ? canonical : []) {
        const sourceKey = String(paragraph?.sourceKey || '');
        const sectionId = String(paragraph?.sectionId || '');
        if (!sourceKey || !sectionId) continue;
        if (!sectionsBySource.has(sourceKey)) sectionsBySource.set(sourceKey, new Set());
        sectionsBySource.get(sourceKey).add(sectionId);
    }
    return (Array.isArray(paragraphs) ? paragraphs : []).filter(paragraph => {
        const matches = sectionsBySource.get(String(paragraph.paragraphId || ''));
        if (matches?.size === 1) {
            const [canonicalSectionId] = matches;
            if (articleNavigatorState.analysisSectionSelection.has(canonicalSectionId)) {
                return articleNavigatorState.analysisSectionSelection.get(canonicalSectionId) === true;
            }
        }
        return articleAnalysisSectionSelected(paragraph.sectionId, paragraph.sectionKind);
    });
}

function setArticleAnalysisSectionSelection(sectionIds, selected) {
    const ids = (Array.isArray(sectionIds) ? sectionIds : [sectionIds])
        .map(String).filter(Boolean);
    ids.forEach(sectionId => {
        articleNavigatorState.analysisSectionSelection.set(sectionId, selected === true);
    });
    const allowedParagraphIds = selectedArticleAnalysisParagraphIds();
    const semanticAnalysisScope = currentNativePdfSemanticAnalysisScope();
    if (lastRegexHighlightRequest?.categories) {
        highlighter.applyHighlight(
            lastRegexHighlightRequest.categories,
            lastRegexHighlightRequest.mode || 'word',
            {
                allowedParagraphIds,
                semanticAnalysisScope,
                analysisModeId: lastRegexHighlightRequest.analysisModeId
            }
        );
    }
    if (lastLlmAnalysis?.rawAnalysis && Array.isArray(lastLlmAnalysis.paragraphs)) {
        renderLlmAnalysis(
            lastLlmAnalysis.rawAnalysis,
            lastLlmAnalysis.paragraphs,
            lastLlmAnalysis.threshold || 0.8,
            lastLlmAnalysis.extractionDiagnostics
        );
    }
    scheduleArticleWorkspaceArtifactsSave({ immediate: true });
    scheduleCurrentArticleArchiveSave();
    return {
        success: true,
        snapshot: buildArticleWorkspaceSnapshot(),
        // allowedParagraphIds includes both canonical IDs and raw aliases.
        selectedParagraphCount: getCanonicalArticleSnapshot().paragraphs.filter(paragraph =>
            articleAnalysisSectionSelected(paragraph.sectionId, paragraph.sectionKind)
        ).length
    };
}
