function throwFigureOperationBusy(requestedFigureId) {
    const active = figureOperationState.active;
    const activeLabel = active?.figureId || active?.mode || figureDepthAnalysisId || 'Figure';
    const error = new Error(`正在精读 ${activeLabel}，请完成后再分析 ${requestedFigureId}`);
    error.code = 'FIGURE_ANALYSIS_BUSY';
    error.requestedFigureId = requestedFigureId;
    error.activeFigureId = active?.figureId || figureDepthAnalysisId;
    error.activeOperationId = active?.operationId || '';
    throw error;
}

function buildCrossFigureMechanismControlMessage(operation, command) {
    const binding = crossFigureMechanismOwnData(operation, 'binding');
    const operationId = crossFigureMechanismOwnData(operation, 'operationId');
    const evidenceFirstVersions = crossFigureMechanismOwnData(
        operation, 'evidenceFirstVersions'
    );
    if (!binding || typeof binding !== 'object' ||
        typeof operationId !== 'string' || !operationId.startsWith('mechanism:') ||
        !['pause', 'resume', 'cancel', 'release', 'abandon', 'status'].includes(command)) {
        const error = new Error('MECHANISM_REQUEST_INVALID');
        error.code = 'MECHANISM_REQUEST_INVALID';
        throw error;
    }
    const versionKeys = [
        'evidenceSchemaVersion', 'canonicalSchemaVersion', 'idAlgorithmVersion',
        'normalizationVersion', 'promptVersion', 'cacheVersion'
    ];
    const normalizedVersions = Object.freeze(Object.fromEntries(
        versionKeys.map(key => [key, crossFigureMechanismOwnData(
            evidenceFirstVersions, key
        )])
    ));
    const profileSignature = crossFigureMechanismOwnData(
        operation, 'profileSignature'
    );
    return Object.freeze({
        type: 'LLM_CONTROL_OPERATION', operationScope: 'mechanism', command,
        operationId,
        evidenceFirstVersion: '2',
        evidenceFirstRouterVersion: '2',
        evidenceFirstVersions: normalizedVersions,
        documentId: crossFigureMechanismOwnData(binding, 'documentId'),
        workspaceId: crossFigureMechanismOwnData(binding, 'workspaceId'),
        workspaceGeneration: crossFigureMechanismOwnData(binding, 'workspaceGeneration'),
        workspaceLifecycle: crossFigureMechanismOwnData(binding, 'workspaceLifecycle'),
        baseWorkspaceRevision: crossFigureMechanismOwnData(
            binding, 'baseWorkspaceRevision'
        ),
        mechanismChainFingerprint: crossFigureMechanismOwnData(
            binding, 'mechanismChainFingerprint'
        ),
        ...(typeof profileSignature === 'string' && profileSignature.length <= 512
            ? { profileSignature } : {}),
        evidenceSchemaVersion: crossFigureMechanismOwnData(
            evidenceFirstVersions, 'evidenceSchemaVersion'
        ),
        canonicalSchemaVersion: crossFigureMechanismOwnData(
            evidenceFirstVersions, 'canonicalSchemaVersion'
        ),
        idAlgorithmVersion: crossFigureMechanismOwnData(
            evidenceFirstVersions, 'idAlgorithmVersion'
        ),
        normalizationVersion: crossFigureMechanismOwnData(
            evidenceFirstVersions, 'normalizationVersion'
        ),
        promptVersion: crossFigureMechanismOwnData(
            evidenceFirstVersions, 'promptVersion'
        ),
        cacheVersion: crossFigureMechanismOwnData(
            evidenceFirstVersions, 'cacheVersion'
        )
    });
}

function normalizeCrossFigureMechanismCleanupIntent(value) {
    const source = value && typeof value === 'object' ? value : {};
    const control = crossFigureMechanismOwnData(source, 'controlMessage');
    const version = crossFigureMechanismOwnData(source, 'version');
    if (version !== 'mechanism-cleanup-intent-v1' ||
        !control || typeof control !== 'object') return null;
    const own = key => crossFigureMechanismOwnData(control, key);
    const suppliedPhase = crossFigureMechanismOwnData(source, 'phase');
    const phase = suppliedPhase === undefined ? 'cleanup_ready' : suppliedPhase;
    const command = own('command');
    const operationId = own('operationId');
    const documentId = own('documentId');
    const workspaceId = own('workspaceId');
    const workspaceGeneration = own('workspaceGeneration');
    const workspaceLifecycle = own('workspaceLifecycle');
    const baseWorkspaceRevision = own('baseWorkspaceRevision');
    const mechanismChainFingerprint = own('mechanismChainFingerprint');
    const suppliedEvidenceFirstVersions = own('evidenceFirstVersions');
    const profileSignature = own('profileSignature');
    const versionKeys = [
        'evidenceSchemaVersion', 'canonicalSchemaVersion', 'idAlgorithmVersion',
        'normalizationVersion', 'promptVersion', 'cacheVersion'
    ];
    const safeText = input => typeof input === 'string' && input.length >= 1 &&
        input.length <= 256 && !/[\u0000-\u001f\u007f]/u.test(input);
    if (own('type') !== 'LLM_CONTROL_OPERATION' ||
        own('operationScope') !== 'mechanism' ||
        own('evidenceFirstVersion') !== '2' ||
        own('evidenceFirstRouterVersion') !== '2' ||
        !['commit_pending', 'cleanup_ready'].includes(phase) ||
        (phase === 'commit_pending' ? command !== 'status'
            : !['cancel', 'release', 'abandon'].includes(command)) ||
        !safeText(operationId) || !operationId.startsWith('mechanism:') ||
        !safeText(documentId) ||
        typeof workspaceId !== 'string' || !/^workspace:[a-f0-9]{64}$/u.test(workspaceId) ||
        !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
        !Number.isSafeInteger(workspaceLifecycle) || workspaceLifecycle < 0 ||
        !Number.isSafeInteger(baseWorkspaceRevision) || baseWorkspaceRevision < 0 ||
        !safeText(mechanismChainFingerprint) ||
        !suppliedEvidenceFirstVersions ||
        typeof suppliedEvidenceFirstVersions !== 'object' ||
        !versionKeys.every(key => safeText(own(key)) &&
            crossFigureMechanismOwnData(suppliedEvidenceFirstVersions, key) ===
                own(key)) ||
        (profileSignature !== undefined &&
            (typeof profileSignature !== 'string' || profileSignature.length > 512 ||
                /[\u0000-\u001f\u007f]/u.test(profileSignature)))) return null;
    const safeCode = input => typeof input === 'string' &&
        (/^[A-Z][A-Z0-9_]{0,99}$/u.test(input) || input === '') ? input : '';
    const primaryCode = safeCode(crossFigureMechanismOwnData(source, 'primaryCode'));
    const cleanupErrorCode = safeCode(
        crossFigureMechanismOwnData(source, 'cleanupErrorCode')
    );
    const controlMessage = Object.freeze({
        type: 'LLM_CONTROL_OPERATION', operationScope: 'mechanism', command,
        operationId,
        evidenceFirstVersion: '2', evidenceFirstRouterVersion: '2',
        evidenceFirstVersions: Object.freeze(Object.fromEntries(
            versionKeys.map(key => [key, own(key)])
        )),
        documentId, workspaceId, workspaceGeneration,
        workspaceLifecycle, baseWorkspaceRevision, mechanismChainFingerprint,
        ...(profileSignature !== undefined ? { profileSignature } : {}),
        evidenceSchemaVersion: own('evidenceSchemaVersion'),
        canonicalSchemaVersion: own('canonicalSchemaVersion'),
        idAlgorithmVersion: own('idAlgorithmVersion'),
        normalizationVersion: own('normalizationVersion'),
        promptVersion: own('promptVersion'),
        cacheVersion: own('cacheVersion')
    });
    const evidenceFirstVersions = Object.freeze(Object.fromEntries(
        versionKeys.map(key => [key, controlMessage[key]])
    ));
    const operation = Object.freeze({
        operationId,
        evidenceFirstVersions,
        epoch: 0,
        binding: Object.freeze({
            documentId, workspaceId, workspaceGeneration, workspaceLifecycle,
            baseWorkspaceRevision,
            mechanismChainFingerprint
        }),
        ...(profileSignature !== undefined ? { profileSignature } : {}),
        cancelled: command === 'cancel',
        commitResolutionPending: phase === 'commit_pending'
    });
    const portable = Object.freeze({
        version: 'mechanism-cleanup-intent-v1',
        phase,
        controlMessage,
        primaryCode,
        cleanupErrorCode
    });
    return Object.freeze({
        portable, controlMessage, operation, operationId, command,
        phase, primaryCode, cleanupErrorCode
    });
}

function normalizeCrossFigureMechanismCleanupIntents(value) {
    const records = Array.isArray(value) ? value.slice(0, 64) : [];
    const byOperationId = new Map();
    const conflicts = new Set();
    records.forEach(record => {
        const normalized = normalizeCrossFigureMechanismCleanupIntent(record);
        if (!normalized || conflicts.has(normalized.operationId)) return;
        const existing = byOperationId.get(normalized.operationId);
        if (!existing) {
            byOperationId.set(normalized.operationId, normalized);
            return;
        }
        if (JSON.stringify(existing.controlMessage) !==
            JSON.stringify(normalized.controlMessage)) {
            byOperationId.delete(normalized.operationId);
            conflicts.add(normalized.operationId);
        }
    });
    return [...byOperationId.values()].map(item => item.portable);
}

function serializeCrossFigureMechanismCleanupIntents(
    intents = crossFigureLogicCleanupIntents
) {
    const records = [];
    for (const intent of intents instanceof Map ? intents.values() : []) {
        if (records.length >= 64) break;
        if (intent?.cleanupPending === false) continue;
        const normalized = normalizeCrossFigureMechanismCleanupIntent({
            version: 'mechanism-cleanup-intent-v1',
            phase: intent?.phase,
            controlMessage: intent?.controlMessage,
            primaryCode: intent?.primaryCode,
            cleanupErrorCode: intent?.cleanupErrorCode
        });
        if (normalized) records.push(normalized.portable);
    }
    return records;
}

function hydrateCrossFigureMechanismCleanupIntents(
    value,
    intents = crossFigureLogicCleanupIntents,
    options = {}
) {
    const strict = options?.strict === true;
    const replace = options?.replace === true;
    const failInvalid = () => {
        const error = new Error('MECHANISM_CLEANUP_CHECKPOINT_INVALID');
        error.code = 'MECHANISM_CLEANUP_CHECKPOINT_INVALID';
        throw error;
    };
    if (strict && (!Array.isArray(value) || value.length > 64)) failInvalid();
    const source = Array.isArray(value) ? value.slice(0, 64) : [];
    if (strict) {
        const stagedById = new Map();
        for (const record of source) {
            const normalized = normalizeCrossFigureMechanismCleanupIntent(record);
            if (!normalized) failInvalid();
            const serialized = JSON.stringify(normalized.controlMessage);
            const existing = stagedById.get(normalized.operationId);
            if (existing && existing !== serialized) failInvalid();
            stagedById.set(normalized.operationId, serialized);
        }
    }
    const sourceCount = source.length;
    const normalizedRecords = normalizeCrossFigureMechanismCleanupIntents(value);
    if (strict && normalizedRecords.length !== sourceCount) failInvalid();
    if (replace) intents.clear();
    let restored = 0;
    let conflicts = 0;
    let capacityRejected = 0;
    normalizedRecords.forEach(record => {
        const normalized = normalizeCrossFigureMechanismCleanupIntent(record);
        if (!normalized) return;
        const existing = intents.get(normalized.operationId);
        if (existing && existing.serializedControl !==
            JSON.stringify(normalized.controlMessage)) {
            conflicts += 1;
            return;
        }
        if (existing) return;
        if (intents.size >= 64) {
            capacityRejected += 1;
            return;
        }
        intents.set(normalized.operationId, {
            operation: normalized.operation,
            operationId: normalized.operationId,
            phase: normalized.phase,
            command: normalized.command,
            controlMessage: normalized.controlMessage,
            serializedControl: JSON.stringify(normalized.controlMessage),
            primaryCode: normalized.primaryCode,
            cleanupPending: true,
            cleanupErrorCode: normalized.cleanupErrorCode,
            retryReady: true,
            promise: null
        });
        restored += 1;
    });
    return {
        restored,
        rejected: Math.max(0,
            sourceCount - normalizedRecords.length - conflicts
        ) + capacityRejected,
        conflicts
    };
}

function committedCrossFigureMechanismOperation(draft, dependencies = {}) {
    const source = draft && typeof draft === 'object' ? draft : {};
    const envelope = crossFigureMechanismOwnData(source, 'mechanismGeneration');
    if (typeof envelope !== 'string' || !envelope) return null;
    const readEnvelope = typeof dependencies.readEnvelope === 'function'
        ? dependencies.readEnvelope
        : globalThis.SciLLM?.readMechanismGenerationEnvelope;
    if (typeof readEnvelope !== 'function') return null;
    let generation = null;
    try {
        generation = readEnvelope(envelope);
    } catch (_) {
        return null;
    }
    if (!generation || crossFigureMechanismOwnData(generation, 'status') !== 'complete') {
        return null;
    }
    const identity = crossFigureMechanismOwnData(generation, 'identity');
    const evidenceFirstVersions = crossFigureMechanismOwnData(
        generation, 'evidenceFirstVersions'
    );
    const operationId = crossFigureMechanismOwnData(identity, 'operationId');
    const epoch = crossFigureMechanismOwnData(identity, 'operationEpoch');
    const documentId = crossFigureMechanismOwnData(identity, 'documentId');
    const workspaceId = crossFigureMechanismOwnData(identity, 'workspaceId');
    const workspaceGeneration = crossFigureMechanismOwnData(
        identity, 'workspaceGeneration'
    );
    const workspaceLifecycle = crossFigureMechanismOwnData(
        identity, 'workspaceLifecycle'
    );
    const baseWorkspaceRevision = crossFigureMechanismOwnData(
        identity, 'baseWorkspaceRevision'
    );
    const mechanismChainFingerprint = crossFigureMechanismOwnData(
        identity, 'mechanismChainFingerprint'
    );
    const committedWorkspaceRevision = crossFigureMechanismOwnData(
        generation, 'committedWorkspaceRevision'
    );
    const versionKeys = [
        'evidenceSchemaVersion', 'canonicalSchemaVersion', 'idAlgorithmVersion',
        'normalizationVersion', 'promptVersion', 'cacheVersion'
    ];
    const safeText = value => typeof value === 'string' && value.length >= 1 &&
        value.length <= 256 && !/[\u0000-\u001f\u007f]/u.test(value);
    if (!safeText(operationId) || !operationId.startsWith('mechanism:') ||
        !Number.isSafeInteger(epoch) || epoch < 1 || !safeText(documentId) ||
        typeof workspaceId !== 'string' ||
        !/^workspace:[a-f0-9]{64}$/u.test(workspaceId) ||
        !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
        !Number.isSafeInteger(workspaceLifecycle) || workspaceLifecycle < 0 ||
        !Number.isSafeInteger(baseWorkspaceRevision) || baseWorkspaceRevision < 0 ||
        !Number.isSafeInteger(committedWorkspaceRevision) ||
        committedWorkspaceRevision !== baseWorkspaceRevision + 1 ||
        !safeText(mechanismChainFingerprint) ||
        !evidenceFirstVersions || typeof evidenceFirstVersions !== 'object' ||
        !versionKeys.every(key => safeText(crossFigureMechanismOwnData(
            evidenceFirstVersions, key
        )))) return null;
    return Object.freeze({
        operationId,
        epoch,
        evidenceFirstVersions: Object.freeze(Object.fromEntries(
            versionKeys.map(key => [key, crossFigureMechanismOwnData(
                evidenceFirstVersions, key
            )])
        )),
        binding: Object.freeze({
            documentId, workspaceId, workspaceGeneration, workspaceLifecycle,
            baseWorkspaceRevision, mechanismChainFingerprint
        }),
        cancelled: false,
        terminalCommitted: true
    });
}

async function stageCrossFigureMechanismCommitPending(
    operation,
    dependencies = {}
) {
    const intents = dependencies.intents instanceof Map
        ? dependencies.intents : crossFigureLogicCleanupIntents;
    const operationId = crossFigureMechanismOwnData(operation, 'operationId');
    const pending = (code, intent = null) => {
        const safeCode = /^[A-Z][A-Z0-9_]{0,99}$/u.test(String(code || ''))
            ? String(code) : 'MECHANISM_CLEANUP_UNCONFIRMED';
        if (intent) {
            intent.cleanupPending = true;
            intent.cleanupErrorCode = safeCode;
            intent.retryReady = true;
            intent.promise = null;
            try {
                if (typeof scheduleArticleWorkspaceArtifactsSave === 'function') {
                    scheduleArticleWorkspaceArtifactsSave({ immediate: true });
                }
            } catch (_) {}
        }
        return {
            staged: false, commitPending: true, cleanupPending: true,
            cleanupErrorCode: safeCode
        };
    };
    let controlMessage;
    try {
        controlMessage = buildCrossFigureMechanismControlMessage(
            operation, 'status'
        );
    } catch (error) {
        return pending(error?.code || 'MECHANISM_REQUEST_INVALID');
    }
    const normalized = normalizeCrossFigureMechanismCleanupIntent({
        version: 'mechanism-cleanup-intent-v1',
        phase: 'commit_pending',
        controlMessage,
        primaryCode: '',
        cleanupErrorCode: ''
    });
    if (!normalized || normalized.operationId !== operationId) {
        return pending('MECHANISM_REQUEST_INVALID');
    }
    const serializedControl = JSON.stringify(normalized.controlMessage);
    let intent = intents.get(operationId) || null;
    if (intent && (intent.phase !== 'commit_pending' ||
        intent.command !== 'status' ||
        intent.serializedControl !== serializedControl)) {
        return pending('MECHANISM_CLEANUP_CONFLICT', intent);
    }
    if (intent?.promise && intent.retryReady !== true) return intent.promise;
    if (!intent && intents.size >= 64) {
        return pending('MECHANISM_CLEANUP_CAPACITY_EXCEEDED');
    }
    if (!intent) {
        intent = {
            operation,
            operationId,
            phase: 'commit_pending',
            command: 'status',
            controlMessage: normalized.controlMessage,
            serializedControl,
            primaryCode: '',
            cleanupPending: true,
            cleanupErrorCode: '',
            retryReady: false,
            promise: null
        };
        intents.set(operationId, intent);
    } else {
        intent.operation = operation;
        intent.cleanupPending = true;
        intent.cleanupErrorCode = '';
        intent.retryReady = false;
    }
    const records = () => {
        const portable = [];
        for (const candidate of intents.values()) {
            if (portable.length >= 64) break;
            if (candidate?.cleanupPending === false) continue;
            const item = normalizeCrossFigureMechanismCleanupIntent({
                version: 'mechanism-cleanup-intent-v1',
                phase: candidate?.phase,
                controlMessage: candidate?.controlMessage,
                primaryCode: candidate?.primaryCode,
                cleanupErrorCode: candidate?.cleanupErrorCode
            });
            if (item) portable.push(item.portable);
        }
        return portable;
    };
    const persistCleanupCheckpoint =
        typeof dependencies.persistCleanupCheckpoint === 'function'
            ? dependencies.persistCleanupCheckpoint
            : cleanupIntents => persistWorkspaceAssetCheckpoint(
                MECHANISM_CLEANUP_INTENTS_ASSET_PATH,
                { schemaVersion: 1, cleanupIntents },
                { force: true }
            );
    const work = (async () => {
        try {
            const receipt = await persistCleanupCheckpoint(records());
            if (crossFigureMechanismOwnData(receipt, 'saved') !== true) {
                return pending('MECHANISM_CLEANUP_CHECKPOINT_WRITE_FAILED', intent);
            }
            intent.promise = null;
            intent.retryReady = true;
            return {
                staged: true, commitPending: true, cleanupPending: true,
                cleanupErrorCode: ''
            };
        } catch (error) {
            return pending(
                error?.code || 'MECHANISM_CLEANUP_CHECKPOINT_WRITE_FAILED',
                intent
            );
        }
    })();
    intent.promise = work;
    return work;
}

async function finalizeCommittedCrossFigureMechanismOperation(
    operation,
    dependencies = {}
) {
    const intents = dependencies.intents instanceof Map
        ? dependencies.intents : crossFigureLogicCleanupIntents;
    const releasedOperationIds = dependencies.releasedOperationIds instanceof Set
        ? dependencies.releasedOperationIds
        : (typeof crossFigureLogicReleasedOperationIds !== 'undefined'
            ? crossFigureLogicReleasedOperationIds : null);
    const operationId = crossFigureMechanismOwnData(operation, 'operationId');
    const cleanupCommand = dependencies.cleanupCommand === 'abandon'
        ? 'abandon' : 'release';
    const pending = (code, intent = null) => {
        const safeCode = /^[A-Z][A-Z0-9_]{0,99}$/u.test(String(code || ''))
            ? String(code) : 'MECHANISM_CLEANUP_UNCONFIRMED';
        if (intent) {
            intent.cleanupPending = true;
            intent.cleanupErrorCode = safeCode;
            intent.retryReady = true;
            intent.promise = null;
            try {
                if (typeof scheduleArticleWorkspaceArtifactsSave === 'function') {
                    scheduleArticleWorkspaceArtifactsSave({ immediate: true });
                }
            } catch (_) {}
        }
        return {
            released: false,
            abandoned: false,
            cleanupPending: true,
            cleanupErrorCode: safeCode
        };
    };
    let controlMessage;
    try {
        controlMessage = buildCrossFigureMechanismControlMessage(
            operation, cleanupCommand
        );
    } catch (error) {
        return pending(error?.code || 'MECHANISM_REQUEST_INVALID');
    }
    const normalized = normalizeCrossFigureMechanismCleanupIntent({
        version: 'mechanism-cleanup-intent-v1',
        phase: 'cleanup_ready',
        controlMessage,
        primaryCode: '',
        cleanupErrorCode: ''
    });
    if (!normalized || normalized.operationId !== operationId) {
        return pending('MECHANISM_REQUEST_INVALID');
    }
    const serializedControl = JSON.stringify(normalized.controlMessage);
    let intent = intents.get(operationId) || null;
    if (intent && (intent.command !== cleanupCommand ||
        intent.serializedControl !== serializedControl)) {
        let serializedCommitPending = '';
        try {
            serializedCommitPending = JSON.stringify(
                buildCrossFigureMechanismControlMessage(operation, 'status')
            );
        } catch (_) {}
        const canResolvePending = intent.phase === 'commit_pending' &&
            intent.command === 'status' &&
            intent.serializedControl === serializedCommitPending;
        if (!canResolvePending) {
            return pending('MECHANISM_CLEANUP_CONFLICT', intent);
        }
    }
    if (intent?.promise && intent.retryReady !== true) return intent.promise;
    if (!intent && intents.size >= 64) {
        return pending('MECHANISM_CLEANUP_CAPACITY_EXCEEDED');
    }
    if (!intent) {
        intent = {
            operation,
            operationId,
            phase: 'cleanup_ready',
            command: cleanupCommand,
            controlMessage: normalized.controlMessage,
            serializedControl,
            primaryCode: '',
            cleanupPending: true,
            cleanupErrorCode: '',
            retryReady: false,
            promise: null
        };
        intents.set(operationId, intent);
    } else {
        intent.operation = operation;
        intent.phase = 'cleanup_ready';
        intent.command = cleanupCommand;
        intent.controlMessage = normalized.controlMessage;
        intent.serializedControl = serializedControl;
        intent.cleanupPending = true;
        intent.cleanupErrorCode = '';
        intent.retryReady = false;
    }
    const records = () => {
        const portable = [];
        for (const candidate of intents.values()) {
            if (portable.length >= 64) break;
            if (candidate?.cleanupPending === false) continue;
            const item = normalizeCrossFigureMechanismCleanupIntent({
                version: 'mechanism-cleanup-intent-v1',
                phase: candidate?.phase,
                controlMessage: candidate?.controlMessage,
                primaryCode: candidate?.primaryCode,
                cleanupErrorCode: candidate?.cleanupErrorCode
            });
            if (item) portable.push(item.portable);
        }
        return portable;
    };
    const persistCleanupCheckpoint =
        typeof dependencies.persistCleanupCheckpoint === 'function'
            ? dependencies.persistCleanupCheckpoint
            : cleanupIntents => persistWorkspaceAssetCheckpoint(
                MECHANISM_CLEANUP_INTENTS_ASSET_PATH,
                { schemaVersion: 1, cleanupIntents },
                { force: true }
            );
    const sendMessage = typeof dependencies.sendMessage === 'function'
        ? dependencies.sendMessage : message => chrome.runtime.sendMessage(message);
    const requireSaved = async cleanupIntents => {
        const receipt = await persistCleanupCheckpoint(cleanupIntents);
        if (crossFigureMechanismOwnData(receipt, 'saved') !== true) {
            const error = new Error('MECHANISM_CLEANUP_CHECKPOINT_WRITE_FAILED');
            error.code = 'MECHANISM_CLEANUP_CHECKPOINT_WRITE_FAILED';
            throw error;
        }
        return receipt;
    };
    const work = (async () => {
        try {
            // The non-empty dedicated checkpoint is the write-ahead boundary.
            // Never expose release to the coordinator before its exact replay
            // capability has a durable acknowledgement.
            await requireSaved(records());
            const response = await sendMessage(normalized.controlMessage);
            const data = crossFigureMechanismOwnData(response, 'data');
            const exactAck = crossFigureMechanismOwnData(response, 'success') === true &&
                crossFigureMechanismOwnData(data, 'operationId') === operationId;
            const cleanupAck = cleanupCommand === 'release'
                ? crossFigureMechanismOwnData(data, 'released') === true
                : crossFigureMechanismOwnData(data, 'abandoned') === true &&
                    crossFigureMechanismOwnData(data, 'compacted') === true &&
                    crossFigureMechanismOwnData(data, 'cleanupComplete') === true &&
                    crossFigureMechanismOwnData(data, 'released') !== true;
            if (!exactAck || !cleanupAck) {
                return pending('MECHANISM_CLEANUP_UNCONFIRMED', intent);
            }
            if (intents.get(operationId) !== intent) {
                return pending('MECHANISM_CLEANUP_CONFLICT', intent);
            }
            intents.delete(operationId);
            try {
                await requireSaved(records());
            } catch (error) {
                if (!intents.has(operationId)) intents.set(operationId, intent);
                return pending(
                    error?.code || 'MECHANISM_CLEANUP_CHECKPOINT_WRITE_FAILED',
                    intent
                );
            }
            intent.cleanupPending = false;
            intent.retryReady = false;
            intent.promise = null;
            if (releasedOperationIds && cleanupCommand === 'release') {
                while (releasedOperationIds.size >= 64) {
                    releasedOperationIds.delete(
                        releasedOperationIds.values().next().value
                    );
                }
                releasedOperationIds.add(operationId);
            }
            return cleanupCommand === 'release'
                ? { released: true, abandoned: false,
                    cleanupPending: false, cleanupErrorCode: '' }
                : { released: false, abandoned: true,
                    cleanupPending: false, cleanupErrorCode: '' };
        } catch (error) {
            return pending(error?.code || 'MECHANISM_CLEANUP_UNCONFIRMED', intent);
        }
    })();
    intent.promise = work;
    return work;
}

function queueCrossFigureMechanismCleanup(
    operation,
    command = 'cancel',
    options = {}
) {
    const operationId = crossFigureMechanismOwnData(operation, 'operationId');
    if (typeof operationId !== 'string' || !operationId.startsWith('mechanism:') ||
        command !== 'cancel') {
        const error = new Error('MECHANISM_REQUEST_INVALID');
        error.code = 'MECHANISM_REQUEST_INVALID';
        throw error;
    }
    const controlMessage = buildCrossFigureMechanismControlMessage(
        operation, command
    );
    const serializedControl = JSON.stringify(controlMessage);
    const scheduleCleanupPersistence = () => {
        try {
            if (typeof scheduleArticleWorkspaceArtifactsSave === 'function') {
                scheduleArticleWorkspaceArtifactsSave({ immediate: true });
            }
        } catch (_) {}
    };
    let intent = crossFigureLogicCleanupIntents.get(operationId) || null;
    if (intent && (intent.command !== command ||
        intent.serializedControl !== serializedControl)) {
        const error = new Error('MECHANISM_CLEANUP_CONFLICT');
        error.code = 'MECHANISM_CLEANUP_CONFLICT';
        throw error;
    }
    if (!intent && crossFigureLogicCleanupIntents.size >= 64) {
        const error = new Error('MECHANISM_CLEANUP_CAPACITY_EXCEEDED');
        error.code = 'MECHANISM_CLEANUP_CAPACITY_EXCEEDED';
        throw error;
    }
    if (!intent) {
        intent = {
            operation,
            operationId,
            command,
            controlMessage,
            serializedControl,
            primaryCode: String(options.primaryCode || ''),
            cleanupPending: true,
            cleanupErrorCode: '',
            retryReady: false,
            promise: null
        };
        crossFigureLogicCleanupIntents.set(operationId, intent);
        scheduleCleanupPersistence();
    }
    if (intent.promise && !intent.retryReady) return intent;
    const sendMessage = typeof options.sendMessage === 'function'
        ? options.sendMessage : message => chrome.runtime.sendMessage(message);
    const sleep = typeof options.sleep === 'function'
        ? options.sleep : delay => new Promise(resolve => setTimeout(resolve, delay));
    const maxAttempts = Math.max(1, Math.min(3,
        Math.floor(Number(options.maxAttempts) || 1)));
    intent.cleanupPending = true;
    intent.cleanupErrorCode = '';
    intent.retryReady = false;
    const cleanupPromise = (async () => {
        let lastCode = '';
        for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
            try {
                const response = await sendMessage(controlMessage);
                const data = crossFigureMechanismOwnData(response, 'data');
                const exactOwner = crossFigureMechanismOwnData(
                    data, 'operationId'
                ) === operationId;
                const confirmed = command === 'cancel'
                    ? crossFigureMechanismOwnData(data, 'cancelled') === true
                    : crossFigureMechanismOwnData(data, 'released') === true;
                if (crossFigureMechanismOwnData(response, 'success') === true &&
                    exactOwner && confirmed) {
                    intent.cleanupPending = false;
                    intent.retryReady = false;
                    if (crossFigureLogicCleanupIntents.get(operationId) === intent) {
                        crossFigureLogicCleanupIntents.delete(operationId);
                        scheduleCleanupPersistence();
                    }
                    return {
                        released: command === 'release',
                        cancelled: command === 'cancel',
                        attempts: attempt
                    };
                }
                lastCode = String(crossFigureMechanismOwnData(
                    crossFigureMechanismOwnData(response, 'error'), 'code'
                ) || 'MECHANISM_CLEANUP_UNCONFIRMED');
            } catch (error) {
                lastCode = String(error?.code || 'MECHANISM_CLEANUP_UNCONFIRMED');
            }
            if (attempt < maxAttempts) await sleep(Math.min(250, attempt * 50));
        }
        intent.cleanupPending = true;
        intent.cleanupErrorCode = lastCode || 'MECHANISM_CLEANUP_UNCONFIRMED';
        intent.retryReady = true;
        scheduleCleanupPersistence();
        return {
            released: false,
            cancelled: false,
            pending: true,
            primaryCode: intent.primaryCode,
            cleanupErrorCode: intent.cleanupErrorCode,
            attempts: maxAttempts
        };
    })();
    intent.promise = cleanupPromise;
    return intent;
}

function createFigureOperationId(randomUUIDImpl = globalThis.crypto?.randomUUID?.bind(
    globalThis.crypto
)) {
    if (typeof randomUUIDImpl !== 'function') {
        const error = new Error('FIGURE_RANDOM_UNAVAILABLE');
        error.code = 'FIGURE_RANDOM_UNAVAILABLE';
        throw error;
    }
    let uuid = '';
    try {
        uuid = String(randomUUIDImpl()).toLowerCase();
    } catch (_) {
        uuid = '';
    }
    if (!/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/u
        .test(uuid)) {
        const error = new Error('FIGURE_RANDOM_UNAVAILABLE');
        error.code = 'FIGURE_RANDOM_UNAVAILABLE';
        throw error;
    }
    return `figure-${uuid}`;
}

function captureFigureSourceOwnerIdentity() {
    try {
        const metadata = articleWorkspaceMetadata();
        const canonicalUrl = SciLLM.normalizeWorkspaceCanonicalUrl(metadata.canonicalUrl);
        if (!canonicalUrl) return '';
        return JSON.stringify([canonicalUrl, SciLLM.normalizeWorkspaceDoi(metadata.doi, canonicalUrl)]);
    } catch (_) { return ''; }
}

function activeFigureSourceLease() {
    const operation = figureOperationState.active;
    const owned = operation && figureSourceLeaseAuthorities.get(operation);
    if (!owned || operation.sourceReadLease !== owned.lease) return null;
    const lease = owned.lease;
    const current = { operationId: operation.operationId, epoch: operation.generation,
        contentDocumentIdentity, navigationIdentity: contentNavigationIdentity(),
        workspaceLifecycle: articleWorkspaceLifecycleGeneration,
        documentId: currentManualDocument?.documentId,
        documentHash: currentManualDocument?.record?.documentHash,
        sourceOwnerIdentity: captureFigureSourceOwnerIdentity(),
        workspaceId: currentArticleWorkspace?.workspaceId,
        workspaceGeneration: Number(currentArticleWorkspace?.workspaceGeneration),
        workspaceContentHash: currentArticleWorkspace?.contentHash || '' };
    if (!SciLLM.figureSourceLeaseIdentityMatches(lease, current) ||
        owned.roots.some(root => !root.isConnected || root.ownerDocument !== document)) {
        operation.cancellationOrigin ||= 'article-source-changed';
        const error = articleWorkspaceLifecycleError();
        error.cancellationOrigin = operation.cancellationOrigin;
        throw error;
    }
    return lease;
}

function deferChangedFigureSourceRead() {
    const lease = activeFigureSourceLease();
    if (!lease || lease.structureSequence === articleStructureChangeSequence) return false;
    articleSourceRefreshDeferred = Object.freeze({ operationId: lease.operationId, epoch: lease.epoch,
        workspaceLifecycle: lease.workspaceLifecycle, structureSequence: articleStructureChangeSequence });
    const error = new Error('正文已更新，当前解图完成后刷新。');
    Object.assign(error, { code: 'ARTICLE_SOURCE_REFRESH_DEFERRED', deferred: true,
        operationId: lease.operationId, epoch: lease.epoch, workspaceLifecycle: lease.workspaceLifecycle });
    throw error;
}

function hasPendingFigureSourceRefresh() {
    const lease = activeFigureSourceLease();
    return Boolean(lease && lease.structureSequence !== articleStructureChangeSequence);
}

function isAdmittedFigureCleanupControlAsset(path, content) {
    if (path !== MECHANISM_CLEANUP_INTENTS_ASSET_PATH) return false;
    const lease = activeFigureSourceLease();
    const own = crossFigureMechanismOwnData;
    if (!lease || own(content, 'schemaVersion') !== 1 ||
        Object.keys(content).some(key => !['schemaVersion', 'cleanupIntents'].includes(key))) return false;
    const records = own(content, 'cleanupIntents');
    if (!Array.isArray(records) || records.length > 64) return false;
    const normalized = normalizeCrossFigureMechanismCleanupIntents(records);
    if (normalized.length !== records.length) return false;
    const current = [];
    for (const intent of crossFigureLogicCleanupIntents.values()) {
        if (intent?.cleanupPending === false) continue;
        const item = normalizeCrossFigureMechanismCleanupIntent({ version: 'mechanism-cleanup-intent-v1',
            phase: intent?.phase, controlMessage: intent?.controlMessage,
            primaryCode: intent?.primaryCode, cleanupErrorCode: intent?.cleanupErrorCode });
        if (!item || current.length >= 64) return false;
        current.push(item.portable);
    }
    if (JSON.stringify(normalized) !== JSON.stringify(current)) return false;
    return normalized.every(record => {
        const control = record.controlMessage;
        return control.documentId === lease.documentId && control.workspaceId === lease.workspaceId &&
            control.workspaceGeneration === lease.workspaceGeneration && control.workspaceLifecycle === lease.workspaceLifecycle;
    });
}

function rememberCoherentFigureSource(canonical) {
    if (activeNativePdfStructure()) return;
    if (manualPreparedContentSequence !== articleStructureChangeSequence ||
        manualPreparedHref !== effectiveArticlePageUrl() ||
        !currentManualDocument?.documentId || !currentArticleWorkspace?.workspaceId ||
        canonical.documentHash !== currentManualDocument.record?.documentHash) return;
    coherentArticleSourceForFigure = {
        data: SciLLM.cloneFigureSourceData({ canonicalSnapshot: canonical,
            documentId: currentManualDocument.documentId, documentHash: canonical.documentHash,
            sourceOwnerIdentity: captureFigureSourceOwnerIdentity(),
            workspaceId: currentArticleWorkspace.workspaceId,
            workspaceGeneration: Number(currentArticleWorkspace.workspaceGeneration),
            workspaceContentHash: currentArticleWorkspace.contentHash || '',
            contentDocumentIdentity, navigationIdentity: contentNavigationIdentity(),
            workspaceLifecycle: articleWorkspaceLifecycleGeneration,
            structureSequence: articleStructureChangeSequence,
            manualPreparedSequence: manualPreparedContentSequence }),
        roots: getArticleStructureObserveRoots().slice()
    };
}

async function prepareFigureSourceAdmission() {
    if (activeNativePdfStructure()) return;
    const source = coherentArticleSourceForFigure?.data;
    if (source && source.structureSequence === articleStructureChangeSequence &&
        source.workspaceLifecycle === articleWorkspaceLifecycleGeneration &&
        source.navigationIdentity === contentNavigationIdentity() &&
        source.contentDocumentIdentity === contentDocumentIdentity &&
        source.documentHash === currentManualDocument?.record?.documentHash &&
        source.sourceOwnerIdentity === captureFigureSourceOwnerIdentity() &&
        manualPreparedContentSequence === articleStructureChangeSequence) return;
    const lifecycle = articleWorkspaceLifecycleGeneration;
    await readArticleWorkspaceSnapshot({ forceRefresh: true });
    if (lifecycle !== articleWorkspaceLifecycleGeneration) throw Object.assign(
        new Error('正文已更新，请重新启动解图。'), { code: 'FIGURE_SOURCE_ADMISSION_UNSTABLE' });
}

function installFigureSourceLease(operation) {
    if (activeNativePdfStructure()) return;
    const source = coherentArticleSourceForFigure;
    if (!source || source.data.structureSequence !== articleStructureChangeSequence ||
        source.data.manualPreparedSequence !== manualPreparedContentSequence ||
        source.data.workspaceLifecycle !== articleWorkspaceLifecycleGeneration ||
        source.data.contentDocumentIdentity !== contentDocumentIdentity ||
        source.data.navigationIdentity !== contentNavigationIdentity() ||
        source.data.documentId !== currentManualDocument?.documentId ||
        source.data.documentHash !== currentManualDocument?.record?.documentHash ||
        source.data.sourceOwnerIdentity !== captureFigureSourceOwnerIdentity() ||
        source.data.workspaceId !== currentArticleWorkspace?.workspaceId ||
        source.data.workspaceGeneration !== Number(currentArticleWorkspace?.workspaceGeneration) ||
        source.data.workspaceContentHash !== (currentArticleWorkspace?.contentHash || '') ||
        source.roots.some(root => !root.isConnected || root.ownerDocument !== document)) {
        throw Object.assign(new Error('正文尚未稳定，请刷新文献后重新解图。'), { code: 'FIGURE_SOURCE_ADMISSION_UNSTABLE' });
    }
    const lease = SciLLM.createFigureCanonicalSourceLease({ ...source.data,
        operationId: operation.operationId, epoch: operation.generation });
    operation.sourceReadLease = lease;
    figureSourceLeaseAuthorities.set(operation, { lease, roots: source.roots.slice() });
}

function releaseFigureSourceLease(operation) {
    const owned = figureSourceLeaseAuthorities.get(operation);
    if (!owned || figureOperationState.active !== operation || operation.cleanupPending || operation.releasePending || operation.uncertainWrites?.size ||
        operation.runtimeTask && !operation.runtimeTask.snapshot().terminal) return false;
    const task = operation.runtimeTask?.snapshot();
    if (task?.terminal) {
        figureTerminalSourceReceipts.set(operation.operationId, SciLLM.cloneFigureSourceData({
            receiptOnly: true, task, contentDocumentIdentity: owned.lease.contentDocumentIdentity,
            navigationIdentity: owned.lease.navigationIdentity,
            cancellationOrigin: operation.cancellationOrigin || (operation.cancelled ? 'unknown' : '') }));
        while (figureTerminalSourceReceipts.size > 16) figureTerminalSourceReceipts.delete(figureTerminalSourceReceipts.keys().next().value);
    }
    figureSourceLeaseAuthorities.delete(operation);
    const pending = articleSourceRefreshDeferred;
    if (pending?.operationId !== operation.operationId || pending.epoch !== operation.generation) return true;
    articleSourceRefreshDeferred = null;
    queueMicrotask(() => {
        if (figureOperationState.active || contentNavigationIdentity() !== owned.lease.navigationIdentity ||
            contentDocumentIdentity !== owned.lease.contentDocumentIdentity) return;
        chrome.runtime.sendMessage({ type: 'ARTICLE_STRUCTURE_CHANGED',
            revision: Number(currentArticleStructure?.revision) || 1,
            paragraphCount: currentArticleStructure?.paragraphs?.length || 0,
            source: 'figure-source-terminal-refresh' }).catch(() => {});
    });
    return true;
}

function beginFigureOperation(mode, figureId = '', requestedOperationId = '', options = {}) {
    if (figureOperationState.active) throwFigureOperationBusy(figureId || mode);
    const generation = ++figureOperationState.generation;
    const operation = {
        operationId: /^figure-[a-f0-9-]{36}$/iu.test(requestedOperationId) ? requestedOperationId : createFigureOperationId(),
        generation,
        mode: mode === 'batch' ? 'batch' : 'single',
        figureId: sanitizeFigureProgressText(figureId, 80),
        workspaceLifecycle: articleWorkspaceLifecycleGeneration,
        userAuthorizedResume: options.userAuthorizedResume === true,
        paused: false,
        cancelled: false,
        waiters: [],
        requestOperationByFigure: new Map(),
        requestOperationIds: new Set()
    };
    if (typeof installFigureSourceLease === 'function') installFigureSourceLease(operation);
    figureOperationState.active = operation;
    figureOperationState.last = operation;
    return operation;
}

function initializeRuntimeFigureTask(operation, figures, depth = 'standard') {
    if (operation.runtimeTask) return operation.runtimeTask;
    operation.frozenPanelScopes = new Map();
    for(const figure of figures) {
        const resolved=SciLLM.resolveFigurePanelInventory?.(figure);
        const panels=resolved?.inventoryMatched ? resolved.panelHints : figure.panelHints || [];
        if(figure.sourceKind==='pdf-page-caption' || figure.pdfFigureContext?.route==='vision')continue;
        operation.frozenPanelScopes.set(figure.figureId,Object.freeze([...panels]));
        recordRuntimeFigureStage('expected',figure,panels,{operationId:operation.operationId,analysisDepth:depth});
    }
    const native=globalThis.__brevessNativePdfDocument;
    operation.runtimeTask=SciLLM.createRuntimeTaskContract({operationId:operation.operationId,
        epoch:operation.generation,module:'figures',documentId:contentDocumentIdentity,
        documentGeneration:native?.documentGeneration || 0,workspaceLifecycle:operation.workspaceLifecycle,
        scopeIds:figures.map(f=>f.figureId),inputSignature:hashArticleChatParagraphText(JSON.stringify(figures.map(f=>[f.figureId,buildFigureInputHash(f,f.analysisImages||[])]))),
        configSignature:depth});
    const task=operation.runtimeTask;
    task.apply(task.capture(),{status:'running',eventSequence:1});
    return task;
}

function markRuntimeFigureCommitted(figure) {
    const operation=figureOperationState.active, task=operation?.runtimeTask;
    if(!task || task.snapshot().terminal)return;
    assertCurrentArticleWorkspaceLifecycle(operation.workspaceLifecycle);
    if(operation.cancelled)throw cancelledOperationError();
    task.apply(task.capture(),{status:'saving',eventSequence:task.snapshot().eventSequence+1,committedIds:[figure.figureId]});
}

async function confirmRuntimeFigureRetained(
    operation, state, modelResult, depth, inputHash, visionAdmission, images
) {
    const task = operation?.runtimeTask;
    if (!task) return false;
    const token = task.capture();
    const figure = state?.figure;
    const figureId = String(figure?.figureId || '');
    const policySignature = visionAdmission?.figureReusePolicySignature;
    const modelFingerprint = JSON.stringify(modelResult);
    // Persistent JSON may reorder object keys; retain array order and every value.
    const stableValue = value => Array.isArray(value) ? value.map(stableValue)
        : value && typeof value === 'object' ? Object.fromEntries(
            Object.keys(value).sort().map(key => [key, stableValue(value[key])])) : value;
    const contentFingerprint = value => JSON.stringify(stableValue(value));
    const modelContentFingerprint = contentFingerprint(modelResult);
    const sourceExternal = figure?.sourceExternal === true;
    const materialId = String(figure?.sourceMaterialId || '');
    if (sourceExternal && !materialId) return false;
    const relativePath = sourceExternal
        ? SciLLM.supplementalFigureAssetPath(materialId) : 'figures/inventory.json';
    const workspace = currentArticleWorkspace && {
        workspaceId: currentArticleWorkspace.workspaceId,
        workspaceGeneration: currentArticleWorkspace.workspaceGeneration
    };
    if (!workspace?.workspaceId || !Number.isSafeInteger(workspace.workspaceGeneration) ||
        workspace.workspaceGeneration < 1 || !token.scopeIds.includes(figureId)) return false;
    const stale = () => Object.assign(new Error('FIGURE_RETAINED_RESULT_STALE'),
        { code: 'FIGURE_RETAINED_RESULT_STALE' });
    const assertCurrent = () => {
        if (!isCurrentFigureOperation(operation) || figureOperationState.active !== operation ||
            operation.runtimeTask !== task || task.snapshot().terminal) throw stale();
        assertCurrentArticleWorkspaceLifecycle(operation.workspaceLifecycle);
        task.assertCurrent(token);
        if (operation.cancelled || task.snapshot().cancelRequested) throw cancelledOperationError();
        if (operation.uncertainWrites?.size || operation.primaryError?.code === 'WRITE_OUTCOME_UNKNOWN' ||
            task.snapshot().status === 'outcome_unknown') {
            throw Object.assign(new Error('WRITE_OUTCOME_UNKNOWN'), { code: 'WRITE_OUTCOME_UNKNOWN' });
        }
        if (currentArticleWorkspace?.workspaceId !== workspace.workspaceId ||
            currentArticleWorkspace?.workspaceGeneration !== workspace.workspaceGeneration ||
            figureWalkthroughState.get(figureId) !== state || state.figure !== figure ||
            state[depth] !== modelResult || JSON.stringify(modelResult) !== modelFingerprint ||
            (figure.sourceExternal === true) !== sourceExternal ||
            String(figure.sourceMaterialId || '') !== materialId ||
            visionAdmission?.figureReusePolicySignature !== policySignature ||
            !SciLLM.figureResultMatchesInput(state, depth, inputHash) ||
            !SciLLM.figureResultMatchesPolicy(state, depth, policySignature) ||
            buildFigureInputHash(figure, images) !== inputHash) throw stale();
    };
    assertCurrent();
    const pendingField = depth === 'deep' ? 'pendingDeep' : 'pendingStandard';
    const modelField = depth === 'deep' ? 'modelDeep' : 'modelStandard';
    if (state.pendingResults?.[depth] || state.pendingResumeCheckpoints?.[depth] ||
        modelResult?.partial === true || modelResult?.panelCoverage?.missingPanels?.length ||
        modelResult?.panelCoverage?.unresolvedPanels?.length ||
        !isCompleteFigureAnalysisResult(modelResult, figure, depth)) return false;
    // Input pixels were prepared by this batch. Bind source now; reject changes during readback.
    const liveRevision = buildFigureLiveRetryRevision(figure);
    const asset = await getWorkspaceAssetCheckpoint(relativePath, {
        workspace, includeWorkspaceGeneration: true
    });
    assertCurrent();
    assertFigureRetryCommitBinding(state, inputHash, liveRevision, operation.workspaceLifecycle);
    if (asset?.writeOutcomeUnknown === true || asset?.error?.code === 'WRITE_OUTCOME_UNKNOWN') {
        throw Object.assign(new Error('WRITE_OUTCOME_UNKNOWN'), { code: 'WRITE_OUTCOME_UNKNOWN' });
    }
    if (!Number.isSafeInteger(asset?.revision) || asset.revision < 1 ||
        typeof asset.contentHash !== 'string' || !asset.contentHash ||
        asset.workspaceGeneration !== workspace.workspaceGeneration) return false;
    if (asset.workspaceId != null && asset.workspaceId !== workspace.workspaceId) return false;
    if (sourceExternal && asset.content?.materialId !== materialId) return false;
    const sourceIdentityFields = [
        'figureId', 'figureLabel', 'isSupplemental', 'identityRevision', 'originalFigureId', 'sourceMaterialId',
        'figureKind', 'figureSeries', 'sourceFingerprint', 'sourceDocumentFingerprint',
        'imageSha256', 'imageAssetPath', 'sourcePage', 'pageIndex', 'sourceMode',
        'parentWorkspaceId', 'parentWorkspaceGeneration', 'parentCanonicalUrl',
        'parentDocumentHash', 'sourceUrl'
    ];
    const sameSource = (saved, live) => sourceIdentityFields.every(field =>
        contentFingerprint(saved[field] ?? null) === contentFingerprint(live[field] ?? null)) &&
        ['captionBlocks', 'contextParagraphIds'].every(field =>
            contentFingerprint(saved[field] || []) === contentFingerprint(live[field] || [])) &&
        buildFigureInputHash(saved, images) === inputHash;
    // Root material identity is also binding when supplied by the saved schema.
    // Old single-row assets may omit these optional fields; omission does not
    // erase the row's own identity or the original workspace readback guard.
    if (sourceExternal && ['parentWorkspaceId', 'parentWorkspaceGeneration',
        'parentCanonicalUrl', 'parentDocumentHash', 'sourceUrl'].some(field =>
        Object.hasOwn(asset.content, field) && contentFingerprint(asset.content[field] ?? null) !==
            contentFingerprint(figure[field] ?? null))) return false;
    // Supplemental inventory is a projection: inspect the bound material.
    // Include rows bearing the original reader identity even if normalization
    // would move a tampered alias into another material/kind identity domain.
    const rawFigures = Array.isArray(asset.content?.figures) ? asset.content.figures : [];
    const originalFigureId = String(figure.originalFigureId || figureId);
    const rows = rawFigures.map(raw => ({ raw, saved: sourceExternal
        ? SciLLM.normalizeSupplementalFigure(raw, asset.content) : raw }));
    let matches = rows.filter(({ raw, saved }) => saved?.figureId === figureId ||
        (sourceExternal && (String(raw?.figureId || '') === figureId ||
            String(raw?.figureId || '') === originalFigureId ||
            String(raw?.originalFigureId || '') === originalFigureId)));
    if (!matches.length || matches.some(({ saved }) => !sameSource(saved, figure))) return false;
    if (matches.length > 1) {
        if (!sourceExternal) return false;
        const canonical = matches.filter(({ raw }) =>
            String(raw?.figureId || '').trim().slice(0, 200) === figureId);
        if (canonical.length !== 1) return false;
        const aliasFields = ['standard', 'modelStandard', 'deep', 'modelDeep',
            'pendingStandard', 'pendingDeep', 'pendingStandardCheckpointEnvelope',
            'pendingDeepCheckpointEnvelope', 'figureInputHash', 'figureResultInputHashes',
            'figureResultPolicySignatures', 'manualEdits', 'panelAnalyses', 'panelAnalysisErrors',
            'panelFollowups', 'panelFollowupHistories', 'panelFollowupErrors',
            'standardError', 'deepError', 'humanReviewed', 'editedAt'];
        const emptyAliasValue = value => value == null || value === '' || value === false || value === 0 ||
            (Array.isArray(value) ? value.length === 0 :
                typeof value === 'object' && Object.keys(value).length === 0);
        // Only a source-only alias is shadowed. An explicit blank human edit,
        // competing result, checkpoint or binding remains a refusal.
        if (matches.some(row => row !== canonical[0] && aliasFields.some(field =>
            !emptyAliasValue(row.saved[field])))) return false;
        matches = canonical;
    }
    const saved = matches[0].saved;
    const savedModel = saved[modelField] || saved[depth];
    if (state.pendingResults?.[depth] || state.pendingResumeCheckpoints?.[depth] ||
        saved[pendingField] || saved[`${pendingField}CheckpointEnvelope`] ||
        !isCompleteFigureAnalysisResult(savedModel, figure, depth) ||
        !SciLLM.figureResultMatchesInput(saved, depth, inputHash) ||
        !SciLLM.figureResultMatchesPolicy(saved, depth, policySignature) ||
        contentFingerprint(savedModel) !== modelContentFingerprint) return false;
    // No await after the final source/owner/save checks: retained is distinct from a new write.
    task.apply(token, { status: 'running', eventSequence: task.snapshot().eventSequence + 1,
        retainedIds: [figureId], retainedConfirmed: true });
    return true;
}

function isCurrentFigureOperation(operation) {
    const active = figureOperationState.active;
    const operationId = typeof operation === 'string'
        ? operation : operation?.operationId;
    const generation = typeof operation === 'object' ? operation?.generation : null;
    return Boolean(active && operationId && active.operationId === operationId &&
        (generation === null || active.generation === generation));
}

async function finishFigureOperation(operation, options = {}) {
    if (!isCurrentFigureOperation(operation)) return { released: false, stale: true };
    if (operation.releasePromise) return operation.releasePromise;
    const ownData = (target, key) => {
        if ((typeof target !== 'object' && typeof target !== 'function') ||
            target === null) return undefined;
        try {
            const descriptor = Object.getOwnPropertyDescriptor(target, key);
            return descriptor && Object.prototype.hasOwnProperty.call(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) {
            return undefined;
        }
    };
    const sendMessage = typeof options.sendMessage === 'function'
        ? options.sendMessage : message => chrome.runtime.sendMessage(message);
    const sleep = typeof options.sleep === 'function'
        ? options.sleep : delay => new Promise(resolve => setTimeout(resolve, delay));
    const maxAttempts = Math.max(1, Math.min(3,
        Math.floor(Number(options.maxAttempts) || 2)));
    const command = options.command === 'cancel' ||
        operation.cleanupCommand === 'cancel' ? 'cancel' : 'release';
    // An uncertain write must first be reconciled by its read-only receipt.
    // Releasing here would allow a new provider request to race that write.
    if (operation.uncertainWrites?.size || operation.primaryError?.code === 'WRITE_OUTCOME_UNKNOWN') {
        const task=operation.runtimeTask;
        if(task && !task.snapshot().terminal)task.apply(task.capture(),{status:'outcome_unknown',eventSequence:task.snapshot().eventSequence+1});
        return {released:false,pending:true,reason:'WRITE_OUTCOME_UNKNOWN'};
    }
    operation.cleanupCommand = command;
    const releaseOperationIds = [...new Set([
        operation.operationId,
        ...(operation.requestOperationIds instanceof Set ? operation.requestOperationIds : [])
    ])];
    operation.releasePending = true;
    operation.cleanupPending = true;
    const releasePromise = (async () => {
        let lastError = null;
        for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
            if (operation.cleanupCommand !== command) break;
            try {
                let released = false, cancelled = false;
                for (const releaseOperationId of releaseOperationIds) {
                    const response = await sendMessage({
                        type: 'LLM_CONTROL_OPERATION',
                        operationScope: 'figure',
                        operationId: releaseOperationId,
                        workspaceLifecycle: operation.workspaceLifecycle,
                        command
                    });
                    const data = ownData(response, 'data');
                    const operationReleased = ownData(data, 'released') === true;
                    const operationCancelled = ownData(data, 'cancelled') === true;
                    const cleanupComplete = ownData(data, 'cleanupComplete') === true;
                    const requestedCommand = ownData(data, 'requestedCommand');
                    const confirmed = command === 'cancel'
                        ? operationCancelled : operationReleased || operationCancelled;
                    if (ownData(response, 'success') !== true ||
                        ownData(data, 'operationId') !== releaseOperationId ||
                        !cleanupComplete || requestedCommand !== command ||
                        operation.cleanupCommand !== command || !confirmed) {
                        const responseError = ownData(response, 'error');
                        lastError = new Error(
                            ownData(responseError, 'message') ||
                            'FIGURE_OPERATION_RELEASE_UNCONFIRMED'
                        );
                        lastError.causeCode = ownData(responseError, 'code') || '';
                        throw lastError;
                    }
                    if (releaseOperationId === operation.operationId) {
                        released = operationReleased;
                        cancelled = operationCancelled;
                    }
                }
                operation.releasePending = false;
                operation.cleanupPending = false;
                delete operation.cleanupCommand;
                operation.waiters.splice(0).forEach(resolve => resolve());
                const task=operation.runtimeTask;
                if(task && !task.snapshot().terminal) {
                    if(operation.cancelled || command==='cancel') {
                        if(!task.snapshot().cancelRequested)task.requestCancel(task.capture());
                        task.confirmCancel(task.capture(),{success:true,cancelled:true});
                    } else {
                        const complete=!operation.primaryError && task.snapshot().completedUnits===task.snapshot().totalUnits;
                        task.apply(task.capture(),{status:'saving',eventSequence:task.snapshot().eventSequence+1});
                        task.apply(task.capture(),{status:complete?'completed':task.snapshot().completedUnits?'partial':'failed',eventSequence:task.snapshot().eventSequence+1,saveConfirmed:complete});
                    }
                }
                if (typeof releaseFigureSourceLease === 'function') releaseFigureSourceLease(operation);
                if (isCurrentFigureOperation(operation)) figureOperationState.active = null;
                return { released, cancelled, attempts: attempt };
            } catch (error) {
                lastError = error;
            }
            if (attempt < maxAttempts) await sleep(Math.min(250, attempt * 50));
        }
        const error = new Error('FIGURE_OPERATION_RELEASE_UNCONFIRMED');
        error.code = 'FIGURE_OPERATION_RELEASE_UNCONFIRMED';
        error.causeCode = String(ownData(lastError, 'causeCode') ||
            ownData(lastError, 'code') || '');
        if (operation.primaryError && typeof operation.primaryError === 'object') {
            operation.primaryError.cleanupPending = true;
            operation.primaryError.cleanupErrorCode = error.code;
            operation.primaryError.cleanupCauseCode = error.causeCode;
            return { released: false, pending: true, primaryErrorPreserved: true };
        }
        throw error;
    })();
    operation.releasePromise = releasePromise;
    try {
        return await releasePromise;
    } finally {
        if (operation.releasePromise === releasePromise) operation.releasePromise = null;
    }
}

function queueFigureOperationLifecycleCleanup(
    operation = figureOperationState.active
) {
    if (!operation || figureOperationState.active !== operation) return null;
    operation.cancelled = true;
    operation.tiffResources?.forEach(id=>cancelArticleContentExport(id));
    operation.paused = false;
    operation.cleanupCommand = 'cancel';
    operation.cleanupPending = true;
    operation.releasePending = true;
    operation.waiters?.splice(0).forEach(resolve => resolve());
    if (!operation.primaryError || typeof operation.primaryError !== 'object') {
        operation.primaryError = articleWorkspaceLifecycleError();
    }
    if (operation.lifecycleCleanupPromise) return operation;
    const cleanupPromise = Promise.resolve().then(() =>
        finishFigureOperation(operation, { command: 'cancel', maxAttempts: 2 })
    ).catch(error => {
        operation.cleanupPending = true;
        operation.releasePending = true;
        operation.primaryError.cleanupPending = true;
        operation.primaryError.cleanupErrorCode = String(
            error?.code || 'FIGURE_OPERATION_RELEASE_UNCONFIRMED'
        );
        return { released: false, pending: true, primaryErrorPreserved: true };
    });
    operation.lifecycleCleanupPromise = cleanupPromise;
    void cleanupPromise.then(result => {
        if (result?.pending === true &&
            operation.lifecycleCleanupPromise === cleanupPromise) {
            operation.lifecycleCleanupPromise = null;
        }
    });
    return operation;
}

async function recoverPendingFigureOperationRelease() {
    const operation = figureOperationState.active;
    if (operation?.releasePending && typeof operation.reconcileSourceWrites === 'function') {
        await operation.reconcileSourceWrites();
    }
    if (!operation?.releasePending) return { recovered: false };
    const result = await finishFigureOperation(operation, { maxAttempts: 3 });
    if (figureOperationState.active === operation || result?.pending === true) {
        const error = new Error('FIGURE_OPERATION_RELEASE_UNCONFIRMED');
        error.code = 'FIGURE_OPERATION_RELEASE_UNCONFIRMED';
        throw error;
    }
    return { recovered: true, ...result };
}

async function synchronizeFigureWorkspaceLifecycle() {
    const lifecycle = articleWorkspaceLifecycleGeneration;
    await recoverPendingFigureOperationRelease();
    if (!figureWorkspaceLifecycleSyncPromise) {
        const syncing = (async () => {
            while (figureWorkspaceLifecycleTransitions.length) {
                const transition = figureWorkspaceLifecycleTransitions[0];
                const response = await chrome.runtime.sendMessage({
                    type: 'LLM_ADVANCE_FIGURE_WORKSPACE_LIFECYCLE',
                    ...transition
                });
                if (response?.success !== true ||
                    response.data?.workspaceLifecycle !== transition.workspaceLifecycle) {
                    const error = new Error('FIGURE_WORKSPACE_LIFECYCLE_SYNC_FAILED');
                    error.code = 'FIGURE_WORKSPACE_LIFECYCLE_SYNC_FAILED';
                    throw error;
                }
                figureWorkspaceLifecycleTransitions.shift();
            }
        })();
        figureWorkspaceLifecycleSyncPromise = syncing;
        void syncing.finally(() => {
            if (figureWorkspaceLifecycleSyncPromise === syncing) {
                figureWorkspaceLifecycleSyncPromise = null;
            }
        }).catch(() => {});
    }
    await figureWorkspaceLifecycleSyncPromise;
    assertCurrentArticleWorkspaceLifecycle(lifecycle);
}

function captureSidebarRuntimeDocumentSource(operation) {
    const snapshot = getCanonicalArticleSnapshot();
    const structure = snapshot?.structure;
    const source = {
        sourceDocumentId: String((structure?.adapterId === 'pdf-native' ? structure.documentId : '') ||
            currentManualDocument?.documentId || lastPreparedStudy?.documentId || ''),
        sourceDocumentHash: String(snapshot?.documentHash || ''),
        contentDocumentIdentity,
        navigationIdentity: contentNavigationIdentity(),
        module: operation.module, operationId: operation.operationId,
        operationGeneration: operation.generation,
        documentGeneration: Number(globalThis.__brevessNativePdfDocument?.documentGeneration) || 0,
        workspaceLifecycle: operation.workspaceLifecycle
    };
    if (['sourceDocumentId', 'sourceDocumentHash', 'contentDocumentIdentity', 'navigationIdentity']
        .some(key => typeof source[key] !== 'string' || !source[key]) ||
        !Number.isSafeInteger(source.documentGeneration) || source.documentGeneration < 0) return null;
    return Object.freeze(source);
}

function isSidebarRuntimeDocumentSourceCurrent(operation) {
    const captured = operation?.sidebarDocumentSource;
    if (!captured || sidebarRuntimeDocumentSources.get(operation) !== captured ||
        operation !== analyzeArticleWithLLM.runtimeOperation ||
        operation.module !== 'highlights' || operation.generation !== llmOperationState.generation ||
        operation.workspaceLifecycle !== articleWorkspaceLifecycleGeneration) return false;
    const current = captureSidebarRuntimeDocumentSource(operation);
    return Boolean(current && Object.keys(captured).every(key => captured[key] === current[key]));
}

function bindSidebarRuntimeDocumentReceipt(operation, result, request) {
    const stale = () => ({ success: false, code: 'STALE_OPERATION' });
    if (!isSidebarRuntimeDocumentSourceCurrent(operation)) return stale();
    if (result?.success !== true) return result;
    const data = result.data, task = data?.task, source = operation.sidebarDocumentSource;
    if (!task || task.module !== source.module || task.operationId !== source.operationId ||
        data.operationId !== task.operationId || data.epoch !== task.epoch ||
        !Number.isSafeInteger(task.epoch) || task.epoch < 1 ||
        typeof task.documentId !== 'string' || !task.documentId.trim() ||
        task.documentGeneration !== source.documentGeneration || task.workspaceLifecycle !== source.workspaceLifecycle ||
        (request.epoch !== undefined && request.epoch !== task.epoch) ||
        (operation.epoch !== undefined && operation.epoch !== task.epoch)) return stale();
    const pinned = operation.sidebarDocumentReceipt;
    if (pinned && (pinned.backendDocumentId !== task.documentId || pinned.epoch !== task.epoch)) return stale();
    operation.sidebarDocumentReceipt ||= Object.freeze({ backendDocumentId: task.documentId, epoch: task.epoch });
    const { operationGeneration, ...capturedSource } = source;
    return { ...result, data: { ...data, sidebarDocumentBinding: Object.freeze({
        ...capturedSource, backendDocumentId: task.documentId, epoch: task.epoch
    }) } };
}

function beginLlmHighlightOperation(options = {}) {
    suppressSavedHtmlHighlightCheckpoint();
    restoredWorkspaceLlmTask = null;
    const generation = ++llmOperationState.generation;
    const operation = {
        operationId: /^highlight-[a-z0-9-]{8,100}$/iu.test(String(options.operationId || '')) ? options.operationId : `highlight-${generation}-${Date.now()}`,
        generation,
        module:'highlights',workspaceLifecycle:articleWorkspaceLifecycleGeneration,startedAt:Date.now(),
        paused: false,
        cancelled: false,
        waiters: []
    };
    operation.sidebarDocumentSource = captureSidebarRuntimeDocumentSource(operation);
    sidebarRuntimeDocumentSources.set(operation, operation.sidebarDocumentSource);
    llmOperationState.active = operation;
    analyzeArticleWithLLM.runtimeOperation = operation;
    return operation;
}

function finishLlmHighlightOperation(operation) {
    if (llmOperationState.active?.operationId !== operation?.operationId) return;
    operation.waiters.splice(0).forEach(resolve => resolve());
    llmOperationState.active = null;
    // Retain the bounded registry receipt for final status and stale-stop checks.
}

function cancelledOperationError() {
    const error = new Error('分析已取消，已完成结果会保留');
    error.code = 'CANCELLED';
    return error;
}

async function waitForLocalOperation(operation) {
    if (!operation || operation.cancelled) throw cancelledOperationError();
    if (operation.paused) {
        await new Promise(resolve => operation.waiters.push(resolve));
    }
    if (operation.cancelled) throw cancelledOperationError();
}

async function sendLlmOperationControlWithDeadline(operationOrId, command, timeoutMs = 1800) {
    const operationId = typeof operationOrId === 'object'
        ? String(operationOrId?.operationId || '') : String(operationOrId || '');
    const runtimeScoped = typeof operationOrId === 'object' && operationOrId.module === 'highlights';
    const figureScoped = typeof operationOrId === 'object' &&
        String(operationOrId?.operationId || '').startsWith('figure-');
    let timer = null;
    try {
        const response = await Promise.race([
            chrome.runtime.sendMessage({
                type: 'LLM_CONTROL_OPERATION',
                operationId,
                ...(figureScoped ? {
                    operationScope: 'figure',
                    workspaceLifecycle: Number(operationOrId.workspaceLifecycle)
                } : runtimeScoped ? {operationScope:'runtime',workspaceLifecycle:operationOrId.workspaceLifecycle,epoch:operationOrId.epoch} : {}),
                command
            }),
            new Promise(resolve => {
                timer = setTimeout(() => resolve({
                    success: true,
                    pending: true,
                    reason: 'CONTROL_CONFIRMATION_TIMEOUT'
                }), timeoutMs);
            })
        ]);
        return response || { success: true, pending: true };
    } catch (error) {
        return {
            success: true,
            pending: true,
            reason: 'CONTROL_CONFIRMATION_FAILED',
            error: error?.message || String(error)
        };
    } finally {
        if (timer !== null) clearTimeout(timer);
    }
}

async function controlLlmOperation(scope, command) {
    const operation = scope === 'figure'
        ? figureOperationState.active : llmOperationState.active;
    if (!operation) return { success: true, active: false };
    if (scope !== 'figure' && !operation.epoch) {
        const state = await queryContentRuntimeTask({module:'highlights',operationId:operation.operationId});
        if (state?.data?.task) operation.epoch=state.data.task.epoch;
    }
    if (command === 'pause') operation.paused = true;
    if (command === 'resume') {
        operation.paused = false;
        operation.waiters.splice(0).forEach(resolve => resolve());
    }
    if (command === 'cancel') {
        if (scope === 'figure') operation.cancellationOrigin ||= 'user-stop';
        operation.cancelled = true;
        operation.tiffResources?.forEach(id=>cancelArticleContentExport(id));
        operation.paused = false;
        operation.waiters.splice(0).forEach(resolve => resolve());
    }
    if (scope === 'figure') {
        if (command === 'cancel') {
            cancelPendingFigureProgress(figureWorkspaceInventory, {
                completedFigures: figureAnalysisStatus.completedFigures,
                errorCode: 'CANCELLED'
            });
        }
        updateFigureAnalysisStatus({
            paused: operation.paused,
            running: true,
            phase: operation.cancelled ? 'stopping' : operation.paused ? 'paused' : 'analyzing',
            operationId: operation.operationId,
            message: operation.cancelled
                ? '正在停止 Figure 解读，等待后台确认；已保存结果会保留。'
                : operation.paused
                    ? '已暂停；当前模型请求结束后不会继续发送新请求。'
                    : '已继续 Figure 解读。'
        });
    }
    const response = await sendLlmOperationControlWithDeadline(
        operation,
        command
    );
    if (!response?.success) {
        const error = new Error(response?.error?.message || '无法控制分析任务');
        error.code = response?.error?.code;
        throw error;
    }
    return { success: true, scope, command, operationId: operation.operationId,
        paused: operation.paused, cancelled: operation.cancelled, active: true,
        backendAcknowledged: response.pending !== true && response.data?.pending !== true,
        backendPendingReason: response.pending === true || response.data?.pending === true ? response.reason || response.data?.reason || 'STOP_CONFIRMATION_PENDING' : '' };
}

function throwStaleFigureOperation(operation) {
    const error = new Error('FIGURE_ANALYSIS_STALE');
    error.code = 'FIGURE_ANALYSIS_STALE';
    error.operationId = operation?.operationId || '';
    throw error;
}

function sanitizeFigureProgressText(value, maxLength = 160) {
    return String(value || '').normalize('NFKC').replace(/\s+/g, ' ').trim().slice(0, maxLength);
}

function sanitizeFigureProgressPanels(value) {
    return (Array.isArray(value) ? value : []).slice(0, 30)
        .map(item => sanitizeFigureProgressText(item, 20).toUpperCase())
        .filter(item => /^[A-Z0-9][A-Z0-9.+-]{0,7}$/.test(item));
}

function normalizeFigureRecoveryProgressFields(progress = {}) {
    const inputMode = sanitizeFigureProgressText(progress.inputMode, 40);
    const checkpointStatus = sanitizeFigureProgressText(progress.checkpointStatus, 40);
    return {
        missingPanels: sanitizeFigureProgressPanels(progress.missingPanels),
        unresolvedPanels: sanitizeFigureProgressPanels(progress.unresolvedPanels),
        inputMode: ['caption_context', 'figure_image', 'panel_crop'].includes(inputMode)
            ? inputMode : '',
        savedPanelCount: Math.max(0, Math.min(30,
            Math.floor(Number(progress.savedPanelCount) || 0))),
        validatedPanelCount: Math.max(0, Math.min(30,
            Math.floor(Number(progress.validatedPanelCount) || 0))),
        checkpointStatus: ['pending_save', 'saved', 'not_requested', 'save_failed']
            .includes(checkpointStatus) ? checkpointStatus : ''
    };
}

function translateFigureRecoveryText(value) {
    return SciLLM.translateInterfaceText?.(
        value, SciLLM.getInterfaceLanguage?.() || llmPresentationState.language || 'zh-CN'
    ) || String(value || '');
}

function formatFigureCoverageFailure(error = {}, figureLabel = 'Figure', savedPanelCount = 0) {
    const code = String(error?.code || '').toUpperCase();
    const validationMessages = {
        schema_shape: '返回结构不完整', title_length: '标题长度不符合要求',
        identity: '图号与请求不一致', panel_labels: 'Panel 标签不符合图注',
        empty_panel: 'Panel 内容为空', empty_overview: '整图概述为空',
        group_group_count: '证据分组数量不符合要求', group_empty_group: '证据分组为空',
        group_unknown_panel: '证据分组包含未知 Panel', group_overlap: 'Panel 存在重复分组',
        group_missing_panels: '证据分组遗漏 Panel',
        group_basis_missing: '证据分组缺少依据', group_basis_shape: '证据分组依据格式不完整',
        group_basis_panel_scope: '分组依据引用了组外 Panel', group_basis_source: '分组依据来源未能核实',
        group_basis_differences: '分组依据未正确说明条件差异'
    };
    if (code === 'INVALID_RESPONSE' && error.figureFailureStage === 'validation' &&
        Object.hasOwn(validationMessages, error.figureValidationIssue)) {
        const field = SciLLM.isFigureValidationField?.(error.figureValidationField)
            ? `（${error.figureValidationField}）` : '';
        const saved = Math.max(0, Math.min(30, Math.floor(Number(error.savedPanelCount ?? savedPanelCount) || 0)));
        return `${figureLabel || 'Figure'}：${translateFigureRecoveryText(validationMessages[error.figureValidationIssue])}${field}；` +
            `${translateFigureRecoveryText('已保存')} ${saved} ${translateFigureRecoveryText('个有效 Panel')}；` +
            translateFigureRecoveryText('整图仍待补全，可重试。');
    }
    const missingPanels = sanitizeFigureProgressPanels(
        error?.missingPanels || error?.unresolvedPanels
    );
    if (code === 'FIGURE_PANEL_COVERAGE_INCOMPLETE' || missingPanels.length) {
        const labels = missingPanels.length ? missingPanels.join('、') : '待核验项';
        return `${figureLabel || 'Figure'} ${translateFigureRecoveryText('尚缺 Panel')} ${labels}；` +
            `${translateFigureRecoveryText('已保存')} ${Math.max(
            0, Math.floor(Number(savedPanelCount) || 0)
        )} ${translateFigureRecoveryText('个有效 Panel，可仅重试缺失项。')}`;
    }
    const message = String(error?.message || '').trim();
    if (code === 'FIGURE_REQUEST_REPLAY_AMBIGUOUS') {
        const cause = /timed out/iu.test(message) ? '模型请求超时' :
            /unable to reach/iu.test(message) ? '连接模型服务时中断' :
            /rate limit/iu.test(message) ? '模型服务限制请求频率' :
            /temporarily unavailable/iu.test(message) ? '模型服务暂时不可用' :
            '上次请求的完成状态无法确认';
        return `${translateFigureRecoveryText(cause)}；` +
            translateFigureRecoveryText('已停止自动重发，已保存的结果仍保留。当前图需核验请求状态。');
    }
    if (/provider returned an invalid response/iu.test(message)) {
        const saved = Math.max(0, Math.floor(Number(error.savedPanelCount ?? savedPanelCount) || 0));
        return `${figureLabel || 'Figure'} ${translateFigureRecoveryText('返回结构未通过校验')}；` +
            (saved ? `${translateFigureRecoveryText('已保存')} ${saved} ${translateFigureRecoveryText('个有效 Panel，可仅重试缺失项。')}`
                : translateFigureRecoveryText('本次没有有效 Panel，可重试解读。'));
    }
    return message || `${figureLabel || 'Figure'} ${translateFigureRecoveryText('解读失败')}`;
}

function figureResponseError(response, fallback) {
    const error = new Error(response?.error?.message || fallback);
    error.code = response?.error?.code || fallback;
    const publicCauseCodes = new Set([
        'FIGURE_PANEL_SCOPE_CHANGED', 'FIGURE_PANEL_RETRY_SCOPE_STALE',
        'FIGURE_CHECKPOINT_BINDING_INVALID', 'FIGURE_CHECKPOINT_CONFLICT',
        'FIGURE_CHECKPOINT_STALE', 'FIGURE_CHECKPOINT_INVALID',
        'FIGURE_CHECKPOINT_TRANSPORT_UNAVAILABLE', 'FIGURE_WORKSPACE_MODEL_MERGE_STALE',
        'FIGURE_WORKSPACE_LIFECYCLE_CHANGED', 'ASSET_REVISION_CONFLICT',
        'ASSET_HASH_CONFLICT', 'WRITE_OUTCOME_UNKNOWN',
        'CHECKPOINT_TRANSPORT_FAILED', 'CHECKPOINT_REJECTED', 'CHECKPOINT_COUNT_MISMATCH',
        'NETWORK_ERROR', 'REQUEST_TIMEOUT', 'PROVIDER_UNAVAILABLE', 'RATE_LIMITED',
        'PROVIDER_COMPLETION_UNKNOWN'
    ]);
    if (['FIGURE_CHECKPOINT_PERSIST_FAILED', 'FIGURE_REQUEST_REPLAY_AMBIGUOUS'].includes(error.code) &&
        publicCauseCodes.has(response?.error?.causeCode)) error.causeCode = response.error.causeCode;
    if (error.code === 'FIGURE_REQUEST_REPLAY_AMBIGUOUS') {
        const fields = response.error;
        error.retryProvider = fields.retryProvider === false ? false : undefined;
        error.figureOutcome = ['unknown', 'response_uncommitted'].includes(fields.figureOutcome)
            ? fields.figureOutcome : '';
        error.failureScope = fields.failureScope === 'figure_target' ? 'figure_target' : 'global';
        error.canContinueIndependentTargets = fields.canContinueIndependentTargets === true;
        error.cleanupPending = fields.cleanupPending === true;
    }
    if (error.code === 'INVALID_RESPONSE' && response?.error?.figureFailureStage === 'validation') {
        error.figureFailureStage = 'validation';
        error.figureValidationIssue = response.error.figureValidationIssue;
        error.figureValidationField = response.error.figureValidationField;
        error.savedPanelCount = response.error.savedPanelCount;
    }
    error.notificationUsage = response?.error?.notificationUsage;
    error.notificationTask = response?.error?.notificationTask;
    return error;
}

function canApplyFigureFailure(state, lifecycle, error) {
    return lifecycle === articleWorkspaceLifecycleGeneration && Boolean(state) &&
        figureWalkthroughState.get(state.figure?.figureId) === state &&
        !['FIGURE_PANEL_RETRY_SCOPE_STALE', 'FIGURE_INPUT_CHANGED',
            'FIGURE_WORKSPACE_STALE', 'FIGURE_OPERATION_STALE'].includes(error?.code);
}

function sanitizeFigureProgressRoute(route) {
    if (!route || typeof route !== 'object') return null;
    return {
        taskType: sanitizeFigureProgressText(route.taskType, 40),
        requestedProfileId: sanitizeFigureProgressText(route.requestedProfileId, 100),
        effectiveProfileId: sanitizeFigureProgressText(route.effectiveProfileId, 100),
        effectiveProfileName: sanitizeFigureProgressText(route.effectiveProfileName, 120),
        name: sanitizeFigureProgressText(route.name, 120),
        providerId: sanitizeFigureProgressText(route.providerId, 80),
        model: sanitizeFigureProgressText(route.model, 160),
        capabilityMode: sanitizeFigureProgressText(route.capabilityMode, 40),
        fallbackReason: sanitizeFigureProgressText(route.fallbackReason, 160)
    };
}

function normalizeFigureProviderAttemptProgress(progress = {}) {
    const suppliedLimit = Number(progress.providerAttemptLimit);
    const providerAttemptLimit = Number.isFinite(suppliedLimit) && suppliedLimit > 0
        ? Math.max(1, Math.min(96, Math.floor(suppliedLimit))) : 0;
    const suppliedAttempt = Number(progress.providerAttempt);
    const providerAttempt = Number.isFinite(suppliedAttempt) && suppliedAttempt > 0
        ? Math.max(0, Math.min(
            providerAttemptLimit || 96,
            Math.floor(suppliedAttempt)
        )) : 0;
    return { providerAttempt, providerAttemptLimit };
}

function mergeFigureProviderAttemptProgress(previous = {}, patch = {}) {
    const prior = normalizeFigureProviderAttemptProgress(previous);
    const incoming = normalizeFigureProviderAttemptProgress(patch);
    const providerAttemptLimit = prior.providerAttemptLimit ||
        incoming.providerAttemptLimit;
    const providerAttempt = Math.min(
        providerAttemptLimit || 96,
        Math.max(prior.providerAttempt, incoming.providerAttempt)
    );
    return { providerAttempt, providerAttemptLimit };
}

function formatFigureProviderAttemptSuffix(progress = {}) {
    const suppliedLimit = Number(progress.providerAttemptLimit);
    const limit = Number.isFinite(suppliedLimit) && suppliedLimit > 0
        ? Math.max(1, Math.min(96, Math.floor(suppliedLimit))) : 0;
    const suppliedAttempt = Number(progress.providerAttempt);
    const attempt = Number.isFinite(suppliedAttempt) && suppliedAttempt > 0
        ? Math.max(0, Math.min(limit || 96, Math.floor(suppliedAttempt))) : 0;
    return attempt > 0 && limit > 0
        ? translateFigureRecoveryText(`（模型尝试 ${attempt}/${limit}）`)
        : '';
}

function sanitizeFigureProgressSnapshot(progress = {}) {
    const expectedPanels = sanitizeFigureProgressPanels(progress.expectedPanels);
    const startedAt = Math.max(0, Math.floor(Number(progress.startedAt) || 0)) || null;
    const terminal = progress.completed === true || progress.failed === true || progress.cancelled === true ||
        ['figure', 'failed', 'cancelled'].includes(progress.phase);
    const finishedAt = terminal ? Math.max(startedAt || 0,
        Number(progress.finishedAt) || Number(progress.updatedAt) || startedAt || 0) : null;
    const recognizedPanelCount = Number.isFinite(Number(progress.recognizedPanelCount))
        ? Math.max(0, Math.min(30, Math.floor(Number(progress.recognizedPanelCount))))
        : null;
    const batchRecognizedPanelCount = Number.isFinite(Number(progress.batchRecognizedPanelCount))
        ? Math.max(0, Math.min(30, Math.floor(Number(progress.batchRecognizedPanelCount))))
        : null;
    const unexpectedPanels = sanitizeFigureProgressPanels(progress.unexpectedPanels);
    const recovery = normalizeFigureRecoveryProgressFields(progress);
    const providerAttempts = normalizeFigureProviderAttemptProgress(progress);
    return {
        visionConfirmation: progress.phase==='figure_vision_confirmation' ? sanitizeFigureVisionConfirmation(progress.visionConfirmation) : null,
        figureId: sanitizeFigureProgressText(progress.figureId, 80),
        figureLabel: sanitizeFigureProgressText(progress.figureLabel, 120),
        expectedPanels,
        expectedPanelCount: Math.max(0, Math.min(30,
            Math.floor(Number(progress.expectedPanelCount) || expectedPanels.length))),
        recognizedPanelCount,
        batchRecognizedPanelCount,
        unexpectedPanels,
        ignoredUnexpectedPanelCount: Math.max(0, Math.min(30,
            Math.floor(Number(progress.ignoredUnexpectedPanelCount) || unexpectedPanels.length))),
        ...recovery,
        ...providerAttempts,
        panelBatchIndex: Math.max(0, Math.floor(Number(progress.panelBatchIndex) || 0)),
        completedPanelBatches: Math.max(0, Math.floor(Number(progress.completedPanelBatches) || 0)),
        totalPanelBatches: Math.max(0, Math.floor(Number(progress.totalPanelBatches) || 0)),
        phase: sanitizeFigureProgressText(progress.phase, 80) || 'preparing',
        running: progress.running === true,
        completed: progress.completed === true,
        failed: progress.failed === true,
        cancelled: progress.cancelled === true,
        operationId: sanitizeFigureProgressText(progress.operationId, 100),
        completedFigures: Math.max(0, Math.floor(Number(progress.completedFigures) || 0)),
        totalFigures: Math.max(0, Math.floor(Number(progress.totalFigures) || 0)),
        cacheHit: progress.cacheHit === true,
        visionFallback: progress.visionFallback === true,
        basis: sanitizeFigureProgressText(progress.basis, 80),
        attempt: Math.max(0, Math.floor(Number(progress.attempt) || 0)),
        waitMs: Math.max(0, Math.floor(Number(progress.waitMs) || 0)),
        errorCode: sanitizeFigureProgressText(progress.errorCode, 80),
        providerId: sanitizeFigureProgressText(progress.providerId, 80),
        model: sanitizeFigureProgressText(progress.model, 160),
        capabilityMode: sanitizeFigureProgressText(progress.capabilityMode, 40),
        route: sanitizeFigureProgressRoute(progress.route),
        startedAt,
        finishedAt,
        elapsedSeconds: startedAt ? Math.max(0, Math.floor(((finishedAt || Date.now()) - startedAt) / 1000)) : 0,
        updatedAt: Math.max(0, Math.floor(Number(progress.updatedAt) || 0)) || Date.now()
    };
}

function updateFigureProgress(figureId, patch = {}) {
    const normalizedId = sanitizeFigureProgressText(figureId || patch.figureId, 80);
    if (!normalizedId) return null;
    const previous = figureProgressById.get(normalizedId) || {};
    const requestedOperationId = sanitizeFigureProgressText(
        patch.operationId || previous.operationId || figureOperationState.active?.operationId,
        100
    );
    const activeRequestOperation = Boolean(patch.operationId &&
        figureOperationState.active?.requestOperationIds?.has(patch.operationId));
    if (patch.operationId && !isCurrentFigureOperation(patch.operationId) &&
        !activeRequestOperation) return null;
    const operationChanged = Boolean(patch.operationId) &&
        requestedOperationId !== sanitizeFigureProgressText(previous.operationId, 100);
    const operationPrevious = operationChanged ? {} : previous;
    const phase = sanitizeFigureProgressText(
        patch.phase || operationPrevious.phase, 80
    ) || 'preparing';
    const terminal = phase === 'figure' || phase === 'failed' || phase === 'cancelled';
    const restarting = !terminal && (patch.running === true || patch.resetStartedAt === true);
    const providerAttempts = mergeFigureProviderAttemptProgress(operationPrevious, patch);
    const next = sanitizeFigureProgressSnapshot({
        ...operationPrevious,
        ...patch,
        figureId: normalizedId,
        expectedPanels: patch.expectedPanels === undefined
            ? operationPrevious.expectedPanels : patch.expectedPanels,
        expectedPanelCount: patch.expectedPanelCount === undefined
            ? operationPrevious.expectedPanelCount : patch.expectedPanelCount,
        ...providerAttempts,
        finishedAt: terminal ? (!operationChanged && patch.resetStartedAt !== true &&
            operationPrevious.finishedAt || Date.now()) : null,
        startedAt: patch.resetStartedAt === true
            ? (patch.startedAt || Date.now())
            : (operationPrevious.startedAt || patch.startedAt || Date.now()),
        phase,
        operationId: requestedOperationId,
        running: patch.running === undefined ? !terminal : patch.running,
        completed: patch.completed === undefined
            ? (phase === 'figure' || (!restarting && operationPrevious.completed === true))
            : patch.completed,
        failed: patch.failed === undefined
            ? (phase === 'failed' || (!restarting && operationPrevious.failed === true))
            : patch.failed,
        cancelled: patch.cancelled === undefined
            ? (phase === 'cancelled' || (!restarting && operationPrevious.cancelled === true))
            : patch.cancelled,
        updatedAt: Date.now()
    });
    figureProgressById.set(normalizedId, next);
    return next;
}

function getFigureProgressSnapshot() {
    return [...figureProgressById.values()]
        .map(item => sanitizeFigureProgressSnapshot(item))
        .sort((left, right) => {
            const leftStarted = Number(left.startedAt) || 0;
            const rightStarted = Number(right.startedAt) || 0;
            return leftStarted - rightStarted || left.figureId.localeCompare(right.figureId);
        });
}

function formatFigureProgressMessage(progress = {}) {
    const label = progress.figureLabel || progress.figureId || 'Figure';
    if (progress.phase === 'source_preparation') return `${label}：来源待补齐；${progress.message || '重试来源准备后继续。'}`;
    const position = progress.totalFigures > 0
        ? `（${Math.min(progress.completedFigures + (progress.completed ? 0 : 1), progress.totalFigures)}/${progress.totalFigures}）`
        : '';
    const providerAttemptSuffix = formatFigureProviderAttemptSuffix(progress);
    if (progress.phase === 'figure_provider_attempt') {
        return `${label}${position}${providerAttemptSuffix}：正在调用模型。`;
    }
    if (progress.phase === 'caption_text_only') {
        return `${label}${position}：当前模型仅使用图注与正文证据。`;
    }
    if (progress.phase === 'figure_fallback') {
        return `${label}${position}：视觉输入未被接受，正回退到图注与正文。`;
    }
    if (progress.phase === 'figure_retry') {
        const seconds = Math.max(1, Math.ceil((Number(progress.waitMs) || 0) / 1000));
        return `${label}${position}：请求暂时失败，${seconds} 秒后自动重试。`;
    }
    if (progress.phase === 'token_limit_retry') return `${label}${position}：正在调整输出令牌上限后重试。`;
    if (progress.phase === 'output_token_retry') return `${label}${position}：正在增加输出令牌后重试。`;
    if (progress.phase === 'output_compact_retry') return `${label}${position}：输出过长，正改用紧凑 JSON 重试。`;
    if (progress.phase === 'figure_schema_retry') return `${label}${position}：返回结构不完整，正在按精确字段要求重试。`;
    if (progress.phase === 'figure_panel_schema_retry') return `${label}${position}：Panel 返回结构不完整，正在按精确字段要求重试。`;
    if (progress.phase === 'figure_panel_transient_retry') {
        const seconds = Math.max(1, Math.ceil((Number(progress.waitMs) || 0) / 1000));
        return `${label}${position}：Panel 请求暂时失败，${seconds} 秒后自动重试。`;
    }
    if (progress.phase === 'figure_compact_fallback') return `${label}${position}：整图结构连续不稳定，已切换为 Panel 提取后再综合。`;
    if (progress.phase === 'figure_panel_batch_complete') {
        const ignored = Number(progress.ignoredUnexpectedPanelCount) || 0;
        const ignoredNotice = ignored
            ? `，${translateFigureRecoveryText('已忽略模型重复返回的')} ${ignored} ` +
                `${translateFigureRecoveryText('个批次外 Panel')}`
            : '';
        return `${label}${position}：${translateFigureRecoveryText('当前 Panel 分批已保存，继续下一批')}` +
            `${ignoredNotice}`;
    }
    if (progress.phase === 'figure_panel_batch_pending' ||
        progress.phase === 'figure_panel_recovery_checkpoint_pending' ||
        progress.phase === 'figure_panel_recovery_batch_pending') {
        const key = progress.phase === 'figure_panel_batch_pending'
            ? '当前 Panel 分批已校验，正在保存'
            : progress.phase === 'figure_panel_recovery_checkpoint_pending'
                ? '已校验的 Panel 正在等待保存'
                : '缺失 Panel 批次已校验，正在保存';
        return `${label}${position}：${translateFigureRecoveryText(key)}。`;
    }
    if (progress.phase === 'figure_panel_recovery_checkpoint') {
        const missing = sanitizeFigureProgressPanels(progress.missingPanels);
        return `${label}${position}：${translateFigureRecoveryText('已保存')} ` +
            `${Number(progress.savedPanelCount) || 0} ${translateFigureRecoveryText('个 Panel')}` +
            `${missing.length ? `，${translateFigureRecoveryText('尚缺 Panel')} ${missing.join('、')}` : ''}。`;
    }
    if (progress.phase === 'figure_panel_recovery_batch_complete') {
        const unresolved = sanitizeFigureProgressPanels(progress.unresolvedPanels);
        return `${label}${position}：${translateFigureRecoveryText('缺失 Panel 批次已保存')} ` +
            `${Number(progress.savedPanelCount) || 0} ${translateFigureRecoveryText('个 Panel')}` +
            `${unresolved.length ? `，${translateFigureRecoveryText('尚不可识别 Panel')} ${unresolved.join('、')}` : ''}。`;
    }
    if (progress.phase === 'figure_synthesizing') {
        return `${label}${position}：Panel 已提取，正在综合整图证据链。`;
    }
    if (progress.phase === 'figure_synthesis_complete') {
        return `${label}${position}：整图证据链综合完成。`;
    }
    if (progress.phase === 'cancelled') {
        return `${label}${position}：Figure 解读已取消。`;
    }
    const phaseText = {
        preparing: '正在准备图片与上下文',
        figure_vision_confirmation: '等待确认是否继续文字解读',
        figure_requesting: '正在发送 Figure 请求',
        figure_inventory: '正在读取原图中的 Panel 标签',
        figure_inventory_ready: 'Panel 目录已核对，正在开始解读',
        figure_model_processing: '模型正在处理 Figure',
        figure_response_received: '已收到模型响应，等待校验',
        figure_validating: '正在校验返回结构',
        figure_assembling: '正在整理 Figure 解读',
        figure_panel_batch_pending: translateFigureRecoveryText('当前 Panel 分批已校验，正在保存'),
        figure_panel_batch_complete: translateFigureRecoveryText('当前 Panel 分批已保存，继续下一批'),
        figure_panel_recovery_started: translateFigureRecoveryText('正在仅请求缺失 Panel'),
        figure_panel_recovery_checkpoint_pending: translateFigureRecoveryText('已校验的 Panel 正在等待保存'),
        figure_panel_recovery_checkpoint: translateFigureRecoveryText('已保存有效 Panel，准备补齐缺失 Panel'),
        figure_panel_recovery_batch_pending: translateFigureRecoveryText('缺失 Panel 批次已校验，正在保存'),
        figure_panel_recovery_batch_complete: translateFigureRecoveryText('缺失 Panel 批次已保存'),
        figure_panel_recovery_complete: translateFigureRecoveryText('缺失 Panel 恢复完成'),
        figure_synthesizing: '正在综合整图证据链',
        figure_synthesis_complete: '整图证据链综合完成',
        provider_telemetry: '模型已返回，正在读取完成状态',
        figure_schema_retry: '正在修正模型返回结构',
        figure_panel_planning: '正在规划 Panel 证据输入',
        figure_panel_schema_retry: '正在修正 Panel 返回结构',
        figure_panel_transient_retry: 'Panel 请求暂时失败，正在等待重试',
        figure_panel_token_retry: '正在调整 Panel 输出令牌上限',
        figure_panel_output_retry: '正在增加 Panel 输出令牌上限',
        figure_panel_retry: '正在降低 Panel 输入容量',
        figure_panel_complete: 'Panel 解读已完成',
        figure_compact_fallback: '已切换为 Panel 提取后再综合',
        figure: '✓',
        failed: 'Figure 解读失败'
    }[progress.phase] || '正在处理 Figure';
    return `${label}${position}：${phaseText}。`;
}

function applyFigureProgressEvent(progress = {}) {
    const figureId = sanitizeFigureProgressText(progress.figureId, 80);
    if (!figureId) return null;
    const operationId = sanitizeFigureProgressText(progress.operationId, 100);
    const activeRequestOperation = Boolean(operationId &&
        figureOperationState.active?.requestOperationIds?.has(operationId));
    if ((operationId && !isCurrentFigureOperation(operationId) && !activeRequestOperation) ||
        (!operationId && figureOperationState.active)) return null;
    const phase = sanitizeFigureProgressText(progress.phase, 80) || 'preparing';
    if (figureAnalysisStatus.running === false &&
        ['completed', 'partial', 'failed', 'cancelled'].includes(figureAnalysisStatus.phase) &&
        !['figure', 'failed', 'cancelled'].includes(phase)) return null;
    const entry = updateFigureProgress(figureId, {
        ...progress,
        phase,
        running: phase !== 'figure' && phase !== 'failed' && phase !== 'cancelled',
        completed: phase === 'figure',
        failed: phase === 'failed',
        cancelled: phase === 'cancelled'
    });
    const entries = getFigureProgressSnapshot();
    const completedFigures = Math.max(
        Number(progress.completedFigures) || 0,
        entries.filter(item => item.completed).length
    );
    const failedFigures = entries.filter(item => item.failed).length;
    updateFigureAnalysisStatus({
        phase,
        currentFigure: Math.max(0, Math.min(
            Number(progress.totalFigures) || figureAnalysisStatus.totalFigures || entries.length,
            (Number(progress.completedFigures) || 0) + (phase === 'figure' ? 0 : 1)
        )),
        totalFigures: Number(progress.totalFigures) || figureAnalysisStatus.totalFigures || entries.length,
        completedFigures,
        failedFigures,
        figureLabel: entry.figureLabel,
        message: formatFigureProgressMessage(entry),
        route: entry.route,
        providerId: entry.providerId,
        model: entry.model,
        capabilityMode: entry.capabilityMode
    });
    return entry;
}

function updateFigureAnalysisStatus(patch = {}) {
    const activeRequestOperation = Boolean(patch.operationId &&
        figureOperationState.active?.requestOperationIds?.has(patch.operationId));
    if (patch.operationId && !isCurrentFigureOperation(patch.operationId) &&
        !activeRequestOperation) {
        return figureAnalysisStatus;
    }
    const nextOperationId = sanitizeFigureProgressText(
        patch.operationId || figureOperationState.active?.operationId ||
            figureAnalysisStatus.operationId,
        100
    );
    const sameOperation = !figureAnalysisStatus.operationId ||
        nextOperationId === figureAnalysisStatus.operationId;
    if (sameOperation && figureAnalysisStatus.running) {
        patch = {
            ...patch,
            ...(patch.currentFigure === undefined ? {} : {
                currentFigure: Math.max(
                    Number(figureAnalysisStatus.currentFigure) || 0,
                    Number(patch.currentFigure) || 0
                )
            }),
            ...(patch.completedFigures === undefined ? {} : {
                completedFigures: Math.max(
                    Number(figureAnalysisStatus.completedFigures) || 0,
                    Number(patch.completedFigures) || 0
                )
            })
        };
    }
    const nextFailures = Array.isArray(patch.failures)
        ? patch.failures.slice(-20).map(item => ({
            figureId: String(item?.figureId || '').slice(0, 120),
            figureLabel: String(item?.figureLabel || '').slice(0, 120),
            code: String(item?.code || 'FIGURE_FAILED').slice(0, 80),
            message: String(item?.message || 'Figure 解读失败').slice(0, 500)
        }))
        : figureAnalysisStatus.failures;
    figureAnalysisStatus = {
        ...figureAnalysisStatus,
        ...patch,
        operationId: sanitizeFigureProgressText(
            nextOperationId, 100
        ),
        failures: nextFailures,
        updatedAt: Date.now()
    };
    return figureAnalysisStatus;
}

function figureTerminationOwnerBinding(operation) {
    const workspace = currentArticleWorkspace;
    if (!operation || figureOperationState.last !== operation ||
        (figureOperationState.active && figureOperationState.active !== operation) ||
        operation.generation !== figureOperationState.generation ||
        operation.workspaceLifecycle !== articleWorkspaceLifecycleGeneration ||
        !/^workspace:[a-f0-9]{64}$/u.test(workspace?.workspaceId || '') ||
        !Number.isSafeInteger(workspace?.workspaceGeneration) || workspace.workspaceGeneration < 1) return null;
    return { operationId: operation.operationId, operationGeneration: operation.generation,
        workspaceId: workspace.workspaceId, workspaceGeneration: workspace.workspaceGeneration,
        workspaceLifecycle: operation.workspaceLifecycle, documentIdentity: contentDocumentIdentity,
        navigationIdentity: contentNavigationIdentity() };
}

function captureFigureTerminationOwner(request, sender) {
    if (sender?.id !== chrome.runtime.id) return { success: false };
    const operation = figureOperationState.active;
    if (!operation || operation.cancelled || operation.operationId !== request.operationId ||
        operation.workspaceLifecycle !== request.workspaceLifecycle) return { success: false };
    const binding = figureTerminationOwnerBinding(operation);
    if (!binding) return { success: false };
    const prior = operation.nativeTerminationOwner;
    if (prior && Object.keys(binding).some(key => binding[key] !== prior[key])) return { success: false };
    operation.nativeTerminationOwner ||= Object.freeze(binding);
    return { success: true, binding: { ...operation.nativeTerminationOwner } };
}

function applyFigureTerminationReceipt(request, sender) {
    if (sender?.id !== chrome.runtime.id || !Number.isFinite(request.expiresAt) ||
        Date.now() >= request.expiresAt || request.expiresAt > Date.now() + 2000) return { success: false };
    const operation = figureOperationState.last;
    const current = figureTerminationOwnerBinding(operation), bound = operation?.nativeTerminationOwner;
    if (!current || !bound || !request.binding || Object.keys(request.binding).length !== Object.keys(bound).length ||
        Object.keys(bound).some(key => current[key] !== bound[key] || request.binding[key] !== bound[key])) return { success: false };
    if (request.nativeRequestState !== undefined) return applyFigureNativeRequestState(request, operation);
    const value = request.diagnostic;
    if (!value || !/^[a-zA-Z0-9:._-]{1,100}$/u.test(value.requestId || '') ||
        !Number.isSafeInteger(value.portSessionId) || value.portSessionId < 1 ||
        !Number.isSafeInteger(value.providerAttempt) || value.providerAttempt < 1 || value.providerAttempt > 96 ||
        !/^[a-f0-9]{64}$/u.test(value.dispatchDigest || '') ||
        !['timeout','aborted'].includes(value.cancelReason)) return { success: false };
    const terminal = value.state === 'terminal_confirmed';
    if (terminal ? !['turn.cancelled','turn.completed','turn.error'].includes(value.terminalType) ||
        !(value.terminalType === 'turn.cancelled' ? ['interrupted','completed'] : value.terminalType === 'turn.completed' ? ['completed'] : ['completed','failed']).includes(value.upstreamStatus) :
        value.state !== 'unknown' || value.upstreamStatus !== 'unknown' ||
        !['receipt_expired','receipt_capacity','bridge_disconnected','terminal_unverified'].includes(value.reason)) return { success: false };
    // The final owner check and this diagnostic-only write share one JS turn.
    // Never call task.apply, mutate result/checkpoint state, or grant a retry here.
    const diagnostic = Object.freeze({ requestId: value.requestId, portSessionId: value.portSessionId,
        providerAttempt: value.providerAttempt, dispatchDigest: value.dispatchDigest,
        cancelReason: value.cancelReason, state: value.state, upstreamStatus: value.upstreamStatus,
        ...(terminal ? { terminalType: value.terminalType } : { reason: value.reason }) });
    const receipts = operation.nativeTerminationDiagnostics ||= new Map();
    const key = `${diagnostic.portSessionId}:${diagnostic.requestId}`;
    if (receipts.has(key)) return { success: false };
    while (receipts.size >= 128) receipts.delete(receipts.keys().next().value);
    receipts.set(key, diagnostic);
    return { success: true, applied: true };
}

function applyFigureNativeRequestState(request, operation) {
    const value = request.nativeRequestState;
    const stages = ['handshake', 'submitted', 'running', 'cancel_requested', 'completed', 'terminal_confirmed', 'outcome_unknown'];
    if (!value || !stages.includes(value.stage) ||
        !/^[a-zA-Z0-9:._-]{1,100}$/u.test(value.requestId || '') ||
        !Number.isSafeInteger(value.portSessionId) || value.portSessionId < (['handshake','cancel_requested','outcome_unknown'].includes(value.stage) && !Number.isFinite(value.dispatchedAt) ? 0 : 1) ||
        !Number.isSafeInteger(request.providerAttempt) || request.providerAttempt < 1 || request.providerAttempt > 96 ||
        !/^[a-f0-9]{64}$/u.test(request.dispatchDigest || '')) return { success: false };
    const times = {};
    for (const key of ['enteredAt', 'dispatchedAt', 'startedAt', 'lastActivityAt', 'cancelRequestedAt', 'terminalAt']) {
        const time = value[key];
        if (time !== undefined && time !== null && (!Number.isFinite(time) || time < 0 || time > Date.now() + 2000)) return { success: false };
        times[key] = Number.isFinite(time) ? time : null;
    }
    if (!Number.isFinite(times.enteredAt) ||
        (value.stage === 'cancel_requested' && !Number.isFinite(times.cancelRequestedAt))) return { success: false };
    const states = operation.nativeRequestStates ||= new Map();
    const previous = states.get(value.requestId);
    if (previous && (previous.providerAttempt !== request.providerAttempt ||
        previous.dispatchDigest !== request.dispatchDigest ||
        (previous.portSessionId > 0 && previous.portSessionId !== value.portSessionId) ||
        stages.indexOf(value.stage) < stages.indexOf(previous.stage))) return { success: false };
    while (states.size >= 128 && !states.has(value.requestId)) states.delete(states.keys().next().value);
    const diagnostic = Object.freeze({ requestId: value.requestId, portSessionId: value.portSessionId,
        providerAttempt: request.providerAttempt, dispatchDigest: request.dispatchDigest,
        stage: value.stage, ...times,
        // A delayed final state must retain the original cancellation clock.
        cancelRequestedAt: times.cancelRequestedAt ?? previous?.cancelRequestedAt ?? null });
    states.set(value.requestId, diagnostic);
    return { success: true, applied: true };
}

function figureNativeRequestStatus(operationId) {
    const operation = figureOperationState.last, bound = operation?.nativeTerminationOwner;
    const current = figureTerminationOwnerBinding(operation);
    if (!bound || operation.operationId !== operationId || !current ||
        Object.keys(bound).some(key => current[key] !== bound[key])) {
        if (operation) operation.nativeRequestStates?.clear();
        return {};
    }
    const states = [...(operation.nativeRequestStates?.values() || [])];
    const diagnostic = states.at(-1);
    const pending = states.filter(value => Number.isFinite(value.cancelRequestedAt) &&
        Number.isFinite(value.dispatchedAt) &&
        !operation.nativeTerminationDiagnostics?.has(`${value.portSessionId}:${value.requestId}`));
    const expiresAt = Math.max(0, ...pending.map(value => value.cancelRequestedAt + 60000));
    return { ...(diagnostic ? { nativeRequestDiagnostic: { ...diagnostic } } : {}),
        nativeTerminationObservationExpiresAt: expiresAt > Date.now() ? expiresAt : 0 };
}

function figureTerminationDiagnosticForStatus(operationId) {
    const operation = figureOperationState.last, bound = operation?.nativeTerminationOwner;
    if (!bound || operation.operationId !== operationId) return null;
    const current = figureTerminationOwnerBinding(operation);
    if (!current ||
        Object.keys(bound).some(key => current[key] !== bound[key])) return null;
    const diagnostic = [...(operation.nativeTerminationDiagnostics?.values() || [])].at(-1);
    if (!diagnostic) return null;
    const detail = diagnostic.state !== 'terminal_confirmed' ? '停止尚未确认' :
        diagnostic.upstreamStatus === 'interrupted' ? '停止已确认（上游已中断）' :
        diagnostic.upstreamStatus === 'completed' ? '已确认结束（取消后完成）' :
        diagnostic.upstreamStatus === 'failed' ? '已确认结束（上游失败）' :
        '已确认结束（旧协议未说明中断或完成）';
    return { ...diagnostic, message: `本地调用 ${diagnostic.providerAttempt}：${detail}。原超时或取消结果保留；此回执不能证明未计费。` };
}

function getPublicFigureAnalysisStatus() {
    const figureProgress = getFigureProgressSnapshot();
    const activeOperation = typeof figureOperationState === 'object'
        ? figureOperationState.active : null;
    const terminationDiagnostic = figureTerminationDiagnosticForStatus(
        activeOperation?.operationId || figureAnalysisStatus.operationId);
    // Releasing a stopped operation must not erase its explicit vision pause.
    const waitingForVisionConfirmation = figureAnalysisStatus.paused === true &&
        figureAnalysisStatus.phase === 'awaiting_vision_confirmation' &&
        (!activeOperation || activeOperation.operationId === figureAnalysisStatus.operationId);
    return {
        ...figureAnalysisStatus,
        ...figureNativeRequestStatus(activeOperation?.operationId || figureAnalysisStatus.operationId),
        ...(terminationDiagnostic ? { nativeTerminationDiagnostic: terminationDiagnostic,
            ...(!activeOperation || activeOperation.cancelled ? {
                message: [figureAnalysisStatus.message, terminationDiagnostic.message].filter(Boolean).join(' ')
            } : {}) } : {}),
        running: Boolean(activeOperation && !activeOperation.cancelled),
        paused: activeOperation?.paused === true || waitingForVisionConfirmation,
        canPause: Boolean(activeOperation && !activeOperation.cancelled),
        operationId: activeOperation?.operationId || figureAnalysisStatus.operationId,
        failures: figureAnalysisStatus.failures.map(item => ({ ...item })),
        figureProgress,
        figureProgressById: Object.fromEntries(
            figureProgress.map(item => [item.figureId, { ...item }])
        )
    };
}

function createInitialReviewOutlineStatus() {
    return {
        running: false,
        phase: 'idle',
        completedParagraphs: 0,
        totalParagraphs: 0,
        completedChunks: 0,
        totalChunks: 0,
        checkpointVersion: 0,
        saveConfirmed: false,
        checkpointCached: false,
        message: '',
        globalSynthesisAvailable: null,
        updatedAt: Date.now()
    };
}

function updateReviewOutlineStatus(patch = {}) {
    reviewOutlineStatus = {
        ...reviewOutlineStatus,
        ...patch,
        updatedAt: Date.now()
    };
    return reviewOutlineStatus;
}

function getPublicReviewOutlineStatus() {
    return { ...reviewOutlineStatus };
}

function closeReadingPanel() {
    document.getElementById('sci-reading-panel')?.remove();
}

function closeArticleNavigationPanels() {
    document.getElementById('sci-article-navigator-host')?.remove();
    document.getElementById('sci-review-outline-host')?.remove();
    document.getElementById('sci-review-outline-panel')?.remove();
}

const nativePdfLlmHighlightsByMode = new Map();
const nativePdfSemanticChatHighlightsByTurn = new Map();

function clearLlmHighlights(analysisModeId = '') {
    closeLlmFeedbackPopover();
    const targetId = String(analysisModeId || '');
    if (targetId) nativePdfLlmHighlightsByMode.delete(targetId);
    else nativePdfLlmHighlightsByMode.clear();
    document.querySelectorAll('.pdf-native-automatic-layer').forEach(layer => {
        if (!targetId || layer.dataset.analysisModeId === targetId) layer.remove();
    });
    [...document.querySelectorAll('.sci-llm-highlight')]
        .filter(mark => !targetId ||
            String(mark.dataset.analysisModeId || 'llm-default') === targetId)
        .reverse().forEach(mark => {
        const parent = mark.parentNode;
        if (!parent) return;
        while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
        parent.removeChild(mark);
        parent.normalize();
    });
    document.getElementById('sci-llm-status')?.remove();
    closeReadingPanel();
}

function collectLlmTextNodes(element) {
    const nodes = [];
    const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, {
        acceptNode: node => SciLLM.isScientificInlineTextExcluded(node)
            ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
    });
    let node;
    while ((node = walker.nextNode())) nodes.push(node);
    return nodes;
}

function locateRawOffset(nodes, rawOffset) {
    let cursor = 0;
    for (const node of nodes) {
        const next = cursor + node.textContent.length;
        if (rawOffset <= next) return { node, offset: Math.max(0, rawOffset - cursor) };
        cursor = next;
    }
    return null;
}

function rangesOverlap(first, second) {
    return first.start < second.end && second.start < first.end;
}

function annotationIdsForMark(mark) {
    return String(mark?.dataset?.annotationIds || '').split(',').filter(Boolean);
}

function relationIdsForMark(mark) {
    return String(mark?.dataset?.relationIds || '').split(',').filter(Boolean);
}

function nativePdfAutomaticSourceKey(item, categoryId, sourceType) {
    if (!['regex', 'llm', 'semantic'].includes(sourceType)) return '';
    const locator = item?.locator;
    return JSON.stringify([sourceType, String(categoryId || ''),
        locator ? ['semantic', locator.paragraphId, locator.normalizedStart, locator.normalizedEnd,
            locator.expectedNormalizedQuote] : ['page', item?.pageNumber, item?.start, item?.end, item?.quote]]);
}

function bindNativePdfAutomaticNote(mark, { entry, item, pageNumber, rawRange, category, sourceType, rawOffsets = true }) {
    mark.tabIndex = 0;
    mark.setAttribute('role', 'button');
    mark.setAttribute('aria-label', `${category.name || category.categoryId}：${rawRange.quote || ''}。打开高亮备注`);
    const activate = event => {
        if (event.type === 'keydown' && !['Enter', ' '].includes(event.key)) return;
        event.preventDefault(); event.stopPropagation();
        const native = globalThis.__brevessNativePdfDocument;
        const hash = String(entry.documentHash || entry.analysisMeta?.documentHash || '');
        const generation = Number(entry.documentGeneration ?? entry.generation);
        if (!currentManualDocument?.documentId || native?.structure?.documentHash !== hash ||
            Number(native?.documentGeneration) !== generation) return;
        const projection = globalThis.__brevessPdfReaderBridge?.command?.('getPageProjection', pageNumber);
        if (!projection || projection.documentHash !== hash || projection.documentGeneration !== generation) return;
        const text = SciLLM.readPdfTextProjection(projection.textLayer, rawOffsets ? { mode: 'raw-offset' } : undefined);
        if (text.text.slice(rawRange.start, rawRange.end) !== rawRange.quote) return;
        const range = SciLLM.pdfProjectionRange(text, rawRange, document);
        if (!range) return;
        const descriptor = describeCurrentManualSelection({ rangeCount: 1, isCollapsed: false,
            getRangeAt: () => range, toString: () => rawRange.quote });
        if (!descriptor?.validation?.valid || !descriptor.anchor?.pdfAnchor) {
            showManualStatus('无法定位此 PDF 高亮，请等待页面就绪后重试。', 'error'); return;
        }
        const existing = currentManualDocument.record?.annotations?.find(annotation =>
            annotation.sourceType === sourceType && annotation.categoryId === category.categoryId &&
            annotation.quote === descriptor.anchor.quote &&
            annotation.startOffset === descriptor.anchor.startOffset && annotation.endOffset === descriptor.anchor.endOffset &&
            String(annotation.pdfAnchor?.documentHash || '').replace(/^sha256:/, '') ===
                String(descriptor.anchor.pdfAnchor.documentHash || '').replace(/^sha256:/, '') &&
            annotation.pdfAnchor?.pageNumber === descriptor.anchor.pdfAnchor.pageNumber &&
            annotation.pdfAnchor?.contextHash === descriptor.anchor.pdfAnchor.contextHash);
        if (existing) { openManualAnnotationSurface(existing, mark, sourceType === 'llm' ? mark : null); return; }
        showManualSelectionToolbar({ ...descriptor, openNote: true, initialCategory: category, sourceType,
            sourceAnnotationKey: nativePdfAutomaticSourceKey(item || { ...rawRange, pageNumber }, category.categoryId, sourceType),
            llmMark: sourceType === 'llm' ? mark : null, rect: mark.getBoundingClientRect() });
    };
    mark.addEventListener('click', activate);
    mark.addEventListener('keydown', activate);
}

function bindLlmHighlightInteraction(mark) {
    if (!mark || mark.dataset?.restoredChatTurnId || llmHighlightInteractions.has(mark)) return;
    llmHighlightInteractions.add(mark);
    mark.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        showHighlightContextPopover(mark);
    });
    mark.addEventListener('keydown', event => {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        event.stopPropagation();
        showHighlightContextPopover(mark);
    });
}

function focusRelatedHighlights({ annotationIds = [], relationId = '' }) {
    const annotationSet = new Set(annotationIds);
    const marks = [...document.querySelectorAll('.sci-llm-highlight')].filter(mark =>
        annotationIdsForMark(mark).some(id => annotationSet.has(id)) ||
        (relationId && relationIdsForMark(mark).includes(relationId))
    );
    marks.forEach(mark => {
        mark.classList.add('sci-llm-related-focus');
        setTimeout(() => mark.classList.remove('sci-llm-related-focus'), 1800);
    });
    marks[0]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function appendPanelList(section, items, renderItem) {
    if (!items.length) return;
    const list = document.createElement('div');
    list.className = 'sci-reading-list';
    items.forEach(item => list.appendChild(renderItem(item)));
    section.appendChild(list);
}

function createPanelButton(label, clickHandler) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'sci-reading-item';
    button.textContent = label;
    button.addEventListener('click', clickHandler);
    return button;
}

function prependUiIcon(element, iconName) {
    if (!element || !iconName) return element;
    const icon = document.createElement('i');
    icon.className = `ph ph-${iconName}`;
    icon.setAttribute('aria-hidden', 'true');
    element.prepend(icon);
    return element;
}

function setIconButtonLabel(button, iconName, label) {
    button.replaceChildren();
    prependUiIcon(button, iconName);
    button.append(document.createTextNode(label));
}

function formatEvidenceStrength(value) {
    return ({
        strong: '证据强',
        moderate: '证据中等',
        weak: '证据有限'
    })[String(value || '').toLowerCase()] || '证据待定';
}

function appendReadingSectionTitle(section, label, count) {
    const heading = document.createElement('div');
    heading.className = 'sci-reading-section-title';
    heading.textContent = `${label}（${count}）`;
    section.appendChild(heading);
}

function renderReadingPanel(analysis) {
    closeReadingPanel();
    closeArticleNavigationPanels();
    const ledger = analysis?.ledger;
    const hasContent = ledger && (
        ledger.relationSummaries?.length || ledger.reviewWarnings?.length || ledger.auditItems?.length
    );
    if (!hasContent) return;

    const viewNames = {
        quick_story: '快速主线',
        mechanism_chain: '机制证据链',
        critical_review: '批判性审读'
    };
    const panel = document.createElement('aside');
    panel.id = 'sci-reading-panel';
    panel.setAttribute('aria-label', '论文分析模式');

    const header = document.createElement('div');
    header.className = 'sci-reading-header';
    const title = document.createElement('strong');
    title.textContent = viewNames[analysis.readingViewId] || '论文证据台账';
    const actions = document.createElement('div');
    actions.className = 'sci-reading-actions';
    const toggle = document.createElement('button');
    toggle.type = 'button';
    setIconButtonLabel(toggle, 'caret-up', '收起');
    toggle.setAttribute('aria-expanded', 'true');
    toggle.addEventListener('click', () => {
        panel.classList.toggle('collapsed');
        const collapsed = panel.classList.contains('collapsed');
        setIconButtonLabel(toggle, collapsed ? 'caret-down' : 'caret-up', collapsed ? '展开' : '收起');
        toggle.setAttribute('aria-expanded', String(!collapsed));
    });
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'sci-reading-close';
    close.textContent = '关闭';
    close.setAttribute('aria-label', '关闭论文证据台账');
    close.addEventListener('click', closeReadingPanel);
    actions.append(toggle, close);
    header.append(title, actions);
    panel.appendChild(header);

    const body = document.createElement('div');
    body.className = 'sci-reading-body';
    const profile = analysis.studyProfile;
    if (profile) {
        const summary = document.createElement('div');
        summary.className = 'sci-reading-profile';
        const primaryTypeName = profile.primaryTypeName || profile.primaryType;
        summary.textContent = `研究类型：${primaryTypeName}`;
        body.appendChild(summary);
    }

    const relationSummaries = ledger.relationSummaries || [];
    if (relationSummaries.length) appendReadingSectionTitle(body, '核心证据', relationSummaries.length);
    appendPanelList(body, relationSummaries, relation =>
        createPanelButton(
            `${relation.labelZh} · ${(relation.annotationIds || []).length}条证据 · ` +
                formatEvidenceStrength(relation.evidenceStrength),
            () => focusRelatedHighlights({
                annotationIds: relation.annotationIds,
                relationId: relation.relationId
            })
        )
    );

    const reviewWarnings = ledger.reviewWarnings || [];
    if (reviewWarnings.length) appendReadingSectionTitle(body, '审读提醒', reviewWarnings.length);
    appendPanelList(body, reviewWarnings, warning => {
        const button = createPanelButton(
            `${warning.reasonZh}（${Math.round(warning.confidence * 100)}%）`,
            () => focusRelatedHighlights({
                annotationIds: [
                    ...(warning.claimAnnotationIds || []),
                    ...(warning.evidenceAnnotationIds || [])
                ]
            })
        );
        button.classList.add('warning');
        prependUiIcon(button, 'warning');
        return button;
    });

    const auditItems = ledger.auditItems || [];
    if (auditItems.length) {
        const auditDetails = document.createElement('details');
        auditDetails.className = 'sci-reading-audit-details';
        auditDetails.open = analysis.readingViewId === 'critical_review';
        const auditSummary = document.createElement('summary');
        auditSummary.textContent = `待核查信息（${auditItems.length}）`;
        auditDetails.appendChild(auditSummary);
        appendPanelList(auditDetails, auditItems, item => {
            const row = document.createElement('div');
            row.className = 'sci-reading-audit-item';
            const message = String(item.messageZh || '').trim();
            row.textContent = message.startsWith('待核查：') ? message : `待核查：${message}`;
            return row;
        });
        body.appendChild(auditDetails);
    }

    panel.appendChild(body);
    document.documentElement.appendChild(panel);
}

function paintNativePdfLlmPage(entry, pageNumber) {
    const modeId = entry.analysisMeta.readingViewId || 'llm-default';
    return paintPdfSemanticHighlightPage(entry, pageNumber, {
        layerClass: 'pdf-native-automatic-layer', modeId,
        legacyRanges: (annotation, currentPage) => annotation.pageNumber === currentPage
            ? [{ pageNumber: currentPage, start: annotation.start, end: annotation.end,
                quote: annotation.quote, precision: 'legacy' }] : [],
        createMark: ({ item: annotation, rawRange, textProjection }) => {
        const categories = annotation.categories || [];
        const primary = annotation.primary || categories[0] || {};
            const mark = document.createElement('button');
            mark.type = 'button';
            mark.className = 'sci-llm-highlight pdf-native-automatic-hit';
            mark.dataset.source = 'llm';
            mark.dataset.analysisModeId = modeId;
            mark.dataset.categoryId = primary.categoryId || '';
            mark.dataset.categories = categories.map(item => item.categoryId).join(',');
            mark.dataset.annotationIds = categories.map(item => item.annotationId).filter(Boolean).join(',');
            mark.dataset.relationIds = categories.map(item => item.relationId).filter(Boolean).join(',');
            mark.dataset.pdfPageNumber = String(pageNumber);
            mark.dataset.presentationMode = annotation.visibleMode || 'inline_highlight';
            const color = primary.color || entry.categoryMap[primary.categoryId]?.color || '#8EC5FF';
            mark.style.setProperty('--pdf-annotation-color', color);
            mark.title = categories.map(item => `${item.categoryName || item.categoryId}` +
                `${Number.isFinite(item.confidence) ? ` ${Math.round(item.confidence * 100)}%` : ''}` +
                `${item.reasonZh ? `：${item.reasonZh}` : ''}`).join('\n');
            mark.setAttribute('aria-label', `${mark.title}：${annotation.quote}`);
            llmFeedbackByMark.set(mark, {
                documentHash: entry.analysisMeta.documentHash || '',
                paragraphId: annotation.paragraphId,
                quote: annotation.quote,
                contextBefore: textProjection.text.slice(Math.max(0, rawRange.start - 240), rawRange.start),
                contextAfter: textProjection.text.slice(rawRange.end, rawRange.end + 240),
                categoryId: primary.categoryId || '', confidence: primary.confidence,
                reasonZh: primary.reasonZh || '', categories: categories.map(item => ({ ...item })),
                presentationMode: annotation.visibleMode || 'inline_highlight',
                availableCategories: Object.values(entry.categoryMap).map(item => ({ categoryId: item.categoryId, name: item.name }))
            });
            bindNativePdfAutomaticNote(mark, { entry, item: annotation, pageNumber, rawRange, rawOffsets: isPdfSemanticHighlightLocator(annotation.locator), sourceType: 'llm',
                category: { categoryId: primary.categoryId, name: primary.categoryName || entry.categoryMap[primary.categoryId]?.name, color } });
            return mark;
        }
    });
}

function applyNativePdfLlmHighlights(annotations, analysisMeta) {
    const structure = activeNativePdfStructure();
    const native = globalThis.__brevessNativePdfDocument;
    const semanticState = currentNativePdfSemanticHighlightState();
    const semanticContext = semanticState.context;
    const modeId = String(analysisMeta.readingViewId || 'llm-default');
    clearLlmHighlights(modeId);
    if (semanticState.required && !semanticState.ready) {
        return {
            highlightedCount: 0, rejectedCount: 0, hiddenPresentationCount: 0,
            counts: {}, familyCounts: {}, presentationModeCounts: {},
            presentationDensity: llmPresentationState.density,
            hiddenFamilyIds: [...llmPresentationState.hiddenFamilyIds],
            degradedCount: 0, unresolvedCount: 1,
            highlightReasonCodes: ['PDF_SEMANTIC_WAITING'],
            waitingForSemantic: true
        };
    }
    const categoryMap = SciLLM.createBuiltInCategories();
    (analysisMeta.categories || []).forEach(category => { categoryMap[category.categoryId] = category; });
    const paragraphs = new Map(structure.paragraphs.map(item => [item.paragraphId, item]));
    const entry = { analysisMeta, categoryMap, documentHash: structure.documentHash,
        documentGeneration: native.documentGeneration,
        ...(semanticState.ready ? {
            semantic: true,
            revision: semanticContext.revision,
            semanticCacheKey: semanticContext.semanticCacheKey,
            semanticProvenanceKey: semanticContext.semanticProvenanceKey
        } : {}),
        annotations: [], items: [] };
    const counts = {}, familyCounts = {}, presentationModeCounts = {};
    const diagnostics = { degradedCount: 0, unresolvedCount: 0,
        highlightReasonCodes: [] };
    let rejectedCount = 0, hiddenPresentationCount = 0;
    for (const original of Array.isArray(annotations) ? annotations : []) {
        const annotation = SciLLM.resolveAnnotationPresentation?.(original, {
            viewId: modeId, density: llmPresentationState.density,
            hiddenFamilyIds: llmPresentationState.hiddenFamilyIds, categoryMap
        }) || original;
        if (!annotation.categories?.length || annotation.visibleMode === 'special') { hiddenPresentationCount++; continue; }
        const semanticCandidate = Boolean(semanticContext && semanticState.ready);
        let storedAnnotation;
        if (semanticCandidate) {
            const focused = resolvePdfSemanticHighlightFocus(annotation, semanticContext);
            const locator = focused.target && focused.selection
                ? createPdfSemanticHighlightLocator(focused.target, focused.selection) : null;
            const resolved = locator
                ? resolvePdfSemanticHighlightLocator(locator)
                : { status: 'unresolved', reasonCode: focused.reasonCode ||
                    'PDF_HIGHLIGHT_LOCATOR_UNRESOLVED' };
            if (resolved.status !== 'resolved') {
                addPdfSemanticHighlightDiagnostic(diagnostics, resolved);
                continue;
            }
            storedAnnotation = { ...annotation, locatorKind: 'pdf-semantic', locator,
                paragraphId: focused.target.paragraphId,
                pageNumbers: [...new Set(resolved.ranges.map(range => range.pageNumber))] };
        } else {
            const paragraph = paragraphs.get(annotation.paragraphId);
            if (!paragraph || paragraph.text.slice(annotation.start, annotation.end) !== annotation.quote) {
                rejectedCount++; continue;
            }
            storedAnnotation = { ...annotation, pageNumber: paragraph.pageNumber };
        }
        entry.annotations.push(storedAnnotation);
        entry.items.push(storedAnnotation);
        annotation.categories.forEach(item => { counts[item.categoryId] = (counts[item.categoryId] || 0) + 1; });
        (annotation.familyIds || []).forEach(id => { familyCounts[id] = (familyCounts[id] || 0) + 1; });
        const mode = annotation.visibleMode || 'inline_highlight';
        presentationModeCounts[mode] = (presentationModeCounts[mode] || 0) + 1;
    }
    nativePdfLlmHighlightsByMode.set(modeId, entry);
    new Set(entry.items.flatMap(item => isPdfSemanticHighlightLocator(item.locator)
        ? item.pageNumbers : [item.pageNumber])).forEach(pageNumber => paintNativePdfLlmPage(entry, pageNumber));
    return { highlightedCount: entry.annotations.length, rejectedCount, hiddenPresentationCount,
        counts, familyCounts, presentationModeCounts, presentationDensity: llmPresentationState.density,
        hiddenFamilyIds: [...llmPresentationState.hiddenFamilyIds], ...diagnostics };
}

document.addEventListener('brevess:pdf-page-rendered', event => {
    nativePdfLlmHighlightsByMode.forEach(entry => paintNativePdfLlmPage(entry, event.detail?.pageNumber));
    nativePdfSemanticChatHighlightsByTurn.forEach(entry =>
        paintNativePdfSemanticChatPage(entry, event.detail?.pageNumber));
});
document.addEventListener('brevess:pdf-page-unmounted', event => {
    document.querySelectorAll(`.pdf-native-page[data-pdf-page-number="${Number(event.detail?.pageNumber)}"] ` +
        '.pdf-native-automatic-layer, ' +
        `.pdf-native-page[data-pdf-page-number="${Number(event.detail?.pageNumber)}"] ` +
        '.pdf-native-semantic-chat-layer, ' +
        `.pdf-native-page[data-pdf-page-number="${Number(event.detail?.pageNumber)}"] ` +
        '.pdf-native-regex-layer')
        .forEach(layer => layer.remove());
});

function applyLlmHighlights(annotations, analysisMeta = {}) {
    if (activeNativePdfStructure() && SciLLM.readPdfTextProjection) {
        return applyNativePdfLlmHighlights(annotations, analysisMeta);
    }
    const analysisModeId = String(
        analysisMeta.readingViewId || 'llm-default'
    );
    clearLlmHighlights(analysisModeId);
    const restoredChatTurnId = String(analysisMeta.restoredChatTurnId || '');
    const displayOnly = restoredChatTurnId &&
        analysisModeId === restoredHtmlSemanticChatModeId(restoredChatTurnId);
    const categoryMap = SciLLM.createBuiltInCategories();
    (Array.isArray(analysisMeta.categories) ? analysisMeta.categories : []).forEach(category => {
        categoryMap[category.categoryId] = category;
    });
    const paragraphMetadata = new Map(
        (Array.isArray(analysisMeta.paragraphs) ? analysisMeta.paragraphs : [])
            .map(paragraph => [paragraph.paragraphId, paragraph])
    );
    const elements = new Map(
        [...document.querySelectorAll('[data-sci-llm-paragraph-id]')]
            .map(element => [element.dataset.sciLlmParagraphId, element])
    );
    const presentationOptions = {
        viewId: analysisModeId,
        density: llmPresentationState.density,
        hiddenFamilyIds: llmPresentationState.hiddenFamilyIds,
        categoryMap
    };
    const allPresentationGroups = (Array.isArray(annotations) ? annotations : [])
        .map(annotation => !displayOnly && SciLLM.resolveAnnotationPresentation
            ? SciLLM.resolveAnnotationPresentation(annotation, presentationOptions)
            : annotation
        );
    const visibleAnnotations = allPresentationGroups.filter(annotation =>
        (Array.isArray(annotation.categories) ? annotation.categories : []).length &&
        annotation.visibleMode !== 'special'
    );
    const byParagraph = new Map();
    visibleAnnotations.forEach(annotation => {
        const items = byParagraph.get(annotation.paragraphId) || [];
        items.push(annotation);
        byParagraph.set(annotation.paragraphId, items);
    });

    const counts = {};
    const familyCounts = {};
    const presentationModeCounts = {};
    let highlightedCount = 0;
    let rejectedCount = 0;
    const hiddenPresentationCount = allPresentationGroups.length - visibleAnnotations.length;

    byParagraph.forEach((items, paragraphId) => {
        const element = elements.get(paragraphId);
        if (!element) {
            rejectedCount += items.length;
            return;
        }
        const acceptedRanges = [];
        items.sort((a, b) => b.start - a.start).forEach(annotation => {
            if (acceptedRanges.some(range => rangesOverlap(range, annotation))) {
                rejectedCount += 1;
                return;
            }
            const nodes = collectLlmTextNodes(element);
            const rawText = nodes.map(node => node.textContent).join('');
            const normalized = SciLLM.normalizeTextWithOffsets(rawText);
            if (normalized.text.slice(annotation.start, annotation.end) !== annotation.quote ||
                annotation.start < 0 || annotation.end <= annotation.start) {
                rejectedCount += 1;
                return;
            }
            const rawStart = normalized.rawStarts[annotation.start];
            const rawEnd = normalized.rawEnds[annotation.end - 1];
            const start = locateRawOffset(nodes, rawStart);
            const end = locateRawOffset(nodes, rawEnd);
            if (!start || !end) {
                rejectedCount += 1;
                return;
            }

            const categories = Array.isArray(annotation.categories) ? annotation.categories : [];
            const primaryRelation = annotation.primary || categories[0] || {};
            const primary = {
                name: primaryRelation.categoryName ||
                    categoryMap[primaryRelation.categoryId]?.name ||
                    primaryRelation.categoryId || 'LLM 标注',
                color: primaryRelation.color ||
                    categoryMap[primaryRelation.categoryId]?.color || '#8EC5FF'
            };
            const mark = document.createElement('mark');
            mark.className = 'sci-llm-highlight';
            const presentationMode = annotation.visibleMode || 'inline_highlight';
            mark.classList.add(`sci-llm-mode-${presentationMode.replace(/_/g, '-')}`);
            if (presentationMode === 'relation_card') {
                mark.classList.add('sci-llm-relation-anchor');
            } else if (presentationMode === 'audit_warning') {
                mark.classList.add('sci-llm-audit-anchor');
            }
            if (displayOnly) {
                mark.dataset.restoredChatTurnId = restoredChatTurnId;
                mark.dataset.source = 'semantic';
            } else {
                mark.tabIndex = 0;
                mark.setAttribute('role', 'button');
                mark.dataset.source = 'llm';
            }
            mark.dataset.analysisModeId = analysisModeId;
            mark.dataset.categoryId = primaryRelation.categoryId || '';
            mark.dataset.categories = categories.map(item => item.categoryId).join(',');
            mark.dataset.annotationIds = categories.map(item => item.annotationId).filter(Boolean).join(',');
            mark.dataset.relationIds = categories.map(item => item.relationId).filter(Boolean).join(',');
            mark.dataset.presentationMode = presentationMode;
            mark.dataset.displayFamilyId = primaryRelation.displayFamilyId || '';
            mark.dataset.badges = llmPresentationState.language === 'en'
                ? annotation.badgeLabelEn || '' : annotation.badgeLabelZh || '';
            mark.dataset.auditLabel = llmPresentationState.language === 'en'
                ? 'AI audit' : 'AI 审读';
            mark.style.borderBottomColor = primary.color;
            mark.title = categories.map(item => {
                const confidence = Number.isFinite(item.confidence) ? ` ${Math.round(item.confidence * 100)}%` : '';
                const mode = item.claimMode === 'inferred' ? 'AI 推断警示' : '作者明确陈述';
                const role = item.quoteRole ? ` · ${item.quoteRole}` : '';
                const slots = (item.slots || []).map(slot => `${slot.name}=${slot.value}`).join('；');
                return `${item.categoryName || item.categoryId}${confidence} · ${mode}${role}` +
                    `${item.reasonZh ? `：${item.reasonZh}` : ''}` +
                    `${slots ? `\n${slots}` : ''}`;
            }).join('\n');
            mark.setAttribute(
                'aria-label',
                `${primary.name}高亮：${annotation.quote.slice(0, 100)}` +
                    (displayOnly ? '' : '。按回车可提供反馈')
            );

            const metadata = paragraphMetadata.get(paragraphId) || {};
            if (!displayOnly) llmFeedbackByMark.set(mark, {
                documentHash: analysisMeta.documentHash || '',
                paragraphId,
                sectionTitle: metadata.sectionTitle || '',
                contextBefore: normalized.text.slice(Math.max(0, annotation.start - 240), annotation.start),
                quote: annotation.quote,
                contextAfter: normalized.text.slice(annotation.end, annotation.end + 240),
                categoryId: primaryRelation.categoryId || '',
                confidence: primaryRelation.confidence,
                reasonZh: primaryRelation.reasonZh || '',
                categories: categories.map(item => ({ ...item })),
                presentationMode,
                displayFamilyId: primaryRelation.displayFamilyId || '',
                displayFamilyName: llmPresentationState.language === 'en'
                    ? SciLLM.DISPLAY_FAMILIES?.[primaryRelation.displayFamilyId]?.labelEn || ''
                    : SciLLM.DISPLAY_FAMILIES?.[primaryRelation.displayFamilyId]?.labelZh || '',
                presentationLanguage: llmPresentationState.language,
                availableCategories: Object.values(categoryMap).map(category => ({
                    categoryId: category.categoryId,
                    name: category.name
                }))
            });
            bindLlmHighlightInteraction(mark);

            const range = document.createRange();
            range.setStart(start.node, start.offset);
            range.setEnd(end.node, end.offset);
            mark.appendChild(range.extractContents());
            range.insertNode(mark);
            acceptedRanges.push({ start: annotation.start, end: annotation.end });
            highlightedCount += 1;
            categories.forEach(item => {
                counts[item.categoryId] = (counts[item.categoryId] || 0) + 1;
            });
            (annotation.familyIds || []).forEach(familyId => {
                familyCounts[familyId] = (familyCounts[familyId] || 0) + 1;
            });
            presentationModeCounts[presentationMode] =
                (presentationModeCounts[presentationMode] || 0) + 1;
        });
    });

    return {
        highlightedCount,
        rejectedCount,
        hiddenPresentationCount,
        counts,
        familyCounts,
        presentationModeCounts,
        presentationDensity: llmPresentationState.density,
        hiddenFamilyIds: [...llmPresentationState.hiddenFamilyIds]
    };
}

function bindCurrentPdfSemanticAnnotations(rawAnalysis) {
    const context = typeof refreshActivePdfSemanticNavigationContext === 'function'
        ? refreshActivePdfSemanticNavigationContext() : null;
    if (!context?.navigation || !rawAnalysis || !Array.isArray(rawAnalysis.annotations)) {
        return rawAnalysis;
    }
    return {
        ...rawAnalysis,
        annotations: rawAnalysis.annotations.map(annotation => {
            const focused = resolvePdfSemanticHighlightFocus(annotation, context);
            const locator = focused.target && focused.selection
                ? createPdfSemanticHighlightLocator(focused.target, focused.selection) : null;
            return locator ? { ...annotation, ...locator } : {
                ...annotation, locatorKind: 'pdf-semantic'
            };
        })
    };
}

function buildPageConfidenceDistribution() {
    const raw = lastLlmAnalysis?.rawAnalysis;
    const result = { documentIdentity: contentDocumentIdentity,
        readingViewId: String(raw?.readingViewId || ''), available: Boolean(raw),
        groups: [], unresolvedCount: 0 };
    if (!raw) return result;
    // PDF semantic locators have a distinct geometry/selection contract. Never
    // infer their presentability from HTML offsets or stale page marks.
    if (activeNativePdfStructure()) return { ...result, available:false, reason:'PDF_PREVIEW_UNAVAILABLE' };
    const allowed = selectedArticleAnalysisParagraphIds();
    const elements = new Map([...document.querySelectorAll('[data-sci-llm-paragraph-id]')]
        .map(element => [element.dataset.sciLlmParagraphId, element]));
    const categoryMap = SciLLM.createBuiltInCategories();
    (raw.categories || []).forEach(category => { categoryMap[category.categoryId] = category; });
    const textByParagraph = new Map();
    for (const source of Array.isArray(raw.annotations) ? raw.annotations : []) {
        if (!allowed.has(String(source?.paragraphId || ''))) continue;
        const group = SciLLM.resolveAnnotationPresentation(source, {
            viewId: result.readingViewId, density: llmPresentationState.density,
            hiddenFamilyIds: llmPresentationState.hiddenFamilyIds, categoryMap
        });
        if (!group.categories?.length || group.visibleMode === 'special') continue;
        const element = elements.get(group.paragraphId);
        if (!element) { result.unresolvedCount += 1; continue; }
        let text = textByParagraph.get(group.paragraphId);
        if (text === undefined) {
            text = SciLLM.normalizeTextWithOffsets(collectLlmTextNodes(element)
                .map(node => node.textContent).join('')).text;
            textByParagraph.set(group.paragraphId, text);
        }
        if (!Number.isSafeInteger(group.start) || !Number.isSafeInteger(group.end) ||
            group.start < 0 || group.end <= group.start || group.end > text.length ||
            text.slice(group.start, group.end) !== group.quote) {
            result.unresolvedCount += 1; continue;
        }
        const sentenceKeys = [];
        let cursor = group.start;
        while (cursor < group.end) {
            while (cursor < group.end && /\s/u.test(text[cursor])) cursor += 1;
            if (cursor >= group.end) break;
            const bounds = SciLLM.findScientificSentenceBounds(text, cursor, cursor);
            if (bounds.end <= cursor) break;
            sentenceKeys.push(`${group.paragraphId}:${bounds.start}:${bounds.end}`);
            cursor = bounds.end;
        }
        if (!sentenceKeys.length) continue;
        result.groups.push({ paragraphId:group.paragraphId, start:group.start, end:group.end,
            sentenceKeys, categories:group.categories.map(category => ({
                categoryId:category.categoryId, confidence:category.confidence,
                minimumConfidence:category.minimumConfidence, claimMode:category.claimMode
            })) });
    }
    return result;
}

function renderLlmAnalysis(rawAnalysis, paragraphs, threshold, extractionDiagnostics) {
    const filtered = SciLLM.filterAnnotationGroupsByConfidence(
        rawAnalysis.annotations,
        threshold
    );
    const semanticAnnotationIds = new Set((Array.isArray(rawAnalysis.annotations)
        ? rawAnalysis.annotations : []).filter(annotation =>
        annotation?.locatorKind === 'pdf-semantic' &&
        !String(annotation?.paragraphId || '').startsWith('pdf-page-'))
        .map(annotation => String(annotation.paragraphId || '')));
    const allowedParagraphIds = semanticAnnotationIds.size
        ? semanticAnnotationIds : selectedArticleAnalysisParagraphIds();
    const applied = applyLlmHighlights(filtered.annotations.filter(annotation =>
        allowedParagraphIds.has(String(annotation?.paragraphId || ''))
    ), {
        ...rawAnalysis,
        paragraphs
    });
    lastLlmAnalysis = { rawAnalysis, paragraphs, extractionDiagnostics, threshold: filtered.threshold };
    lastLlmDiagnostics = {
        extraction: extractionDiagnostics,
        stage: 'complete',
        annotationCount: Array.isArray(rawAnalysis.annotations) ? rawAnalysis.annotations.length : 0,
        providerRejectedCount: Array.isArray(rawAnalysis.rejected) ? rawAnalysis.rejected.length : 0,
        semanticRejectedCount: rawAnalysis.semanticRejectedCount || 0,
        confidenceThreshold: filtered.threshold,
        hiddenConfidenceCount: filtered.hiddenCount,
        highlightedCount: applied.highlightedCount,
        rejectedCount: applied.rejectedCount,
        degradedCount: applied.degradedCount || 0,
        unresolvedCount: applied.unresolvedCount || 0,
        highlightReasonCodes: applied.highlightReasonCodes || [],
        hiddenPresentationCount: applied.hiddenPresentationCount,
        presentationDensity: applied.presentationDensity,
        hiddenFamilyIds: applied.hiddenFamilyIds,
        familyCounts: applied.familyCounts,
        presentationModeCounts: applied.presentationModeCounts,
        studyProfile: rawAnalysis.studyProfile || null,
        readingViewId: rawAnalysis.readingViewId || '',
        profileCacheHit: Boolean(rawAnalysis.profileCacheHit),
        ledgerAvailable: rawAnalysis.ledger?.available !== false,
        ledgerCacheHit: Boolean(rawAnalysis.ledgerCacheHit),
        relationCount: rawAnalysis.ledger?.relationSummaries?.length || 0,
        auditItemCount: rawAnalysis.ledger?.auditItems?.length || 0
    };
    return { ...applied, ...filtered };
}

function renderProgressiveLlmChunk(progress = {}) {
    const state = llmProgressiveAnalysis;
    const rawCheckpointAnnotations = Array.isArray(progress.checkpointAnnotations)
        ? progress.checkpointAnnotations : [];
    const checkpointAnnotations = bindCurrentPdfSemanticAnnotations({
        annotations: rawCheckpointAnnotations
    })?.annotations || rawCheckpointAnnotations;
    if (!state || !checkpointAnnotations.length) return null;
    const prior = Array.isArray(state.rawAnalysis.annotations)
        ? state.rawAnalysis.annotations : [];
    state.rawAnalysis.annotations = typeof SciLLM.mergeAnnotations === 'function'
        ? SciLLM.mergeAnnotations([...prior, ...checkpointAnnotations])
        : [...prior, ...checkpointAnnotations];
    state.rawAnalysis.rejected = [
        ...(Array.isArray(state.rawAnalysis.rejected) ? state.rawAnalysis.rejected : []),
        ...(Array.isArray(progress.checkpointRejected) ? progress.checkpointRejected : [])
    ];
    const filtered = SciLLM.filterAnnotationGroupsByConfidence(
        state.rawAnalysis.annotations,
        state.threshold
    );
    const applied = applyLlmHighlights(filtered.annotations, {
        ...state.rawAnalysis,
        paragraphs: state.paragraphs
    });
    // Keep the normal feedback and archive paths usable while the later
    // chunks are still running. The final response replaces this partial view.
    lastLlmAnalysis = {
        rawAnalysis: state.rawAnalysis,
        paragraphs: state.paragraphs,
        extractionDiagnostics: state.extractionDiagnostics,
        threshold: filtered.threshold
    };
    // Paragraph-level Claim Census results are durable immediately instead of
    // waiting for every remaining chunk and the evidence-ledger pass.
    scheduleCurrentArticleArchiveSave();
    lastLlmDiagnostics = {
        extraction: state.extractionDiagnostics,
        stage: 'streaming',
        annotationCount: state.rawAnalysis.annotations.length,
        providerRejectedCount: state.rawAnalysis.rejected.length,
        confidenceThreshold: filtered.threshold,
        hiddenConfidenceCount: filtered.hiddenCount,
        highlightedCount: applied.highlightedCount,
        rejectedCount: applied.rejectedCount,
        degradedCount: applied.degradedCount || 0,
        unresolvedCount: applied.unresolvedCount || 0,
        highlightReasonCodes: applied.highlightReasonCodes || [],
        hiddenPresentationCount: applied.hiddenPresentationCount,
        presentationDensity: applied.presentationDensity,
        hiddenFamilyIds: applied.hiddenFamilyIds,
        familyCounts: applied.familyCounts,
        presentationModeCounts: applied.presentationModeCounts
    };
    scheduleArticleWorkspaceArtifactsSave({ immediate: true });
    return { ...applied, ...filtered };
}

function closeLlmFeedbackPopover() {
    document.getElementById('sci-llm-feedback')?.remove();
    document.getElementById('sci-highlight-context-popover')?.remove();
}

async function recordLlmFeedback(
    mark, userAction, correctedCategoryId = '', targetCategoryId = ''
) {
    const sample = llmFeedbackByMark.get(mark);
    if (!sample) return;
    const target = (sample.categories || []).find(item =>
        item.categoryId === targetCategoryId
    );
    const response = await chrome.runtime.sendMessage({
        type: 'LLM_RECORD_FEEDBACK',
        sample: {
            ...sample,
            categoryId: target?.categoryId || sample.categoryId,
            confidence: target?.confidence ?? sample.confidence,
            reasonZh: target?.reasonZh || sample.reasonZh,
            userAction,
            correctedCategoryId
        }
    });
    if (!response?.success) {
        showLlmPageStatus(response?.error?.message || '反馈保存失败', 'error');
        return;
    }

    mark.classList.remove('feedback-accepted', 'feedback-rejected', 'feedback-corrected');
    mark.classList.add(`feedback-${userAction}`);
    mark.dataset.feedback = userAction;
    closeLlmFeedbackPopover();
    showLlmPageStatus(
        response.data.suggestExport
            ? '已积累多篇已确认语料，可在 API 设置页导出语料或生成离线规则'
            : '反馈已保存到本地语料库',
        'success'
    );
    setTimeout(() => showLlmPageStatus(null), 4500);
}

function showLlmFeedbackPopover(mark) {
    showHighlightContextPopover(mark);
}

// Manual annotation UI: start
const MANUAL_MORE_RENDER_LIMIT = 40;
const MANUAL_UNRESOLVED_RENDER_LIMIT = 20;
const MANUAL_CONTEXT_CATEGORY_LIMIT = 100;
const MANUAL_FORBIDDEN_SCAN_LIMIT = 600;
const MANUAL_UI_SELECTOR = [
    '#sci-manual-toolbar', '#sci-highlight-context-popover', '#sci-manual-status',
    '#sci-reading-panel', '#sci-review-outline-panel', '.sci-figure-walkthrough',
    '.sci-figure-badge', '[data-sci-plugin-ui]'
].join(',');
const MANUAL_BLOCKED_SELECTOR = [
    'input', 'textarea', 'select', 'option', 'button', 'pre', 'code',
    '[contenteditable]:not([contenteditable="false"])', '[role="textbox"]'
].join(',');
const MANUAL_CLEAR_COMPLETION_TYPE = 'ANNOTATION_CLEAR_DOCUMENT';
function createContentWorldNonce(cryptoValue = globalThis.crypto) {
    let random = '';
    try {
        if (typeof cryptoValue?.randomUUID === 'function') {
            random = cryptoValue.randomUUID.call(cryptoValue);
        } else if (typeof cryptoValue?.getRandomValues === 'function') {
            const bytes = new Uint8Array(16);
            cryptoValue.getRandomValues(bytes);
            random = Array.from(bytes, value => value.toString(16).padStart(2, '0')).join('');
        }
    } catch (_) {}
    const normalized = typeof random === 'string'
        ? random.replace(/[^a-f0-9]/giu, '').toLowerCase().slice(0, 64) : '';
    if (normalized.length < 32) {
        throw new Error('CONTENT_WORLD_NONCE_UNAVAILABLE');
    }
    return normalized;
}

function nextManualDocumentEpochState(previous, prepared, lifecycleGeneration) {
    const own = (value, key) => {
        if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
            return undefined;
        }
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) {
            return undefined;
        }
    };
    const text = (value, maximum) => typeof value === 'string'
        ? value.normalize('NFKC').replace(/[\u0000-\u001f\u007f]/gu, '')
            .trim().slice(0, maximum)
        : '';
    const record = own(prepared, 'record');
    const identity = [
        text(own(prepared, 'documentId'), 200),
        text(own(record, 'documentHash'), 300),
        text(own(record, 'canonicalUrl'), 2000)
    ];
    const lifecycle = Number(lifecycleGeneration);
    const identityKey = identity.every(Boolean) ? JSON.stringify(identity) : '';
    if (!identityKey || !Number.isSafeInteger(lifecycle) || lifecycle < 0) {
        return { documentEpoch: 0, identityKey: '', lifecycleGeneration: 0 };
    }
    const previousEpoch = Number(own(previous, 'documentEpoch'));
    const previousIdentity = text(own(previous, 'identityKey'), 2600);
    const previousLifecycle = Number(own(previous, 'lifecycleGeneration'));
    if (Number.isSafeInteger(previousEpoch) && previousEpoch > 0 &&
        previousIdentity === identityKey && previousLifecycle === lifecycle) {
        return previous;
    }
    return {
        documentEpoch: Number.isSafeInteger(previousEpoch) && previousEpoch > 0
            ? Math.min(2147483647, previousEpoch + 1) : 1,
        identityKey,
        lifecycleGeneration: lifecycle
    };
}

const contentWorldNonce = createContentWorldNonce();
let manualDocumentEpochState = {
    documentEpoch: 0, identityKey: '', lifecycleGeneration: 0
};

function manualDocumentExecutionProof() {
    return {
        contentWorldNonce,
        documentEpoch: Number(manualDocumentEpochState.documentEpoch) || 0
    };
}

function currentManualDocumentExecutionState() {
    const executionProof = manualDocumentExecutionProof();
    return {
        documentId: String(currentManualDocument?.documentId || ''),
        documentHash: String(currentManualDocument?.record?.documentHash || ''),
        canonicalUrl: String(currentManualDocument?.record?.canonicalUrl || ''),
        contentWorldNonce: String(executionProof.contentWorldNonce || ''),
        documentEpoch: Number(executionProof.documentEpoch) || 0,
        title: String(currentManualDocument?.record?.title || document.title || ''),
        annotationCount: currentManualDocument?.record?.annotations?.length || 0,
        unresolvedCount: currentManualUnresolved.length
    };
}

function sameManualDocumentExecutionState(left, right) {
    return Boolean(left && right &&
        String(left.documentId || '') && left.documentId === right.documentId &&
        String(left.documentHash || '') && left.documentHash === right.documentHash &&
        String(left.canonicalUrl || '') && left.canonicalUrl === right.canonicalUrl &&
        /^[a-f0-9]{32,64}$/u.test(String(left.contentWorldNonce || '')) &&
        left.contentWorldNonce === right.contentWorldNonce &&
        Number.isSafeInteger(Number(left.documentEpoch)) && Number(left.documentEpoch) > 0 &&
        Number(left.documentEpoch) === Number(right.documentEpoch));
}

function normalizeManualReprepareExpectedIdentity(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    let prototype;
    try { prototype = Object.getPrototypeOf(value); } catch (_) { return null; }
    if (prototype !== Object.prototype && prototype !== null) return null;
    const own = key => {
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) { return undefined; }
    };
    const text = (key, maximum) => typeof own(key) === 'string'
        ? own(key).normalize('NFKC').trim().slice(0, maximum) : '';
    const normalized = {
        documentId: text('documentId', 200),
        documentHash: text('documentHash', 300),
        canonicalUrl: text('canonicalUrl', 2000),
        contentWorldNonce: text('contentWorldNonce', 64).toLowerCase(),
        documentEpoch: Number(own('documentEpoch')),
        operationNonce: text('operationNonce', 160)
    };
    if (!normalized.documentId || !normalized.documentHash || !normalized.canonicalUrl ||
        !/^[a-f0-9]{32,64}$/u.test(normalized.contentWorldNonce) ||
        !Number.isSafeInteger(normalized.documentEpoch) || normalized.documentEpoch < 1 ||
        !/^[A-Za-z0-9._:-]{12,160}$/u.test(normalized.operationNonce)) return null;
    return normalized;
}

async function reinitializeManualAnnotationsAfterCommit(expectedIdentity, dependencies = {}) {
    const capture = typeof dependencies.capture === 'function'
        ? dependencies.capture : currentManualDocumentExecutionState;
    const disable = typeof dependencies.disable === 'function'
        ? dependencies.disable : disableManualAnnotationUi;
    const initialize = typeof dependencies.initialize === 'function'
        ? dependencies.initialize : initializeManualAnnotationUi;
    const prepare = typeof dependencies.prepare === 'function'
        ? dependencies.prepare : prepareManualDocument;
    const expected = normalizeManualReprepareExpectedIdentity(expectedIdentity);
    if (!expected) throw new Error('MANUAL_REPREPARE_TARGET_MISMATCH');
    const before = capture();
    if (!sameManualDocumentExecutionState(before, expected)) {
        throw new Error('MANUAL_REPREPARE_TARGET_MISMATCH');
    }
    disable();
    initialize();
    await prepare({ force: true });
    const after = capture();
    if (!sameManualDocumentExecutionState(after, expected)) {
        throw new Error('MANUAL_REPREPARE_TARGET_MISMATCH');
    }
    return { success: true, ...after, operationNonce: expected.operationNonce };
}

const manualUiLifecycle = ManualAnnotationUiHelpers.createManualUiLifecycle();
